/* ⛔ GENERATED by kit/build.mjs from i18n/vi.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">MIDI đúng phong cách,</span> <span class=\"hl-bright\">ngay trong DAW của bạn.</span>","index.0e16857e":"Trống, melody, melody đối, 808, hợp âm và cả bản phối trọn bài — tạo theo phong cách của những nghệ sĩ cụ thể, dưới dạng MIDI nguyên bản, <strong>theo tông và tempo của chính dự án bạn</strong>. Miễn phí, ngoại tuyến và 100% không AI.","hero.chipStandalone":"Ứng dụng độc lập","hero.chipWeb":"Web","hero.chipLinux":"Linux (trình chỉnh sửa đang hoàn thiện)","index.a9e41a1f":"Tình hình — bây giờ nó là một plugin","index.4c860bcf":"Freally MIDI Master khởi đầu là một ứng dụng máy tính; <strong>v0.2.0</strong> chính là bản đó. Từ <strong>ngày 29 tháng 7 năm 2026, ứng dụng máy tính đã ngừng</strong> — không còn được dựng hay phát hành. Cái đã cài vẫn chạy; chỉ là không tìm thấy bản cập nhật nữa.","index.986fa10d":"Giờ nó là một <strong>plugin CLAP, còn VST3 và AU được chiếu ra từ đó</strong> — không vì bản thân định dạng, mà vì một plugin được đưa tempo, nhịp và đầu phát của phần mềm chủ. Mẫu được tạo ra rơi vào đúng bài bạn đang viết, chứ không phải vào cái tempo mà nghệ sĩ tình cờ được ghi ở đó.","index.e46c4677":"Nó nạp và tạo được trong <strong>Ableton Live&nbsp;12</strong> (VST3) và <strong>FL&nbsp;Studio</strong> (CLAP). Reaper, Bitwig và Logic thì chưa thử. Bản độc lập chạy đúng plugin đó trong cửa sổ riêng, không cần DAW nào.","see.title":"Trông nó thế nào","see.intro":"Plugin khi đang chạy: một giai điệu được tạo cùng bàn phím bạn chơi nó, và cả một bản phối trên dòng thời gian.","features.0cdb36f4":"Freally MIDI Master với một melody trap vừa tạo: dãy pad trống ở trên, khung piano roll và làn lực nhấn của nó, bốn clip Re-Dream bên dưới, và bàn phím trên màn hình ở dưới cùng.","features.1ef3563d":"Một melody trap vừa tạo, làn lực nhấn của nó, bốn bản Re-Dream của nó, và bàn phím để bạn chơi nó vào.","features.dacd8e46":"Chế độ Bài hát: bản phối 56 ô nhịp trên dòng thời gian, với các đoạn INTRO, PHIÊN KHÚC, ĐIỆP KHÚC và OUTRO cùng một clip sửa được cho mỗi phần — trống, hợp âm, melody và melody đối — mỗi clip mang thẻ MIDI và Âm thanh riêng.","features.6fe61d69":"Chế độ Bài hát: cả một bản phối trên dòng thời gian bạn có thể sửa, mỗi phần một clip, mỗi clip mang MIDI và âm thanh riêng để kéo ra.","home.inside.title":"Bên trong có gì","index.92530b36":"Nghệ sĩ, không phải thể loại","index.420c17ef":"Hầu hết các bộ tạo đều nghĩ theo thể loại. «Trap» không phải là «Metro Boomin», và chẳng công cụ phổ thông nào từng nghe tới OsamaSon. Nhập một cái tên và bạn có những mẫu mang đúng dấu ấn thật của nghệ sĩ đó.","index.e6a1356b":"Nó đi theo DAW của bạn","index.bab9531a":"Plugin đọc tempo và nhịp của phần mềm chủ trong từng khối, nên một bản trap viết ở 140 sẽ ra ở 92 trong một dự án 92&nbsp;BPM. Ghim một tempo và cái của bạn thắng.","index.4a2c8227":"Năm bộ tạo, cộng thêm chế độ Bài hát","index.bd395814":"Trống, melody, melody đối, bassline và hợp âm — cộng thêm chế độ Bài hát, không phải bộ tạo thứ sáu mà là một bản phối lấp đầy cả năm.","index.04c8fb28":"Nghệ sĩ nào cũng có tâm trạng","index.efa5276f":"Chọn một tâm trạng và ở lại đó, hoặc để <em>Bất kỳ</em> và mỗi lần nhấn sẽ đi khắp dải của nghệ sĩ đó. Một nghệ sĩ viết hơn một kiểu đĩa, và không hạt giống nào có thể bước qua giữa các kiểu ấy.","index.276d670e":"Dựng một phong cách của riêng bạn","index.84153fc4":"Bắt đầu từ bất kỳ nghệ sĩ nào, chỉnh đúng phần bạn quan tâm rồi lưu lại — nó nằm trong danh mục phong cách cạnh những cái có sẵn và hoạt động y như thế, vì nó cũng là một thứ như vậy. Gắn sao cho những bản thu bạn thích và nó khớp một phong cách vào chúng.","index.5a9ab055":"Các nốt rơi xuống track","index.06309989":"Không có tệp nào phải kéo, không có thư mục nào phải tìm. Plugin xuất MIDI ngay chỗ bạn cắm nó vào, theo thời gian của chính phần mềm chủ.","index.191153d2":"Tái lập được bằng hạt giống","index.3bb0362b":"Mỗi lần tạo đều có một hạt giống. Sao lại, dán vào, và bạn có đúng cái beat đó trở lại — trên bất kỳ máy nào, vào bất kỳ ngày nào. Tính tất định do bộ kiểm thử ép buộc.","index.f52c92c0":"Không AI, không tài khoản, không đám mây","index.21393e5c":"Không mô hình, không dữ liệu huấn luyện, không suy luận và không gọi mạng trong lúc tạo. Không đăng nhập và không đo lường từ xa. Mọi thứ diễn ra trên máy bạn — kể cả «huấn luyện phong cách của riêng bạn», vốn đo những bản thu bạn giữ lại rồi ghi các con số trở lại chứ không học gì cả. Một bản dựng có AI hay có client HTTP ở bất kỳ đâu trong phần phụ thuộc sẽ không qua được.","index.7f44a4fa":"Con đường tới 1.0","index.99276787":"Mỗi bản dựng mang tới trọn một khả năng. Không có gì ra đời nửa vời.","ladder.rung.v0.3.0":"Chuyển hướng sang plugin. CLAP, còn VST3 và AU được chiếu ra từ đó. Nạp được trong Ableton và FL Studio.","ladder.rung.v0.4.0":"Hoàn tác không giới hạn. Mỗi thay đổi trong buổi làm việc chỉ cách một lần nhấn để lùi lại — không giới hạn độ sâu.","ladder.rung.v0.5.0":"Nó phát ra âm thanh. Một bộ sampler phía sau các bộ tạo, các one-shot của riêng bạn trên bất kỳ phần nào, và một bộ chạy phát ngay trong plugin.","ladder.rung.v0.5.5":"Nó chơi một nhạc cụ. Một bộ tổng hợp phía sau mỗi phần, một thư viện gốc 2.729.088 âm thanh bạn có thể lần theo nhạc cụ và thể loại, một bộ dựng sample pack, và một bàn phím có thể chơi bất cứ lúc nào.","ladder.rung.v0.5.7":"Một thư viện đồ sộ, cực kỳ chân thực. Hai mươi bốn động cơ tổng hợp mới và 750 nhạc cụ mới — tổng 975, từ đại dương cầm và các nhóm dây kéo cho tới những mạch analog được mô hình hoá — mỗi cái đều đo lại theo vật thật mà nó mang tên. 1.614.600 âm thanh, mà trên ổ đĩa bạn vẫn chưa có một tệp nào.","ladder.rung.v0.6.0":"Thư viện mẫu âm của bạn. Một cây thư mục có nghe thử, mục yêu thích gắn sao, kéo vào pad và phát ngược — và thả một tệp MIDI vào thì nó tự tìm ra trong đó có những phần nào.","ladder.rung.v0.7.0":"Bản phối, giống như trong DAW. Các clip vẽ từ chính nốt của mình, thu phóng, chọn nhiều, cắt và nhân bản — và kéo cả bài ra ngoài, mỗi phần một track.","ladder.rung.v0.8.0":"67 thể loại, 2.000 nghệ sĩ. Danh mục phong cách đầy đủ — dòng ngầm cạnh dòng chính — mỗi mục là một mô hình phong cách viết tay. 67 thể loại đã viết xong và 1.250 nghệ sĩ cùng nhà sản xuất cũng vậy; phần còn lại đang được mã hoá từ nghiên cứu, từng tập một.","ladder.rung.v0.9.0":"Hoàn thiện và gia cố. Mọi trạng thái đều được thiết kế và mọi tình huống biên đều được xử lý: khả năng truy cập, HiDPI, an toàn khi sập, khởi động lạnh dưới ba giây.","ladder.rung.v1.0.0-beta":"Đủ tính năng. Mọi thứ 1.0 hứa, cộng thêm các phòng cộng tác và Freally MixSir, người bạn đồng hành trên điện thoại. Vẫn chưa có tải về — đây là bản được thử bằng tay.","ladder.rung.v1.0.0RC":"Bản ứng viên phát hành. Re-Dream tới — mỗi lần tạo đều đến dưới dạng bốn: bản thu bạn có cộng ba bản được mơ ra sau nó, nghe thử ngay trong track trước khi một bản thay vào phần đó. Rồi tới lượt thử bằng tay, chạy từ đầu tới cuối trên máy thật trong một DAW thật.","ladder.rung.v1.0.0":"Mở tải xuống. Cả năm bộ tạo cộng chế độ Bài hát, các phòng cộng tác và MixSir, mọi định dạng, trên cả ba nền tảng. Bản dựng đầu tiên ai cũng cài được — sau một lượt tối ưu, một lượt tinh giản, một lượt duyệt mã và một lượt duyệt an ninh, với cả hai bộ chạy tích hợp liên tục tự dựng đều xanh.","index.daba7f83":"<strong>Hiện chưa có gì để tải về.</strong> <strong>Tiếp theo là v1.0.0RC</strong>, và nó đang được thử bằng tay ngay lúc này — mọi phần mềm chủ, mọi hệ điều hành, và những thứ không bộ kiểm thử nào phán xét được. Một plugin chạy nửa vời trong phiên làm việc của ai đó còn tệ hơn là không có, nên nó chỉ ra mắt khi ma trận ấy xanh, không sớm hơn.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","index.25a8716e":"Động cơ dựa trên quy tắc, không phải được huấn luyện","index.644f2e23":"Trong sản phẩm này <strong>không có AI</strong>. Không mô hình, không dữ liệu huấn luyện, không suy luận, không gọi mạng khi tạo. Động cơ là mã thủ tục tất định, đọc những tham số phong cách viết tay rút ra từ nghiên cứu đã công bố. Đó là một kiến trúc pháp lý ngang với kiến trúc kỹ thuật: ở đây không có MIDI sao chép, không có âm thanh lấy mẫu, không có bản ký âm đĩa của ai, và không có tính năng nào tái tạo một bài cụ thể. Tên nghệ sĩ chỉ là cách gọi mô tả phong cách.","index.2419a115.t":"Âm nhạc bạn làm ra bằng nó là của bạn","index.2419a115.b":"Không phí bản quyền và không bắt buộc ghi công. Bản thân Freally MIDI Master là phần mềm độc quyền, Bảo lưu mọi quyền, và mã nguồn của nó là riêng tư — bạn không được phân phối lại nó. Nó <em>không</em> phải mã nguồn mở.","honest.names.title":"Tên gọi chỉ mô tả phong cách","index.7e9d277b":"Tên nghệ sĩ và nhà sản xuất trong Freally MIDI Master là cách gọi mô tả một phong cách âm nhạc, không hơn. Không hàm ý và không tuyên bố bất kỳ sự liên kết, chứng thực hay quyền tác giả nào. Mọi mẫu đều được tạo theo thủ tục từ các tham số phong cách viết tay — không sao chép MIDI, âm thanh hay dữ liệu từ bất kỳ bản thu nào. Mọi thương hiệu và tên gọi thuộc về chủ sở hữu tương ứng. <a href=\"legal/disclaimer.md\">Đọc toàn bộ tuyên bố miễn trừ</a>.","index.cf01481f":"Quyền riêng tư","index.a4c6de24":"Không tài khoản. Không đo lường từ xa. Không có gì về bạn, về dự án hay về thành quả của bạn được truyền đi bao giờ. Tạo, phát, nhập và xuất đều hoàn toàn cục bộ.","index.6a3c2dd2.t":"Plugin không mở bất kỳ kết nối đi ra nào","index.6a3c2dd2.b":"Hai cái từng có — kiểm tra cập nhật khi khởi động và báo cáo sập tuỳ chọn — thuộc về ứng dụng máy tính và đã bị bỏ cùng nó. Plugin do người cài plugin cài và cập nhật. Được ép bằng hai cửa dựng chứ không phải hứa: <strong>không có client HTTP nào được biên dịch vào plugin</strong> — điều này vẫn đúng, vì dịch vụ cộng tác do một chương trình riêng chạm tới, chứ không bao giờ là plugin mà DAW của bạn nạp — và bản thân giao diện cũng được chạy hết trong mỗi lần commit và sẽ thất bại nếu thử gửi dù chỉ một yêu cầu ra khỏi máy. Báo cáo sập được ghi lên ổ đĩa của bạn và không bao giờ gửi đi đâu.","index.1497b93b.t":"Ứng dụng web được gửi qua mạng; còn thứ bạn làm ra thì không","index.1497b93b.b":"Một trang phải được tải về — bản thân ứng dụng và dữ liệu phong cách mà nó tạo dựa trên. Chỉ có thế. Việc tạo chạy trên máy bạn, trong trình duyệt bạn; các beat, các hạt giống và mọi thứ bạn nhập vào đều ở đó và không bao giờ được tải lên. Sau một lần ghé, thẻ vẫn chạy khi tắt mạng, và như vậy còn gần với ngoại tuyến hơn phần lớn phần mềm làm được.","index.40df2f36.t":"Cộng tác là ngoại lệ duy nhất, và chỉ khi bạn dùng nó","index.40df2f36.b":"Các phòng nối máy bạn trực tiếp tới những người bạn mời. Nếu bạn lưu ai đó làm bạn bè, một dịch vụ nhỏ có thể cho bạn biết khi nào họ trực tuyến — và nó không được kể điều gì đáng giá: một khoá thay đổi mỗi vài phút, và một địa chỉ được mã hoá bằng bí mật chỉ hai bạn giữ. Nó không đọc được, không liệt kê được ai đang ở đó, và không suy ra được ai biết ai. Tắt nó đi, hoặc đừng bao giờ lưu bạn bè, thì bạn dán một mã thay thế — mà các phòng vốn vẫn chạy theo cách đó.","index.b5d5c2d0.t":"Một điều sắp tới, nói ngay bây giờ thay vì lúc nó ra","index.b5d5c2d0.b":"Tính năng cộng tác — các phòng, đang phát triển và hôm nay không có gì cài nó — cần biết địa chỉ công khai của máy bạn trước khi hai người có thể kết nối trực tiếp, và một máy chủ STUN tồn tại đúng để làm việc đó. Khi nó tới, mở hay vào một phòng sẽ liên lạc với một máy chủ như vậy; bản dựng này nêu tên Cloudflare và Google. Một máy chủ như thế chỉ biết rằng có địa chỉ nào đó đang dùng một ứng dụng WebRTC — không biết bạn nói với ai, cũng không biết bạn gửi gì — và không có gì được liên lạc cho tới khi bạn mở hoặc vào một phòng. Câu ở trên vẫn đúng với plugin đúng như nó xuất xưởng hôm nay.","site.tagline":"MIDI đúng phong cách, được tạo ngay trên track bạn đang làm.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Âm nhạc bạn làm ra bằng nó là của bạn, không phí bản quyền và không bắt buộc ghi công.","features.512c7b09":"Bộ tạo MIDI đầy đủ nhất từng được dựng — và nó không tốn gì cả.","features.d19d4e76":"2.413 phong cách nghệ sĩ và nhà sản xuất. 1.648 nhạc cụ. Hơn 96 triệu bản thu khác nhau cho mỗi phần. Biến bất kỳ tệp âm thanh nào thành MIDI. Mơ lại bất kỳ ý tưởng nào thành bốn. Phối trọn một bài. <strong>Mọi tính năng, cho mọi người, hiện miễn phí.</strong>","features.5e30071b":"Mọi con số ở đây đều đếm từ sản phẩm xuất xưởng và bộ kiểm thử của nó. Không có gì là ước lượng, và không có gì làm tròn lên.","featuresPage.numbers.models":"mô hình phong cách","featuresPage.numbers.artists":"nghệ sĩ","featuresPage.numbers.producers":"nhà sản xuất","featuresPage.numbers.instruments":"nhạc cụ","featuresPage.numbers.takes":"bản thu cho mỗi phần","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.price":"giá hiện nay","features.2fb7a96e":"Hiện nó miễn phí. Tất cả.","features.6b604c8e":"Mọi tính năng, cho mọi người. Không tầng trả phí, không khoá bản quyền, không mua trong ứng dụng, không đăng ký định kỳ, không bản thử hết hạn, không bản «Pro» giữ những phần hay làm con tin. Điều đó được ghi trong thoả thuận bản quyền của phiên bản này: <em>«Phần mềm được cung cấp miễn phí, đầy đủ.»</em> <strong>Và âm nhạc bạn làm ra bằng nó là của bạn</strong>, không phí bản quyền và không bắt buộc ghi công.","features.a5a8c798":"Tính năng chủ lực","features.65a59ac5":"Tìm một cái tên, không phải một thể loại","features.177ce0e6":"2.413 nghệ sĩ, nhà sản xuất và thể loại trong một ô — qua cả tên gọi khác và bất chấp lỗi chính tả. Trước khi bạn nhấn bất cứ gì, nó đã cho biết lựa chọn ấy <em>làm</em> gì: thời kỳ, dải tempo, tông mà nó nghiêng về, các tâm trạng nêu tên, và nó viết những phần nào, không viết phần nào. Một nghệ sĩ không viết melody đối sẽ nói ra, thay vì trả lời thẻ đó bằng im lặng.","features.c7e63f3a":"Re-Dream — cùng một ý tưởng, khác đi","features.b9301e2e":"Tung lại cho bạn một ý tưởng khác. Một <strong>Re-Dream</strong> cho bạn cùng ý tưởng đó, khác đi. Mỗi lần tạo đến dưới dạng bốn — bản thu bạn có, cộng ba bản được mơ ra sau nó — và bạn nghe từng bản <em>trong track của mình</em>, trên nền trống và 808 của mình. Một Re-Dream giữ <strong>79%</strong> các điểm khởi âm của bản gốc, trong khi ba hạt giống mới chỉ giữ 35%. Đó là một cửa trong bộ kiểm thử, không phải một lời quảng cáo. Nó cũng dùng được với tệp: chọn một <code>.mid</code> trong trình duyệt và giá đỡ sẽ nạp từ đó thay vì từ một lần tạo.","features.a4d9cbed":"Bất kỳ tệp âm thanh nào cũng thành MIDI","features.5a6369dd":"Kéo <em>bất kỳ</em> sample nào — WAV, AIFF, FLAC, MP3, M4A, OGG — lên một bộ tạo và nó trở về dưới dạng nốt. Điểm khởi âm, tempo, chính độ dài của vòng lặp, cao độ và nội dung trống, tất cả đều đo được. Và mỗi phần đều nói <em>vì sao</em> nó được chuyển tới đó, nên một phán đoán sai chỉ là một cú nhấn để chuyển hướng chứ không phải điều bạn phát hiện muộn.","features.fdfc6809":"Năm bộ tạo và cả một bài hát","features.fbe4c84f":"Trống · Melody · Melody đối · Bassline · Hợp âm — cộng chế độ Bài hát, lấy một trong những cấu trúc <em>của chính</em> nghệ sĩ và vẽ nó lên một dòng thời gian bạn có thể sửa. Đổi độ dài, nhân bản, khoá cái bạn thích, tung lại một đoạn mà không động tới phần còn lại.","features.d4dc7d3d":"Nó cũng là một nhạc cụ","features.5c924fb6":"Một bộ tổng hợp đa âm với <strong>1.648 nhạc cụ trải trên 69 thể loại</strong>, và mỗi bộ tạo có tính du dương chơi nhạc cụ riêng của nó — bốn giọng cùng lúc, không phải một giọng dùng chung. Không cái nào là thư viện sample: mỗi âm thanh là một địa chỉ gồm năm số nguyên, nên toàn bộ chỉ là mấy con số trong tệp dự án của bạn.","features.3f42ac73":"Và bạn chơi được vào đó","features.b9fcfc0e":"Một bàn phím trên màn hình, các phím máy tính làm bàn phím thứ hai, và bộ điều khiển MIDI của riêng bạn với bộ lọc kênh, dịch giọng, quãng tám, dải uốn cao độ và đường cong lực nhấn. Nhấn ghi và thứ bạn chơi rơi vào clip của phần đó — một nốt giữ qua điểm cuối vòng lặp vẫn là <em>một</em> nốt, và ghi lại lần nữa là chồng thêm chứ không thay thế. Bánh xe cao độ uốn <strong>mọi</strong> nhạc cụ, kể cả những nhạc cụ mô hình hoá vật lý: các thành phần của một cái chuông và dây của một cây guitar đi theo nó, còn những phần không đi theo nốt — thân đàn violin, các formant của giọng người — thì ở đúng chỗ của chúng.","features.f3789702":"5.085 vòng lặp MIDI, do cùng động cơ ấy viết","features.68dac5bc":"Các gói gốc: melody, bassline, hợp âm, melody đối, vòng lặp trống và vòng lặp bộ gõ, theo thể loại. Đi qua chúng bằng ↑/↓ và mỗi cái sẽ phát ngay khi bạn tới. Kéo một cái lên bộ tạo thì nó rơi vào đó, chia đúng vào các phần; kéo ra ngoài thì nó vào DAW của bạn như một clip. Chín megabyte <em>nốt</em> — không phải một gigabyte bản thu của người khác, vì mỗi cái đều do bộ tạo và mô hình của chính chúng tôi viết.","features.99073b05":"Nó sẽ không đưa cho bạn đoạn hook của người khác","features.77e297a3":"Mỗi melody đều được sàng lọc qua một bảng các đường nét giai điệu nổi tiếng <em>trước khi bạn nghe nó</em>, và bản thu nào trùng sẽ bị bỏ và rút lại. Bảng chỉ chứa dấu vân tay một chiều và hoàn toàn không có dữ liệu nốt — dịch giọng một đoạn hook không giấu được nó, và trong sản phẩm không có gì do người khác viết.","features.05de2492":"Khoá lại, tung lại, lấy lại","features.8347a3e6":"Khoá cái bạn thích và tung lại phần còn lại — một làn đã khoá trở về từng nốt một, bạn nhấn Tạo bao nhiêu lần cũng vậy. Mỗi lần tạo có một hạt giống: sao lại, dán vào, lấy về. Và hoàn tác không giới hạn cho mọi thứ, vì một mục hoàn tác là các đầu vào chứ không phải các nốt.","features.5ec34078":"Không AI. Không một mô hình nào.","features.f28580e7":"Không phải hạn chế — đó là thiết kế. Quy tắc, phép đo và ngẫu nhiên có hạt giống từ trên xuống dưới, cùng một cửa dựng khước từ mọi phần phụ thuộc có thể lén mang một mô hình vào. Nó đem lại cho bạn tính tái lập, tính giải thích được và một nguồn gốc bạn bảo vệ được: không có gì được huấn luyện trên bản thu của ai, vì chẳng có gì được huấn luyện cả.","features.79dacbd4":"Đặt cạnh những bộ tạo MIDI hàng đầu","features.c9427ee1":"Tổng hợp từ bảng tính năng do từng sản phẩm tự công bố.","featuresPage.compare.feature":"Tính năng","features.3e8248e3":"Giá","features.97ef455a":"Hiện miễn phí","features.dc9d4584":"Có phí","features.8fde48f3":"Đăng ký định kỳ","features.a036b01a":"Phong cách nghệ sĩ / nhà sản xuất nêu tên","featuresPage.compare.legend.yes":"đầy đủ","featuresPage.compare.legend.no":"không có","features.a52b7c6e":"chỉ thể loại","featuresPage.compare.legend.partly":"một phần","features.37d67e95":"danh sách có giấy phép","features.88048f2f":"Trống <em>và</em> melody, bass, hợp âm, melody đối","features.a69f56a4":"cả năm","features.0f8398e4":"chỉ trống","features.5916033f":"Phối trọn bài trên một dòng thời gian sửa được","features.73ab2ff8":"<strong>Tệp âm thanh → MIDI</strong>, bất kỳ sample nào","features.400bace7":"nhận dạng","features.11963ece":"Tệp MIDI → chia thành năm phần, mỗi phần có lý do","features.cc1b6bf2":"<strong>Re-Dream</strong> — cùng một ý tưởng, khác đi","features.b21d091f":"biến hình","features.75f1827c":"Hạt giống tái lập được — dán vào là có lại","features.215a67ab":"Bộ tổng hợp tích hợp mà bạn cũng chơi được luôn","features.891ee051":"Sample của riêng bạn trên bất kỳ làn nào","features.1cc2b417":"Sàng hook — khước từ melody của người khác","features.ddfa7bdc":"Khoá cái bạn thích, tung lại phần còn lại","features.2cb5ea83":"Huấn luyện một phong cách trên những bản thu <em>bạn</em> gắn sao","features.dce5f5da":"không học máy","features.5a67578e":"Chạy hoàn toàn ngoại tuyến, không tài khoản, không đo lường từ xa","features.b3f15e02":"đám mây","features.ceec1655":"<strong>Không AI/học máy ở bất kỳ đâu</strong> — quy tắc kiểm toán được","features.b72eae1f":"kiểm ở mỗi lần push","features.716f8c55":"Phòng cộng tác trực tiếp","features.f75444a3":"18 ngôn ngữ","features.a2295f23":"Hoàn tác không giới hạn cho mọi thứ","features.036b5f21.t":"Bản một dòng","features.036b5f21.b":"Mọi sản phẩm khác trong bảng đó đều đòi bạn tiền để làm một phần những gì cái này làm. Cái này không đòi gì và làm tất cả.","features.3f4902cc":"So sánh được tổng hợp từ bảng tính năng công khai của từng sản phẩm; sản phẩm có thay đổi, và mọi đính chính đều được hoan nghênh.","features.d452e239":"Vì sao nó có hình dạng như hiện tại","features.87e13091":"Tái lập được","features.75b8dd39":"Cùng một hạt giống cho cùng những nốt, hôm nay và năm năm nữa. Không thứ gì được huấn luyện hứa được điều đó.","features.20690c04":"Giải thích được","features.8d02c9f7":"Mỗi lần tạo đều nói được tham số nào sinh ra nó, vì ở đó có một tham số chứ không phải một trọng số.","features.4fd9fc99":"Một nguồn gốc bạn bảo vệ được","features.489d6eaf":"Không có gì được huấn luyện trên bản thu của ai, vì chẳng có gì được huấn luyện cả. Kho nghiên cứu chỉ từng góp các phân phối — chưa bao giờ là dữ liệu nốt, chưa bao giờ là âm thanh.","features.0f211ed0":"Nó ở lại trên máy bạn","features.94aff5cf":"Không tài khoản, không đăng nhập, không đo lường từ xa, không đi vòng qua đám mây. Nó chạy trên máy bay. Sample, MIDI, phần bạn chơi và các dự án của bạn không bao giờ rời ổ đĩa — <strong>không một byte sample nào băng qua đường truyền</strong>, kể cả trong một phòng cộng tác.","features.e6a1356b":"Nó đi theo DAW của bạn","features.e3a8277a":"Plugin đọc tempo và nhịp của phần mềm chủ trong từng khối, nên một mẫu được tạo <em>cho bài của bạn</em> — bản trap viết ở 140 ra ở 92 trong một dự án 92 BPM. Tự ghim một tempo và cái của bạn thắng.","features.7142b88f.t":"Về con số 96 triệu ấy","features.7142b88f.b":"Nó được đo, không phải quảng cáo. Bộ kiểm thử kết xuất 200 hạt giống cho mỗi mô hình và đo được <strong>199 bản Re-Dream khác nhau trong 200 lần rút</strong> từ một bản thu duy nhất. Cả hai con số đều không cạn ở 200 mẫu, nên cả hai đều là <em>ngưỡng dưới</em>: ≥200 lần tạo × ≥199 Re-Dream ≈ 40.000 bản thu cho mỗi mô hình mỗi phần, và 40.000 × 2.413 mô hình là hơn 96 triệu — <em>cho mỗi phần</em>, trước khi bốn phần du dương kết hợp với nhau. Chúng tôi cố ý chỉ nêu ngưỡng dưới và không bao giờ nêu tổng: một con số tổng sẽ là ngưỡng trên mà mã không chứng minh được, và nó sẽ biến nguồn cảm hứng không cạn thành một danh mục mà bạn hình dung được điểm cuối.","features.21cc118f":"Những gì còn chưa tới","features.0b765e69":"Nói thẳng, vì một bảng tính năng che đi những chỗ thiếu thì không đáng đọc.","featuresPage.limits.title":"Chưa hoàn thành","features.3311e0fb":"<strong>Kéo ra ngoài trên macOS và Linux</strong> đã viết và đã bật nhưng chưa từng thả vào một DAW thật. Trên Windows thì có. Dù thế nào, xuất tệp vẫn chạy ở mọi nơi.","features.7a359bb4":"<strong>Phím tắt toàn cục, chia sẻ màn hình và máy ảnh</strong> trong các phòng cộng tác.","features.fa2456cd":"<strong>v1.0.0RC sắp ra mắt, và bản tải về đi cùng nó.</strong> Cho tới lúc đó, câu trả lời thật lòng cho câu hỏi «tải nó ở đâu» là <em>chưa có</em>.","documentation.ca365831":"Mọi thứ plugin làm, và cách nó quyết định chơi gì.","documentation.e4253178":"Định dạng & phần mềm chủ","documentation.e3843261":"Cài đặt","documentation.61c43d0a":"Vòng làm việc cốt lõi","documentation.40f89a05":"Danh mục phong cách","documentation.ba8c0def":"Tâm trạng","documentation.197723c7":"Phong cách của riêng bạn, và huấn luyện nó","documentation.bd31a893":"Các pad trống","documentation.f3aaedd4":"Trình duyệt sample","documentation.4a0779eb":"Thả một tệp MIDI vào","documentation.ec0e4ac2":"Các bộ tạo","documentation.c1e2865a":"Chế độ Bài hát","documentation.04770da9":"Nhạc cụ","documentation.c20403bd":"Âm thanh đã bounce","documentation.a70dab9e":"Đưa nó vào DAW của bạn","documentation.905e63d9":"Tempo, tông & tự đồng bộ","documentation.05bb0a4d":"Hạt giống & tính tái lập","documentation.e709e76f":"Cài đặt sẵn","documentation.9e2759d7":"Thư viện pattern","documentation.874a5339":"Các bản thu của bạn, và khoá một trống","documentation.b7a3d0f4":"Trạng thái phiên","documentation.26669547":"Phím tắt","documentation.148f83d6":"Bản độc lập","documentation.0d1db92c":"Quyền riêng tư & mạng","documentation.9091f25a":"Những câu hỏi người ta thực sự hỏi","documentation.70252a52":"Báo lỗi","documentation.fef8e889":"Giấy phép","documentation.1f0efc8f":"Freally MIDI Master là một plugin <strong>CLAP</strong>. VST3 và AU được chiếu ra từ nó chứ không được triển khai riêng, và đó là điều giúp nó nạp được trong những phần mềm chủ không hỗ trợ CLAP.","documentation.3960ec4c":"Phần mềm chủ","documentation.041a5dec":"Định dạng","documentation.bae7d5be":"Trạng thái","documentation.2a47e9fb":"Ableton Live 12","documentation.20a69fa8":"VST3","documentation.c21b9338":"Nạp được và tạo nhạc","documentation.3e592955":"FL Studio","documentation.51df4626":"CLAP","documentation.54e5b246":"Reaper · Bitwig · Logic","documentation.7fa841a9":"CLAP / VST3 / AU","documentation.864e8b1c":"Chưa thử nghiệm","documentation.6141642e":"Không có DAW","documentation.1d10323c":"Độc lập","documentation.fdd933a8":"Chạy trong cửa sổ riêng","documentation.7d883e08":"Plugin viết nốt lên track mà bạn chèn nó vào <strong>và tự tạo ra âm thanh</strong> — trống qua bộ kit của nó, và mỗi phần có tính du dương qua nhạc cụ riêng. Bạn không phải định tuyến nó đi đâu để nghe.","documentation.a8d36300":"<strong>Tải về mở ở bản 1.0.</strong> Trước đó không có trình cài đặt, không bản beta và không bản xem trước — một plugin chạy nửa vời trong phiên làm việc của ai đó còn tệ hơn là không có, nên nó chỉ ra mắt khi ma trận QA xanh trên mọi phần mềm chủ và mọi hệ điều hành.","documentation.c5ebdb97":"Nơi các định dạng nằm, khi 1.0 ra mắt:","documentation.de8aa862":"Hệ điều hành","documentation.26d9c28d":"Windows","documentation.e59a23ba":"<code>%COMMONPROGRAMFILES%\\CLAP</code>","documentation.72e6c218":"<code>%COMMONPROGRAMFILES%\\VST3</code>","documentation.cd6fdcbf":"macOS","documentation.75bb9363":"<code>~/Library/Audio/Plug-Ins/CLAP</code>","documentation.9e8fc2e4":"<code>~/Library/Audio/Plug-Ins/VST3</code>","documentation.83ad8510":"Linux","documentation.f81f810e":"<code>~/.clap</code>","documentation.48df6728":"<code>~/.vst3</code>","documentation.fdbefea1":"<strong>Chọn một người.</strong> Gõ một cái tên vào ô danh mục phong cách — nghệ sĩ hay thể loại đều được.","documentation.98f5460e":"<strong>Tạo.</strong> Mẫu được dựng theo tempo và tông của dự án bạn.","documentation.e1f3b866":"<strong>Nghe nó.</strong> Nhấn phát trong DAW — các nốt đã nằm sẵn trên track.","documentation.d9b0f0a8":"<strong>Tung lại hoặc giữ.</strong> Mỗi lần tạo mang một hạt giống bạn có thể sao chép lại.","documentation.f8d5c8c2":"Hầu hết các bộ tạo MIDI đều nghĩ theo <em>thể loại</em>. «Trap» không phải là «Metro Boomin», và chẳng công cụ phổ thông nào từng nghe tới OsamaSon. Freally MIDI Master nghĩ theo <strong>nghệ sĩ</strong> — mỗi người là một tập tham số phong cách viết tay mô tả ngữ pháp roll hi-hat, cách 808 trượt, độ swing, âm vực và bố cục các đoạn.","documentation.4f2277e8":"Bạn tìm họ bằng <strong>một ô gõ có tự hoàn thành</strong>. Bắt đầu gõ và nó thu hẹp dần theo từng chữ — trên cả danh mục dòng chính, danh mục dòng ngầm, tên gọi khác và lỗi chính tả. Dừng giữa chừng rồi nhấp ra ngoài thì nó lấy kết quả khớp nhất, nên bạn không bao giờ bị bỏ lại mà chưa chọn gì. Nhấn vào mũi tên thay vì gõ và nó cho bạn xem tất cả.","documentation.a84eb15c":"Cùng một ô liệt kê <strong>cả nghệ sĩ lẫn thể loại</strong>, mỗi hàng cho biết nó là loại nào, nên bạn không bao giờ phải biết trước «UK Drill» là một người hay một phong cách. Chọn một mục và chi tiết của nó hiện ngay bên dưới — thời kỳ, các thể loại nó làm, <strong>dải tempo</strong> và tông nó nghiêng về, các tâm trạng nêu tên, và <strong>nó viết những phần nào, không viết phần nào</strong> — <strong>trước khi</strong> bạn nhấn Tạo. <strong>Thể loại là bộ lọc để duyệt, không phải đơn vị để tạo</strong> — dù bản thân một thể loại cũng là một mô hình phong cách thật và tự nó tạo được.","documentation.2e81e526":"Dòng cuối ấy quan trọng hơn vẻ ngoài của nó. Một nghệ sĩ không viết melody đối sẽ trả lời thẻ đó bằng <em>im lặng</em>, và như thế là đúng — họ không viết chúng, nên không có gì được bịa ra cho họ. Trước khi khung này nói rõ điều đó, cách duy nhất để biết là nhấn Tạo rồi nhìn chằm chằm vào một piano roll trống.","documentation.c67e0e46":"Tên nghệ sĩ <strong>chỉ là cách gọi mô tả phong cách</strong>. Không có gì trong bộ dữ liệu là MIDI sao chép, âm thanh lấy mẫu hay bản ký âm đĩa của ai.","documentation.b0e455fd":"Một nghệ sĩ không chỉ có một kiểu âm thanh. Bên cạnh nghệ sĩ là một <strong>tâm trạng</strong> — <em>dark</em>, <em>bounce</em>, <em>melodic</em> và <em>minimal</em> của trap; <em>dusty</em>, <em>jazzy</em> và <em>hard</em> của boom bap; <em>cowbell</em>, <em>memphis</em> và <em>brazilian</em> của phonk. Để ở <strong>Bất kỳ</strong> và mỗi lần nhấn sẽ đi khắp dải của nghệ sĩ đó; ghim một tâm trạng thì ở lại đó.","documentation.c4de4112":"Một tâm trạng là <strong>cùng một tác giả viết một kiểu đĩa khác</strong>, đúng như cách các nhà sản xuất mô tả danh mục tác phẩm của chính họ. Nó được áp dụng trước khi bất kỳ bộ tạo nào chạy, nên mọi phần đều tuân theo — không có cách nào để trống ở một tâm trạng còn melody ở tâm trạng khác.","documentation.4e322996":"<strong>Một nghệ sĩ chỉ đưa ra những tâm trạng mà nghệ sĩ đó thực sự có.</strong> Tâm trạng được kế thừa theo cùng dòng dõi như mọi thứ khác, nên không có đường nào để tâm trạng của nghệ sĩ này được đưa ra trên nghệ sĩ khác. Yêu cầu một tâm trạng mà phong cách không có thì nó sẽ nói thẳng bằng tên, thay vì lặng lẽ tạo một thứ khác.","documentation.8b53323c":"<strong>Quy trình riêng</strong> nằm trên cùng của thanh bên trái, trên mọi thứ khác. Bắt đầu từ bất kỳ nghệ sĩ hay thể loại nào, chỉnh dải tempo, độ swing, mật độ hi-hat, mật độ melody và các âm giai, rồi lưu dưới tên của riêng bạn. Nó xuất hiện trong danh mục phong cách với dấu <strong>Của bạn</strong> và tạo, khoá, tung lại, xuất y hệt một nghệ sĩ có sẵn — vì nó là cùng một loại thứ, theo cùng một định dạng.","documentation.63fa26a1":"Nó <strong>kế thừa mọi thứ bạn không thay đổi</strong>, kể cả những cải tiến mà nghệ sĩ bạn lấy làm gốc nhận được trong một bản phát hành sau. Một phong cách mới mở ra với các giá trị lấy từ beat đang có trên màn hình thay vì từ một biểu mẫu trống.","documentation.22b5f3cc":"Gắn sao cho những bản thu bạn thích trong lúc làm. Khi đã giữ đủ ba mươi bản, <strong>Huấn luyện</strong> sẽ khớp một phong cách vào chúng — mỗi ô nhịp bao nhiêu điểm khởi âm, âm vực nào, đường nét của dòng nhạc ra sao — rồi ghi các dải đó lại thành một mô hình phong cách bình thường. Các tệp <code>.mid</code> của riêng bạn cũng có thể làm tư liệu huấn luyện.","documentation.421a3d31":"<strong>«Huấn luyện» nghĩa là khớp số liệu, và trong đó không có học máy ở bất kỳ đâu.</strong> Không học gì từ âm nhạc của người khác, không có gì rời khỏi máy bạn, và một lần khớp chỉ lặp lại chính nó sẽ bị từ chối kèm lý do thay vì được lưu. Mức sàn ba mươi tồn tại để một phong cách mã hoá gu của bạn chứ không phải ý kiến của một hạt giống.","documentation.70a577ec":"<strong>Sample của bạn chỉ được sao chép nếu bạn bảo vậy.</strong> Một phong cách có thể giữ các one-shot bạn đã gán, để chúng vẫn phát sau khi bạn di chuyển hay xoá bản gốc. Điều đó nghĩa là có một bản sao thứ hai trên ổ đĩa, nên trình chỉnh sửa cho bạn biết bao nhiêu tệp và bao nhiêu megabyte trước khi có gì xảy ra — và ô đó mặc định không được đánh dấu. Tự việc lưu một phong cách không sao chép gì cả.","documentation.5d689d19":"Tám pad nằm ngang phía trên sân khấu, trên piano roll. Mỗi pad là một làn trống: tên của nó, thứ hiện đang nằm trên nó, và một chấm cho biết bạn có nghe được nó không — <strong>xanh lá là nghe được, đỏ là đã tắt tiếng</strong>.","documentation.86cb89b2":"Nhấn một pad để tắt hoặc bật tiếng nó. Nhấn <strong>Phát</strong> ở chính giữa phía trên của nó để nghe riêng âm thanh đó. <strong>Kéo một sample lên nó</strong> từ trình duyệt để đặt one-shot của riêng bạn vào đó, hoặc nhấp đúp để chọn một tệp. Nút trộn tung lại pad đó từ thư mục bạn đang duyệt, còn ✕ đặt lại âm thanh tích hợp.","documentation.aaa1fd33":"<strong>Tên làn của mỗi pad tự nó là một bộ chọn</strong> — đổi bất kỳ pad nào trong tám pad sang bất kỳ làn nào trong ba mươi bảy làn mà plugin có. Hai pad có thể dùng chung một làn, để bạn chồng lớp một snare; pad thứ ba thì bị từ chối. Bố cục của bạn được nhớ <strong>theo từng nghệ sĩ</strong>, nên quay lại một phong cách bạn đã dựng sẽ khôi phục các pad đúng như lúc bạn rời đi, cùng các sample bạn đã gán.","documentation.d25c3d2f":"<strong>Nó mở ở Danh mục</strong> — mỗi nơi một hàng, mỗi hàng cho biết trong đó có bao nhiêu, và bạn đi vào bên trong. Nhạc cụ và bốn Gói mở rộng gốc là các kệ của thư viện tích hợp; Gói trống chứa mười một bộ kit đi kèm và 407 one-shot của chúng; Gói gốc chứa 5.085 vòng lặp MIDI, theo từng gói. Bên dưới là <strong>+ Thêm thư mục</strong> và các thư mục bạn đã thêm, theo tên.","documentation.40db79d3":"<strong>Con số trên một hàng là cả kệ</strong>, không phải phần còn lại sau bộ lọc, nên nó không đổi khi bạn nhấn một chip lọc. Các hàng được xếp theo thứ tự chữ cái của ngôn ngữ bạn đang dùng, trong số mười tám ngôn ngữ. Một thư mục có ổ đĩa đã rút ra vẫn giữ chỗ của nó và được đánh dấu <em>Không khả dụng</em> bằng chữ chứ không chỉ bằng màu, và vẫn gỡ được — một nhà sản xuất rút ổ sample ra đâu có nghĩa là đã rời khỏi thư viện.","documentation.21e024db":"Bên trong một nơi, các mũi tên phía trên danh sách đi qua các thư mục, còn thanh đường dẫn nhảy thẳng tới một cấp. Thư viện của bạn trở lại vào lần sau bạn mở ứng dụng, dù có dự án hay không.","documentation.6324e27a":"<strong>Các phím mũi tên đi qua nó.</strong> <kbd>↑</kbd> và <kbd>↓</kbd> di chuyển giữa các hàng. Trên một thư mục, <kbd>→</kbd> mở nó và <kbd>←</kbd> đóng nó — còn trên một thư mục đã đóng, <kbd>←</kbd> đóng nhánh chứa nó, nên đó là một đường lùi ra. Trên một <em>tệp</em>, chính hai phím đó phát nó <strong>xuôi và ngược</strong>. Nghe thử không bao giờ khởi động hay dừng bộ điều khiển phát.","documentation.33491a5d":"<strong>Gắn sao cho bất cứ thứ gì</strong> — một sample, một one-shot hay một tệp MIDI. Ngôi sao nằm bên trái tên: chỉ có viền cho tới khi bạn nhấn, rồi thành màu vàng đặc. Các tệp gắn sao gom thành một danh sách dưới cây thư mục, và nhấp vào một tệp sẽ mở mọi thư mục từ gốc tới tệp đó để làm lộ nó ra. Nếu thư mục của nó không còn nằm trong số những thư mục bạn đã thêm, nó sẽ mở vị trí của tệp trong <strong>Windows Explorer hoặc Finder</strong> — nên một mục yêu thích luôn với tới được dù thư viện của bạn đã đổi khác thế nào. Bỏ sao là quên nó.","documentation.0a36b11f":"Trình duyệt có thể chiếm <strong>cả thanh bên</strong> khi bạn cần nhìn sâu, rồi trả lại. Âm thanh và MIDI được tách riêng có chủ đích: một tệp <code>.mid</code> không có dạng sóng để vẽ và không thể thả lên pad trống, và pad từ chối nó ngay trước khi bạn buông tay chứ không thất bại sau đó.","documentation.5811086b":"<strong>Nó chứa được một thư viện thật.</strong> Một thư mục có hai nghìn tệp mở nhanh như thư mục có bốn tệp, vì chỉ những hàng bạn thực sự nhìn thấy mới được vẽ — cuộn xuống và phần còn lại xuất hiện khi bạn tới. <strong>Gõ vào ô lọc</strong> và cây thư mục thu hẹp lại còn những gì khớp, giữ các thư mục dẫn tới đó; gõ tên một thư mục và bạn có mọi thứ bên dưới nó. Dòng bên dưới ô cho biết <em>những thư mục nào đã được tìm</em>, và nó nói đúng như vậy: plugin đọc từng thư mục một, nên bộ lọc với tới những thư mục bạn đã mở và không xa hơn. Một ô ngụ ý điều ngược lại sẽ là nói dối về những gì nó đã xem.","documentation.0c96cd67":"<strong>Rút ổ đĩa chứa một thư mục thư viện ra thì thẻ của nó sẽ báo như vậy</strong>, kèm nút <em>Kiểm tra lại</em> bên cạnh. Thư mục không bị gỡ khỏi thư viện của bạn — cắm ổ đĩa lại, nhấn nút đó, và cây thư mục vẫn ở đó. Trước đây, một thư mục như vậy chỉ đơn giản là không chịu mở, trông y hệt một thư mục trống.","documentation.3de3cadc":"<strong>Nghe trước đã.</strong> Chọn một tệp <code>.mid</code> và bảng sẽ liệt kê những gì có bên trong; nhấn <strong>Phát</strong> và nó vang lên — qua một nhạc cụ tích hợp đơn giản chứ không phải nghệ sĩ nào bạn tình cờ đang chọn, nên cùng một tệp ngày mai vẫn nghe y như vậy. Các làn trống được phát ra như những cú đánh chứ không như cao độ, vì số nốt của một làn trống cho biết pad nào kêu chứ không phải nó trầm tới đâu. Nó được dựng ở lần nhấn đầu tiên chứ không phải lúc bạn nhấp vào tệp, nên đi qua một thư mục vòng lặp bằng <kbd>↓</kbd> chẳng tốn gì. Nó không bao giờ động tới bộ điều khiển phát của dự án.","documentation.9acfff56":"Kéo một tệp <code>.mid</code> từ trình duyệt lên một <strong>bộ tạo</strong> và các nốt của nó rơi vào đó. Còn thả nó lên thẻ <strong>Bài hát</strong> thì cả tệp tới dưới dạng một bản phối — các đoạn chạy ngang phía trên, các phần xếp dọc bên cạnh — và nhấp vào bất kỳ ô nào sẽ mở clip đó trong bộ tạo của nó, y như khi đi sâu vào một bài hát được tạo. Không có gì bạn đang có bị ghi đè cho tới khi bạn chọn một ô.","documentation.7b266d93":"Một tệp nhiều lớp được <strong>tách thành bass, melody, melody đối, hợp âm và trống</strong>, và mỗi phần đều nói <strong>vì sao</strong> nó được chuyển tới đó — «trên kênh trống GM», «hợp âm — các nốt chồng lên nhau», «bè thấp nhất», «từ tên tệp». Một phán đoán sai chỉ là một cú nhấp để chuyển hướng chứ không phải điều bạn phát hiện sau hai ô nhịp.","documentation.d544549e":"<strong>Đặt tên cho tệp và nó sẽ nghe theo.</strong> Một tệp tên <code>…-Bass.mid</code> hoặc <code>…Drums.mid</code> sẽ được tin theo đúng tên, vì đó là bạn nói nó là gì chứ không phải plugin đoán. Điều này quan trọng hơn vẻ ngoài: nốt MIDI của một 808 cho biết <em>phím nào kích hoạt sample</em>, không phải nó trầm tới đâu, nên một bassline thường nằm ở âm vực melody và không phép đo nào phân biệt được nó với một lead chậm. Thứ duy nhất làm được là cái tên bạn đặt cho nó.","documentation.02646e58":"Clip nhập vào <strong>theo tempo của phiên làm việc</strong>. Phần lớn MIDI được xuất ra không mang tempo nào cả — con số trong tên tệp không nằm trong dữ liệu — và plugin sẽ không tự nhận một tempo mà nó không đọc được.","documentation.2528b54c":"<strong>Năm bộ tạo cho từng phần, cộng chế độ Bài hát.</strong> Chế độ Bài hát không phải bộ tạo thứ sáu — nó bày ra một bản phối và lấp đầy năm bộ kia.","documentation.fe06eb64":"Thẻ","documentation.f6222ac9":"Những gì nó tạo ra","documentation.764cb087":"<strong>Trống</strong>","documentation.d18ca618":"Kick, snare và off-snare, clap, hi-hat đóng và mở với ngữ pháp roll, ride, crash, tom, rim, snap, perc, shaker, tambourine, cowbell và woodblock — cộng thêm sub trượt. Nghệ sĩ dùng những cái nào là một phần của chính nghệ sĩ đó.","documentation.f973941a":"<strong>Melody</strong>","documentation.86e5726d":"Cấu trúc câu nhạc — vòng riff, hỏi/đáp, gọi/đáp, vòm dài — với xu hướng nghiêng về nốt hợp âm ở phách mạnh và các thủ pháp riêng của từng thể loại","documentation.4e420883":"<strong>Melody đối</strong>","documentation.c81554ab":"Tiếng vang quãng tám, tiếng vang chuông, arpeggio, câu lick đáp lại và pad ngân dài, đặt vào những khoảng trống của melody","documentation.3562e4d3":"<strong>Bassline</strong>","documentation.6763aa65":"Phần trầm, khoá theo hành vi sub của trống","documentation.677c857e":"<strong>Hợp âm</strong>","documentation.d7eb09d9":"Vòng hợp âm theo tông và âm giai của phiên","documentation.7c237ecf":"<strong>Bài hát</strong>","documentation.6d9aaa02":"Một bản phối lấp đầy năm phần ở trên — một chế độ, không phải một bộ tạo","documentation.ecfc86d6":"<strong>Cả năm đều tạo, và cả năm đều sửa được.</strong> Trống có lưới pad; melody, melody đối, bassline và hợp âm có piano roll. Một phong cách mà 808 <em>chính là</em> bassline của nó sẽ nói ra điều đó thay vì nhân đôi bằng một phần trầm thứ hai.","documentation.5acc0069":"Cao độ được chọn dưới dạng <strong>bậc âm giai</strong> rồi mới được chuyển thành nốt MIDI, nên việc giữ đúng tông là do cấu trúc chứ không phải được lọc ra sau đó.","documentation.eb60a3b0":"Nhấn Tạo trên thẻ <strong>Bài hát</strong> và bạn có cả một bản phối: một trong những cấu trúc bài hát của chính nghệ sĩ, mỗi phần mỗi đoạn một clip, và những đoạn chuyển khiến nó nghe ra một bản thu hoàn chỉnh — một hai phách lặng trước khi điệp khúc vào, một cú switch-up ở nửa sau, một đoạn outro nhỏ dần.","documentation.967c5bf5":"<strong>Một đoạn phát một clip lặp.</strong> Một phiên khúc mười sáu ô nhịp là một vòng lặp bốn ô nhịp phát bốn lần, đúng như khung xem bản phối của mọi DAW vẽ ra. Các đoạn cùng loại dùng chung một clip, vì phiên khúc 1 và phiên khúc 2 là cùng một beat — và switch-up tồn tại chính vì đó là quy tắc.","documentation.fb2dbad1":"Những gì bạn có thể làm","documentation.0c81abc8":"Cách","documentation.b78ea20d":"Đổi độ dài, nhân bản, xoá, sao chép/cắt/dán clip","documentation.f3887844":"Kéo một trong hai mép, nhấp đúp vào tiêu đề đoạn, và các phím tắt thông thường","documentation.b4f2f858":"Tạo lại một đoạn","documentation.462f801c":"<kbd>R</kbd>, hoặc con xúc xắc trên tiêu đề đoạn. Các clip đã khoá được để yên","documentation.6ae2c0bb":"Khoá một clip, một hàng hay cả một đoạn","documentation.d51e6c21":"Ổ khoá trên ô, trên hàng phần, hoặc trên tiêu đề đoạn","documentation.91c16f4e":"Nghe riêng một ô","documentation.6bb5c318":"Biểu tượng tai nghe trên clip. Khung xem báo điều đó trong lúc nó còn hiệu lực","documentation.7f68250f":"Mở một clip trong trình chỉnh sửa của nó","documentation.9b3b8f91":"Nhấp đúp vào nó. Những chỉnh sửa của bạn được ghi ngược vào bản phối","documentation.85574b57":"Lặp một đoạn, tắt tiếng hoặc solo một phần","documentation.d174c5c9":"Biểu tượng lặp trên tiêu đề; cái loa và <kbd>S</kbd> trên hàng","documentation.22fee5c2":"Chọn dựng cấu trúc nào trong các cấu trúc của nghệ sĩ","documentation.9b4ae385":"Bộ chọn trong hàng cấu trúc. Để trống nghĩa là họ chọn","documentation.f3e4fadb":"Xuất","documentation.4ec1e842":"Một tệp <code>.mid</code> nhiều track, hoặc mỗi phần một tệp vào một thư mục","documentation.0969199e":"<strong>Tắt tiếng và solo là điều khiển nghe thử.</strong> Chúng đổi những gì bạn nghe chứ không bao giờ đổi bài hát hay tệp xuất ra — cùng một ranh giới mà nút tắt tiếng âm thanh theo từng làn vạch ra. Bật hay tắt một nút giữa lúc đang phát vẫn giữ vạch phát ở nguyên chỗ, nên bạn có thể kiểm tra một đoạn chuyển mà không mất vị trí của mình trong bài.","documentation.24a78f85":"<strong>Bộ điều khiển phát chạy thẻ nào bạn đang xem.</strong> Chỉ có một lịch phát: thẻ Bài hát đặt cả bản phối lên đó, còn quay lại một thẻ bộ tạo sẽ trả lại cho nó clip của thẻ ấy. Nên vạch phát bạn nhìn thấy luôn là vạch đang chạy.","documentation.dd323d51":"<strong>Một lần tung lại vẫn nằm trong khuôn khổ bài hát.</strong> Nó giữ chế độ mà bài hát được tạo, tempo và tông lúc tạo, và mọi độ swing bạn đã ghim — và để nguyên mọi đoạn khác, kể cả bản nhân bản của đoạn bạn vừa tung lại, đúng như cũ.","documentation.920e6fd6":"<strong>Stem được xuất ra dưới dạng MIDI hoặc âm thanh, theo phần hoặc theo làn.</strong> Nửa âm thanh từng là bất khả thi, và lý do được đo chứ không phải đoán: bộ kit đi kèm không có giọng nào cho bốn phần du dương, nên kết xuất chúng sẽ ghi ra bốn tệp <code>.wav</code> câm rồi gọi đó là stem. Giờ bộ kit đã phủ mọi làn được tạo, còn one-shot của riêng bạn phủ phần còn lại. Cả một <em>bài hát</em> vẫn ghi mỗi phần một tệp <code>.mid</code> — kết xuất hàng phút âm thanh cần một tiến trình bạn theo dõi được và một nút huỷ bạn nhấn được, và đó là việc khác hẳn với kết xuất một vòng lặp bốn ô nhịp.","documentation.edc824f0":"<strong>Bạn có thể kéo một phần thẳng lên track của DAW.</strong> Mỗi phần được tạo đều có một tay nắm MIDI và một tay nắm Âm thanh ở thanh bên phải; bật <strong>Theo làn</strong> và phần trống sẽ thành mỗi làn một tay nắm, để riêng hi-hat cũng có thể đi ra. Cả bản phối cũng kéo được, dưới dạng MIDI. Tệp tới với tên như <code>trap - Snare - 140 BPM - C# Minor</code>, và chính các nốt của clip đi theo con trỏ để bạn thấy mình vừa nhặt cái gì. <strong>Hiện mới có trên Windows</strong> — kéo thả HTML5 bên trong webview của plugin không phải là kéo tệp của hệ điều hành, nên mỗi nền tảng cần nguồn kéo gốc riêng. macOS và Linux vẫn dùng Xuất cho tới khi phần của chúng được viết, và không hiện tay nắm kéo nào thay vì một tay nắm thả ra chẳng được gì.","documentation.f6b5ea7d":"<strong>Tệp được thả nằm ở đâu.</strong> Việc kéo sẽ ghi tạm tệp vào thư mục temp của bạn rồi đưa đường dẫn cho DAW. Một tệp <code>.mid</code> được thả sẽ được mọi DAW sao chép vào dự án, nên chúng được dọn đi sau một tuần; còn một tệp <code>.wav</code> được thả thì được <em>tham chiếu</em> theo đường dẫn, nên chúng không bao giờ bị xoá — hãy dùng Collect All and Save của DAW để giữ hẳn một tệp.","documentation.ac9b6565":"<strong>Nó tạo ra cả âm thanh lẫn nốt.</strong> Một bộ tổng hợp đa âm với thư viện có sẵn gồm 225 nhạc cụ trải trên 69 thể loại, và mỗi bộ tạo trong bốn bộ tạo có tính du dương chơi nhạc cụ riêng — nên gán một âm thanh khác nhau cho Melody, Melody đối, Bassline và Hợp âm sẽ cho bạn bốn giọng cùng lúc, chứ không phải một giọng dùng chung.","documentation.e8595ab4":"Không có gì ở đây là thư viện sample. Mỗi âm thanh được tạo ra từ một địa chỉ nhỏ — một nhạc cụ, một thể loại, một biến thể, một cách chơi và một âm sắc — nên cả thư viện chỉ là một nắm số nguyên trong tệp dự án của bạn thay vì hàng gigabyte trên ổ đĩa. Mười ba động cơ tổng hợp đứng phía sau: violin là mô hình dây kéo vĩ còn Rhodes là mô hình piano vật lý, vì thế các điều khiển của chúng hoạt động khác với của một pad.","documentation.d72a5e39":"<strong>Mỗi địa chỉ là một âm thanh khác nhau.</strong> Hai mươi bốn biến thể của một nhạc cụ trong một thể loại đi khắp dải riêng của nhạc cụ đó &mdash; một thanh kim loại ngân bao lâu, một búa gõ mạnh tới đâu, dây được gảy ở chỗ nào &mdash; thay vì tung xúc xắc hai mươi bốn lần, và thể loại tác động vào chính mô hình chứ không phải một bộ lọc đặt sau nó: 808 trap ngân và trượt trong khi kick house thì gọn, và piano jazz có búa mềm hơn piano metal. Cả 2.729.088 âm thanh đều được kiểm tra, bằng cách kết xuất chúng.","documentation.72640dda":"Thẻ SYNTH","documentation.4a4148dd":"Bộ lọc, cả hai đường bao, các hiệu ứng và các điều khiển master cho bộ tạo nào bạn đang chỉnh. Bốn nút ở trên cùng chọn bộ nào — thẻ SYNTH là thẻ duy nhất không tự nó là một phần, nên nó phải hỏi.","documentation.9e3449fc":"Bên trong một kệ nhạc cụ","documentation.dd09491c":"Mở <strong>Nhạc cụ</strong> hoặc một trong bốn <strong>Gói mở rộng gốc</strong> và bạn duyệt kệ đó theo thể loại và họ nhạc cụ &mdash; các thể loại xếp theo chữ cái và danh sách mở ở <strong>Trap</strong>. Danh sách được chia trang: một thể loại không lọc họ nhạc cụ là 5.400 hàng. <strong>Kệ thu hẹp danh sách</strong>, nên mở Gói mở rộng gốc 2 rồi Keys sẽ hiện các nhạc cụ Keys của gói đó chứ không phải mọi nhạc cụ Keys trong sản phẩm.","documentation.6034b304":"<strong>Nhấp vào một hàng chỉ để phát nó, không hơn.</strong> Đoạn bạn nghe là nhạc cụ ở nốt mà nó nghe đúng chất nhất, được vẽ thành dạng sóng trong trình phát nghe thử bên dưới trình duyệt, kèm vạch phát và thời gian đang chạy. <kbd>&uarr;</kbd> và <kbd>&darr;</kbd> đi qua danh sách và phát bất cứ thứ gì chúng dừng tại, nên bạn có thể nghe lần lượt cả một họ nhạc cụ mà không chạm tới chuột.","documentation.a1eb5eff":"<strong>Đặt một nhạc cụ lên bộ tạo là một lần nhấn riêng</strong> &mdash; nút <em>Dùng trong&hellip;</em> bên dưới danh sách, hoặc <kbd>Ctrl</kbd>/<kbd>&#8984;</kbd> + <kbd>&#9654;</kbd>, cả hai đều đặt vào thẻ bạn đang xem. Chọn một nhạc cụ sẽ xoá reverb, drive, gain và đường bao mà nhạc cụ <em>trước đó</em> đang mang, nên thứ bộ tạo phát chính là thứ phần nghe thử đã phát. Bạn không cần phải với tới núm nào để có được âm thanh vừa nghe.","documentation.7c97bb07":"<strong>Trống vào trống, nhạc cụ vào bộ tạo.</strong> Một nhạc cụ có sẵn là một patch synth còn một làn trống phát one-shot, nên phím tắt từ chối cặp ghép đó thay vì làm điều gì bất ngờ với nó. <kbd>Ctrl</kbd> + <kbd>&#9664;</kbd> phát ngược một sample trong phần nghe thử và sẽ không đưa nó vào bộ tạo theo cách đó &mdash; đảo ngược một nốt là việc của piano roll.","documentation.7f76c6b2":"Bàn phím","documentation.2d0fa842":"Bật/tắt nó từ bất kỳ thẻ nào. Nhấp và kéo qua các phím — bạn nhấn ở chỗ cao hay thấp trên phím sẽ quyết định lực nhấn — hoặc dùng bàn phím gõ. Bàn phím gõ tạm nghỉ khi một ô văn bản đang được chọn, nên việc tìm một nghệ sĩ sẽ không chơi nốt vào tai bạn.","documentation.7a1b9f14":"Đổi quãng tám hay dải sẽ gửi lệnh tắt mọi nốt, nên một nốt đang giữ không thể bị kẹt lại khi các phím bên dưới nó thay đổi.","documentation.30f9d8d3":"Chơi vào từ phần cứng","documentation.ee7a9278":"<strong>Cài đặt &rarr; Đầu vào MIDI.</strong> Một bộ lọc kênh (hoặc tất cả các kênh, là mặc định), dịch giọng theo nửa cung, một mức dịch quãng tám cộng dồn với nó, dải uốn cao độ, và một đường cong lực nhấn — dưới mức giữa thì chạm nhẹ ra to hơn, trên mức giữa thì bạn phải nhấn mạnh hơn.","documentation.4d68e35d":"Một nốt bị dịch giọng vượt quá hai đầu bàn phím sẽ <strong>bị bỏ, không bị vòng lại</strong>. Một nốt bị vòng lại là một nốt sai, và không có gì trên màn hình cho bạn biết chuyện đó đã xảy ra.","documentation.874b0424":"<strong>Nốt bạn chơi vào là của bạn.</strong> Chúng không bao giờ bị phân tích, không bao giờ trở thành một phần của phong cách, và không bao giờ huấn luyện thứ gì — cùng quy tắc áp dụng cho một tệp MIDI bạn nhập vào.","documentation.004f6eb1":"Các núm trên trang bộ tạo","documentation.a9a17e79":"Reverb, delay, drive, âm lượng và pan cho phần bạn đang xem, với cùng những con số trong trình chỉnh sửa theo phần ở thanh bên phải. Đó là một bộ điều khiển hiển thị hai lần, không phải hai bộ phải giữ cho khớp nhau.","documentation.aac58205":"Âm lượng, pan và đường bao thuộc về <em>làn</em>, nên chúng hoạt động dù phần đó đang phát một nhạc cụ có sẵn hay một one-shot của riêng bạn. Reverb, delay và drive được áp lên hiệu ứng riêng của nhạc cụ, nên chúng chỉ xuất hiện khi một âm thanh có sẵn được nạp — trên sample của riêng bạn thì chúng không có gì để chạm tới, và một nút điều khiển không thay đổi gì còn tệ hơn là không có.","documentation.7eff58e8":"Lưu một âm thanh","documentation.bd3b5639":"Tạo hình một nhạc cụ, rồi lưu nó vào một nhóm và dưới một cái tên bạn chọn. Chúng được liệt kê theo các nhóm đó trên thẻ SYNTH.","documentation.857fd301":"<strong>Một âm thanh không phải là một cài đặt sẵn.</strong> Một <em>cài đặt sẵn</em> ở thanh bên phải là một phiên đã lưu — một nghệ sĩ, một hạt giống và các giá trị ghim. Một <em>âm thanh</em> là một nhạc cụ. Chúng được giữ ở những chỗ riêng và không bao giờ xuất hiện trong cùng một danh sách.","documentation.a64f42d4":"PACK — giá đỡ sample","documentation.75928332":"Chọn một thể loại và một nhạc cụ, chọn số lượng, rồi Tạo. Tối đa 25 one-shot được kết xuất ngoại tuyến, mỗi cái được cắt gọn và tạo fade để không bị lách cách, và cái nào ra gần như câm sẽ bị bỏ trước khi tới giá đỡ.","documentation.30f4f34e":"Phát bất kỳ ô nào để nghe nó. <strong>Đổi</strong> tung lại một ô mà không động tới các ô khác, <strong>&times;</strong> gỡ một ô, và Xuất sẽ ghi những gì còn lại — kèm tuỳ chọn chuẩn hoá âm lượng. Việc kết xuất diễn ra ở nền với thanh tiến trình và nút Huỷ, nên cửa sổ DAW của bạn không bao giờ ngừng vẽ.","documentation.3fb1265f":"<strong>Cài đặt &rarr; Đầu vào MIDI</strong>, bên dưới các cài đặt đầu vào — cả hai đều nói về những gì đi qua lại giữa plugin này và thiết bị của riêng bạn. WAV hoặc AIFF, 16-bit, 24-bit hoặc 32-bit số thực, ở 44.1, 48, 88.2, 96, 176.4 hoặc 192 kHz.","documentation.0682be26":"Lựa chọn","documentation.769bb19e":"Khi nào","documentation.0a30f217":"WAV 16-bit","documentation.e77855ff":"Mặc định, và là thứ plugin này vẫn luôn ghi.","documentation.7d81c5bd":"WAV 24-bit","documentation.6ce283a3":"Thứ mà phần lớn nhà sản xuất mong đợi ở một bản bounce. Thêm sáu dB dải dùng được.","documentation.a40ce484":"WAV 32-bit số thực","documentation.34ccd0a3":"Giữ lại mọi thứ vượt quá mức tối đa, để một bản bounce quá lớn vẫn kéo xuống lại được.","documentation.7f9266a3":"AIFF 16 hoặc 24-bit","documentation.2c807357":"Cho quy trình làm việc nào cần đến nó. Chỉ số nguyên — ở đây AIFF không có dạng số thực.","documentation.30e94467":"<strong>Một vòng lặp bạn kéo vào DAW luôn là WAV 16-bit, dù mục này đặt thế nào.</strong> Một vòng lặp được kéo ra phải mang tempo của chính nó để khi vào DAW nó được warp theo đúng tốc độ thay vì theo tốc độ của dự án bạn, và chỉ WAV mới giữ được điều đó. Cài đặt này dành cho tệp bạn <em>lưu</em>, khi bạn đã chọn nơi ghi.","documentation.e667e4fb":"<strong>Ba con đường, và bạn muốn con đường nào tuỳ vào việc bạn đang làm.</strong> Plugin phát trên track riêng của nó, kéo tệp ra ngoài, hoặc xuất chúng vào một thư mục.","documentation.3ac408e8":"1. Cứ chơi thôi","documentation.9eccb298":"Plugin xuất MIDI lên track mà nó nằm trên, và cũng tự tạo ra âm thanh — trống qua bộ kit của nó và mỗi phần có tính du dương qua nhạc cụ riêng. Nhấn phát trong DAW và bạn nghe beat mà không cần định tuyến gì.","documentation.25c81dca":"Nếu bạn muốn nhạc cụ của riêng mình chơi các nốt, hãy định tuyến đầu ra MIDI của plugin tới nó theo cách phần mềm chủ của bạn vẫn làm, và tắt âm thanh riêng của phần đó bằng cách không gán nhạc cụ nào cho nó.","documentation.a651299f":"2. Kéo một clip ra ngoài","documentation.ba47208c":"Nắm một chip phần rồi kéo nó lên một track. Mặc định bạn nhận một tệp <code>.mid</code>, hoặc âm thanh nếu bạn chuyển chip. Kéo cả bản phối sẽ cho mỗi phần một tệp.","documentation.74b1c304":"<strong>Hiện giờ kéo thả chỉ có trên Windows.</strong> Trên macOS và Linux các chip không đưa ra tuỳ chọn đó, vì một nút điều khiển không thể hoạt động còn tệ hơn là không có. Hãy dùng Xuất thay thế — nó tạo ra đúng những tệp đó.","documentation.3df20937":"Một vòng lặp <em>âm thanh</em> được kéo ra mang tempo của chính nó, nên khi vào DAW nó được warp theo tốc độ lúc nó được làm ra chứ không theo tốc độ dự án của bạn. Đó là chuyện riêng của WAV, vì thế một vòng lặp được kéo ra luôn là WAV 16-bit dù định dạng xuất đặt thế nào.","documentation.ff72e267":"3. Xuất vào một thư mục","documentation.5d91da4a":"Chọn một thư mục và nhận mỗi phần một tệp — MIDI, hoặc âm thanh theo định dạng bạn đã đặt. Đây là con đường chạy được trên mọi nền tảng, và là con đường nên dùng cho cả một bản phối.","documentation.29940c77":"Theo từng phần mềm chủ","documentation.9f733253":"Định dạng để cài","documentation.dc3decbb":"Chi tiết","documentation.e6225dc8":"Live không đọc CLAP. Thả một tệp <code>.mid</code> lên một track MIDI; với tệp nhiều track, Live tạo mỗi track một clip.","documentation.d976ad22":"FL Studio 21.2+","documentation.c0fb74c6":"CLAP (hoặc VST3)","documentation.c7b038df":"Đọc CLAP nguyên bản. Một tệp <code>.mid</code> nhiều track rơi vào playlist thành các kênh riêng.","documentation.d1100b6d":"Reaper","documentation.fc15247e":"CLAP hoặc VST3","documentation.ce4fa0e2":"Nhận cả hai. Reaper hỏi cách nhập một tệp nhiều track thay vì đoán.","documentation.82653a52":"Bitwig","documentation.600bbc6d":"CLAP là định dạng gốc của nó.","documentation.fd6889aa":"Logic Pro","documentation.acdf4173":"AU","documentation.a74dbbef":"Chỉ macOS. Logic không đọc CLAP lẫn VST3.","documentation.1f04dbe6":"<strong>Hai trong số các hàng này đã được kiểm chứng, ba hàng thì chưa.</strong> Ableton Live 12 và FL Studio đã được nạp và tạo thử bên trong; Reaper, Bitwig và Logic chưa được mở, nên hàng của chúng mô tả những gì tài liệu của từng phần mềm chủ ghi chứ không phải điều ai đó đã tận mắt thấy. Khi một trong số chúng được chạy, kết quả sẽ được ghi vào <code>docs/daw-matrix.md</code>.","documentation.c076a592":"Plugin đọc tempo và nhịp của phần mềm chủ trong từng khối. Bản trap viết ở 140 sẽ ra ở <strong>92 trong một dự án 92&nbsp;BPM</strong> — vì một clip được tạo ở tempo của nghệ sĩ sẽ không vừa với bài hát bạn yêu cầu.","documentation.ab86fb82":"Thứ tự ưu tiên","documentation.15955a81":"<strong>Tempo bạn ghim thắng.</strong> Ghim một tempo trong các ô phiên và nó thắng mọi thứ.","documentation.32319078":"<strong>Rồi tới phần mềm chủ.</strong> Khi bật tự đồng bộ, tempo của DAW được dùng.","documentation.5e24a1af":"<strong>Rồi tới nghệ sĩ.</strong> Khi tắt tự đồng bộ, tempo do chính mô hình viết sẵn được giữ nguyên.","documentation.1125e7e4":"<strong>Tempo ghim được giữ trong dải mà nghệ sĩ làm việc.</strong> Ô BPM dừng ở dải hiển thị trong bảng &mdash; kéo hoặc gõ vượt quá thì nó dừng ở mép &mdash; và chuyển sang một nghệ sĩ không với tới tempo bạn ghim sẽ đưa nó về tempo gần nhất của họ thay vì tạo ra thứ họ không bao giờ chơi. Phần bạn gõ chỉ được sửa khi bạn rời ô, nên <kbd>1</kbd> trên đường gõ tới <kbd>140</kbd> không bị viết lại ngay dưới con trỏ. <strong>Phần mềm chủ không bao giờ bị ép theo điều đó:</strong> tempo của một dự án là của dự án.","documentation.f2eb4b94":"<strong>Chip âm giai đưa ra những âm giai mà nghệ sĩ đó viết.</strong> Một điệu thức là thứ mang tính cách của họ, nên âm giai chọn cho một nghệ sĩ sẽ được trả lại cho mô hình khi bạn chuyển sang một nghệ sĩ khác không dùng nó. Chip tông cố ý không bị giới hạn &mdash; tông là dịch giọng, cùng một bản nhạc ở cao độ khác.","documentation.638c602e":"Tự đồng bộ là một cài đặt phiên được lưu cùng dự án — ba trạng thái, không phải hai. Tắt nó là cách để bạn dùng tempo do nghệ sĩ viết sẵn ngay trong một dự án đang chạy.","documentation.ac4e2b0c":"Mỗi lần tạo đều có một <strong>hạt giống</strong>. Cùng hạt giống, nghệ sĩ và phiên luôn cho ra một mẫu giống hệt tới từng byte — trên bất kỳ máy nào, vào bất kỳ ngày nào. Sao chép hạt giống từ chip, dán lại, và beat trở về.","documentation.f8ac4ea5":"Để trống ô hạt giống để mỗi lần nhận một hạt giống mới; khi đó chip sẽ hiện hạt giống thực sự đã được dùng, nên bạn có thể sao chép một lần tạo bạn thích dù chưa từng gõ con số nào.","documentation.c902e125":"Tính tất định được bộ kiểm thử ép buộc, không chỉ là ý định — đó cũng là lý do một dự án đã lưu có thể khôi phục một beat mà không lưu một nốt nào.","documentation.5d19dc54":"Một cài đặt sẵn là một phiên được đặt tên — nghệ sĩ, hạt giống, số ô nhịp và các giá trị ghim. Cài đặt sẵn mặc định được biên dịch vào tệp nhị phân; cài đặt sẵn của riêng bạn được ghi vào thư mục dữ liệu theo người dùng của nền tảng, nên chúng tồn tại lâu hơn bất kỳ dự án nào.","documentation.6c29a0d2":"<strong>Không cài đặt sẵn mặc định nào ghim tempo.</strong> Ghim là một chỉ dẫn từ người dùng, mà một tệp đi kèm sản phẩm thì không phải người dùng — một cài đặt sẵn mặc định có ghim tempo sẽ đè lên DAW của bạn ngay lúc bạn nạp nó.","documentation.4df575be":"Đặt tên cho một mẫu bạn thích và lần sau nó vẫn ở đó — trong bất kỳ bài hát nào, trong bất kỳ DAW nào. Mỗi mẫu là một tệp JSON riêng trong thư mục dữ liệu theo người dùng của nền tảng, nên một lần lưu hỏng chỉ mất một vòng lặp chứ không mất cả kệ, và bạn có thể sao lưu, đồng bộ hay đưa một mẫu cho người khác bằng cách sao chép một tệp.","documentation.6053a251":"<strong>Một mẫu đã lưu là nốt, không phải âm thanh.</strong> Bộ kit cố ý không được lưu, và đó là điều làm cho câu &ldquo;dùng nó với bất kỳ âm thanh nào bạn muốn&rdquo; là sự thật chứ không phải lời quảng cáo: nạp mẫu, đổi bộ kit, và cùng một màn trình diễn sẽ phát qua những sample khác. Đó cũng là cách một mẫu sống sót qua sự cố sập — một plugin sống trong tiến trình của người khác và chết cùng nó.","documentation.c6f3d453":"Đây không phải cài đặt sẵn và không phải dự án. Một <em>cài đặt sẵn</em> là điểm khởi đầu và không lưu nốt nào cả, vì động cơ tạo lại chúng; <em>dự án</em> thì nhớ bài hát này. Một mẫu đã lưu là bản thu mà bạn giữ lại.","documentation.ca18c184":"Mọi lần tạo trong phiên đều được giữ, từ lần đầu tiên, đếm riêng cho từng bộ tạo. <kbd>&#9664;</kbd> và <kbd>&#9654;</kbd> đi qua chúng, và lùi lại sẽ mang về toàn bộ thiết lập: nghệ sĩ, tâm trạng, hạt giống, số ô nhịp và các giá trị ghim — không chỉ con số.","documentation.8dc74fe7":"Phần hiển thị cho thấy tempo và tông <strong>thực sự đã được dùng</strong>, không phải lúc nào cũng là cái bạn ghim: một beat được làm trong lúc DAW của bạn đứng ở 92 là được làm ở 92, và tempo thay đổi các nốt.","documentation.d7bad06c":"<strong>Và nó tồn tại lâu hơn phiên làm việc.</strong> Nhấp vào bộ đếm bản thu — chỗ &ldquo;3 / 40&rdquo; giữa hai mũi tên — và mọi lần tạo bạn từng làm đều ở đó, nhóm theo nghệ sĩ, mỗi hàng cho biết nó dài bao nhiêu, nhanh thế nào, và bạn làm nó lúc nào. Chọn một bản và nó trở lại. Hai mũi tên trả lời &ldquo;lùi một bước&rdquo;; còn cái này dành cho beat tối thứ Ba mà bạn chưa từng ghi lại hạt giống.","documentation.1223e0b4":"Nó được giữ theo người dùng chứ không nằm trong dự án — bạn đã tạo theo hướng nào là chuyện về bạn, không phải thứ để gửi kèm trong một bài hát gửi tới hãng đĩa — và nó vẫn còn sau khi cập nhật. Mỗi nghệ sĩ giữ chuỗi bản thu riêng, nên một buổi tối dành cho một người không thể đẩy mất những bản bạn đã lưu từ người khác. <strong>Xoá nó bất cứ lúc nào bạn muốn</strong>: nó là bản ghi những gì bạn đã làm, và việc làm trống được nó không phải một tiện ích phụ.","documentation.13e89cca":"Chọn một bản thu sẽ <em>khôi phục</em> nó, giống như các mũi tên — nên mọi thứ bạn vẽ tay trên clip hiện tại sẽ bị thay thế. Đây không phải nghe thử.","documentation.5415794a":"<strong>Khoá một làn thì một lần tung lại không thể động tới nó.</strong> Nhấp ổ khoá trên bất kỳ hàng trống nào, hoặc nhấn <kbd>L</kbd> khi hàng đó đang được chọn, và Tạo sẽ dựng lại mọi thứ khác xung quanh nó, giữ nguyên từng nốt. Khoá không thay đổi gì trong những gì được xuất ra.","documentation.99bec605":"Plugin lưu nghệ sĩ, hạt giống, số ô nhịp, các giá trị ghim và kích thước cửa sổ của bạn <strong>vào chính tệp dự án của DAW</strong>. Mở lại bài hát và phiên làm việc trở lại. Không có tệp nào phải quản lý và không có đường dẫn nào phải chọn.","documentation.2c40e200":"Bản thân mẫu không được lưu — các đầu vào thì có, và động cơ là tất định, nên khôi phục chính là tạo lại. Đó là lý do một dự án đã lưu chỉ tốn vài byte thay vì hàng trăm kilobyte nốt.","documentation.3e527f79":"Mọi phím tắt mà plugin và bản độc lập có, được nhóm theo cách bảng trong ứng dụng nhóm chúng. Nhấn <kbd>Shift</kbd> + <kbd>?</kbd> trong ứng dụng để xem cùng danh sách đó kèm các phím bạn đã gán lại, điều mà trang này không thể biết.","documentation.876884a2":"Khi một hàng hiện <kbd>Ctrl</kbd> / <kbd>⌘</kbd>, nghĩa là Ctrl (Windows/Linux) hoặc ⌘ (macOS).","documentation.e5651c68":"Phím","documentation.97c89a4d":"Thao tác","documentation.c10d76c9":"Điều khiển","documentation.86247409":"<kbd>Space</kbd>","documentation.fe13ca09":"Phát hoặc tạm dừng","documentation.a1e10fc7":"<kbd>F9</kbd>","documentation.7fa3a667":"Bắt đầu hoặc dừng ghi","documentation.4b2adf96":"<kbd>F10</kbd>","documentation.b32e9662":"Bật hoặc tắt máy đếm nhịp","documentation.dba91bb2":"<kbd>K</kbd>","documentation.7dda588a":"Hiện hoặc ẩn bảng bên phải","documentation.523bc70d":"<kbd>E</kbd>","documentation.0b4b9af3":"Chuyển giữa trình duyệt tệp và danh sách","documentation.df9030e9":"<kbd>Shift</kbd> + <kbd>?</kbd> hoặc <kbd>F1</kbd>","documentation.1f06ac86":"Hiện bảng này","documentation.e9789990":"Hiển thị và bố cục","documentation.e14c9778":"<kbd>V</kbd>","documentation.1d83fd23":"Hiện hoặc ẩn một bảng","documentation.d4d84f89":"<kbd>Shift</kbd> + <kbd>V</kbd>","documentation.09faca1e":"Chế độ tập trung - ẩn thanh bên và thẻ","documentation.fc45f9b7":"Tạo","documentation.285be7d3":"<kbd>Enter</kbd>","documentation.0c77ce7a":"Tìm trong danh sách","documentation.04522798":"<kbd>G</kbd>","documentation.ac1fc67e":"Tạo phần này","documentation.627c2d8c":"<kbd>Shift</kbd> + <kbd>G</kbd>","documentation.3767cc00":"Tạo tất cả các phần","documentation.ed629d67":"<kbd>1 – 6</kbd>","documentation.5ee84ca1":"Chọn bộ tạo","documentation.51462405":"<kbd>R</kbd>","documentation.9a7a1f12":"Tạo lại đoạn clip","documentation.5eafac83":"<kbd>L</kbd>","documentation.81eb04cd":"Giữ trống này khi tạo lại","documentation.9018d7e2":"<kbd>←</kbd> / <kbd>→</kbd>","documentation.cdf3fbba":"Duyệt các bản của bạn","documentation.3b9ba1a2":"Chỉnh sửa","documentation.fd138353":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>A</kbd>","documentation.913afff1":"Chọn tất cả","documentation.ebad6201":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>C</kbd>","documentation.af74f7c5":"Sao chép","documentation.b737693a":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>X</kbd>","documentation.38d13bda":"Cắt","documentation.098d9ba7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>V</kbd>","documentation.db248300":"Dán","documentation.414f88f4":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Z</kbd>","documentation.39fc7212":"Hoàn tác","documentation.fc1e31a5":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Shift</kbd> + <kbd>Z</kbd> hoặc <kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Y</kbd>","documentation.471b94d4":"Làm lại","documentation.08b1c0d8":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>D</kbd>","documentation.972d5737":"Nhân bản","documentation.f66bceff":"<kbd>Delete</kbd>","documentation.f6fdbe48":"Xoá","documentation.07fdb121":"<kbd>Esc</kbd>","documentation.04d948a3":"Bỏ chọn","documentation.70440046":"Nốt","documentation.5d4723bf":"<kbd>↑</kbd> / <kbd>↓</kbd>","documentation.8c532548":"Dịch giọng một nửa cung","documentation.6cac4df7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>↑</kbd> / <kbd>↓</kbd>","documentation.2b308ba3":"Dịch giọng một quãng tám","documentation.d47af99e":"Dịch theo thời gian","documentation.ac264590":"<kbd>*</kbd>","documentation.be758f68":"Kéo dài gấp đôi","documentation.a9253744":"<kbd>/</kbd>","documentation.dd9f8fd9":"Nén còn một nửa","documentation.8382840e":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>R</kbd>","documentation.3ee05a25":"Đảo ngược nốt đã chọn","documentation.7c37d8f8":"Lưới trống","documentation.9e4e8841":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>3</kbd>","documentation.4157bd81":"Chùm ba ở ô này","documentation.43a310f9":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>5</kbd>","documentation.7e966ffc":"Chùm năm ở ô này","documentation.a5878dde":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>7</kbd>","documentation.1f5d282a":"Chùm bảy ở ô này","documentation.7ec8386d":"<kbd>Alt</kbd> + <kbd>nhấp</kbd>","documentation.ebfc4304":"Chép ô nhịp 1 sang ô nhịp này","documentation.2ff1c1cd":"<kbd>Shift</kbd> + <kbd>kéo</kbd>","documentation.fb11f8c2":"Kéo một khung để chọn ô","documentation.4fe7447c":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>nhấp</kbd>","documentation.54e8dccd":"Thêm một ô vào vùng chọn","documentation.1a36d4f6":"<kbd>Nhấp chuột phải</kbd>","documentation.0aeadb3b":"Bảng roll cho ô này","documentation.c9889415":"<kbd>Nhấp chuột phải</kbd> + <kbd>kéo</kbd>","documentation.394a6a30":"Xoá mọi ô đã kéo qua","documentation.dcd5f1f8":"Trình duyệt sample","documentation.94d34d10":"Phát sample ngược / xuôi","documentation.d604eafc":"Hoàn tác không giới hạn trong một phiên và bao gồm nghệ sĩ, hạt giống, số ô nhịp, các giá trị ghim, mỗi lần tạo <strong>và cả bản phối</strong> — một ngăn xếp duy nhất, dù bạn ở thẻ nào. Bên trong một ô văn bản, chức năng hoàn tác của chính hệ thống sẽ nhận phím tắt đó, nên ô hạt giống vẫn xoá ngược được một ký tự.","documentation.e90cfbee":"Cùng plugin đó, trong cửa sổ riêng, không cần DAW nào — tiện để thử nhanh và cho những máy mà bạn không dùng để sản xuất nhạc.","documentation.c1864be2":"<strong>Nó không thể đồng bộ với DAW của bạn, và sẽ không bao giờ</strong> — không có phần mềm chủ, nên không có gì để đồng bộ. Có thể đặt một tempo cố định qua dòng lệnh, đi qua cùng con đường đó, nhưng tempo, nhịp và đầu phát thật của phần mềm chủ thì cần một phần mềm chủ thật.","documentation.fb858c80":"<strong>Và nó không báo tempo dự án nào trừ khi bạn yêu cầu.</strong> Không có <code>--tempo</code> thì không có dự án, nên không có gì đè lên nghệ sĩ: chọn một mô hình và bạn nghe nó ở tempo mà nó được viết. Truyền <code>--tempo</code> vào thì giá trị cố định đó hoạt động y như của một phần mềm chủ.","documentation.58c0f8e2":"Không tài khoản. Không đo lường từ xa. Không có gì về bạn, về dự án hay về thành quả của bạn được truyền đi. Tạo, phát, nhập và xuất đều hoàn toàn cục bộ.","documentation.6dae90a7":"<strong>Plugin không mở bất kỳ kết nối đi ra nào.</strong> Hai cái từng có — kiểm tra cập nhật khi khởi động và báo cáo sập tuỳ chọn — thuộc về ứng dụng máy tính và đã bị bỏ cùng nó. Plugin do người cài plugin cài và cập nhật, và không có client HTTP nào được biên dịch vào nó. Hai cửa dựng kiểm tra điều này ở mỗi commit thay vì tin vào lời tuyên bố: một cửa đọc đồ thị phụ thuộc và thất bại nếu có bất kỳ client HTTP nào được liên kết, cửa kia điều khiển giao diện thật qua một lần tạo và thất bại nếu trình duyệt thử gửi dù chỉ một yêu cầu ra khỏi máy.","documentation.bef6f4df":"<strong>Ứng dụng web được gửi qua mạng; còn thứ bạn làm ra thì không.</strong> Một trang phải được tải về — bản thân ứng dụng và dữ liệu phong cách mà nó tạo dựa trên. Chỉ có thế. Việc tạo chạy trên máy bạn, trong trình duyệt bạn; các beat, các hạt giống và mọi thứ bạn nhập vào đều ở đó và không bao giờ được tải lên. Sau một lần ghé, thẻ vẫn chạy khi tắt mạng.","documentation.410bfc53":"<strong>Cộng tác là ngoại lệ duy nhất, và chỉ khi bạn dùng nó.</strong> Các phòng nối máy bạn trực tiếp tới những người bạn mời. Nếu bạn lưu ai đó làm bạn bè, một dịch vụ nhỏ có thể cho bạn biết khi nào họ trực tuyến — và nó không được kể điều gì đáng giá: một khoá thay đổi mỗi vài phút, và một địa chỉ được mã hoá bằng bí mật chỉ hai bạn giữ. Nó không đọc được, không liệt kê được ai đang ở đó, và không suy ra được ai biết ai. Tắt nó đi, hoặc đừng bao giờ lưu bạn bè, thì bạn dán một mã thay thế. Dịch vụ cộng tác do một chương trình riêng liên lạc tới, không bao giờ do plugin mà DAW của bạn nạp, và đó là điều giữ cho câu ở trên luôn đúng.","documentation.0b27ac6b":"Báo cáo sập được ghi vào một thư mục trên chính ổ đĩa của bạn và không bao giờ được gửi đi đâu. Chúng tồn tại để bạn có thứ đính kèm vào một báo cáo lỗi nếu bạn muốn — ngoài bạn ra không có gì đọc thư mục đó.","documentation.6d222977":"Mọi câu trả lời ở đây đều là nhắc lại một điều đã được viết trong giấy phép, <a href=\"legal/disclaimer.md\">tuyên bố miễn trừ về tên gọi</a> hoặc phần ghi công. Không có gì trên trang này là một lời hứa mới.","documentation.daf9a79b":"Đây có phải AI không?","documentation.2458a52d":"Không, và không theo nghĩa yếu kiểu «chúng tôi không gọi nó như thế». Không có học máy ở bất kỳ đâu trong sản phẩm — không mô hình, không dữ liệu huấn luyện, không suy luận, không mạng nơ-ron dưới bất kỳ dạng nào. Động cơ đọc một tập con số và quy tắc viết tay rồi dựng một mẫu từ một bộ sinh ngẫu nhiên có hạt giống. Bạn có thể đọc những con số đó: chúng là JSON thuần, và mỗi con số là một dải tempo, một tỉ lệ swing, một mật độ nốt, một ngữ pháp roll hoặc một xu hướng hợp âm.","documentation.3bf82a34":"Vậy làm sao nó nghe giống một nghệ sĩ cụ thể được?","documentation.9412c301":"Vì thói quen của một nhà sản xuất là thứ mô tả được. Hi-hat dồn đôi thường xuyên tới đâu, snare rơi vào đâu, 808 có trượt không và trượt xa bao nhiêu, những họ hợp âm nào xuất hiện và họ nào không bao giờ — tất cả được viết ra bằng tay, từ các cuộc phỏng vấn đã công bố, bài viết về kỹ thuật và việc lắng nghe. Đó là cùng một loại tài liệu như một bài học trống dạy bạn nhịp shuffle, và nó hiệu quả vì cùng một lý do.","documentation.fa02d276":"Các nghệ sĩ có tham gia không? Họ có chấp thuận việc này không?","documentation.ac411997":"Không. <strong>Không nghệ sĩ, nhà sản xuất, hãng đĩa hay nhà xuất bản nào được nêu tên trong phần mềm này đã chứng thực, tài trợ, phê duyệt, xem xét hay liên kết với nó theo bất kỳ cách nào.</strong> Tên của họ xuất hiện như cách gọi mô tả một phong cách dễ nhận ra và không gì khác — giống như cách một bảng hợp âm có thể được ghi nhãn «bossa nova». Không tên nào được dùng làm thương hiệu hay dấu chỉ xuất xứ cho phần mềm này hoặc cho bất cứ gì nó tạo ra.","documentation.af1c7364":"Nó có chứa âm nhạc của họ không?","documentation.bb221e18":"Không. Một mô hình phong cách không chứa MIDI, không chứa âm thanh, không có bản ký âm của bản thu nào và không có nội dung giai điệu hay lời nhạc từ bất kỳ bài hát nào. Không có tính năng nào tái tạo một bài cụ thể, và sẽ không bao giờ có — đó là một quyết định thiết kế vĩnh viễn chứ không phải thứ chưa được dựng.","documentation.92ebf1ef":"Tôi có được phát hành thứ mình làm ra không? Có được bán nó không?","documentation.02c55f87":"Có. Những gì bộ tạo viết ra là nguyên bản ngay từ cách nó được dựng: nó được ghép từ các quy tắc và một con số, không có bản thu nào ở bất kỳ khâu nào, nên trong đó không có gì đến từ tác phẩm của người khác. Bạn sở hữu thành quả của mình và không nợ ai điều gì vì nó — xem phần giấy phép bên dưới để biết câu chữ chính xác.","documentation.1d3f4df2":"Lưu ý thông thường vẫn áp dụng và chẳng liên quan gì tới phần mềm này: nếu bạn thả lên pad một sample mà bạn không có quyền, sample đó vẫn không phải của bạn. Các nốt là của bạn; một bản thu bạn nhập vào thì vẫn là thứ nó vốn là.","documentation.114f1c77":"Nếu nó vô tình viết ra một melody đã có sẵn thì sao?","documentation.e79791f6":"Nó sàng lọc điều đó. Mỗi melody và melody đối đều được lấy dấu vân tay theo hình dạng — chuỗi quãng và khoảng cách giữa chúng — rồi được đối chiếu với một bảng các giai điệu nổi tiếng trước khi bạn nghe. Bản nào trùng sẽ bị bỏ và rút lại.","documentation.9e84e0da":"<strong>Nói thẳng về phạm vi của nó.</strong> Bảng chứa những giai điệu thuộc phạm vi công cộng — dân gian, thánh ca và cổ điển — vì dựng nó từ bất cứ thứ gì khác đồng nghĩa với việc phần mềm này mang nốt nhạc của người khác, điều duy nhất nó không bao giờ được làm. Nên bộ sàng bắt được việc vô tình trích một giai điệu nổi tiếng, và điều đó đáng để bắt. Nó <em>không</em> phải lý do thành quả của bạn là nguyên bản. Lý do ấy là mọi điều trong hai câu trả lời ở trên.","documentation.13eef4e4":"Nó có lén gửi dữ liệu về nhà không?","documentation.772074f7":"Không. Xem <a href=\"#privacy\">Quyền riêng tư &amp; mạng</a> ở trên để có câu trả lời đầy đủ, gồm cả hai thứ có chạm tới mạng và lý do: tải ứng dụng web, và cộng tác nếu bạn chọn dùng nó.","documentation.58fc0ea4":"Các vòng lặp trống và one-shot đến từ đâu?","documentation.ccf41857":"Cả hai đều là của chúng tôi. 5.085 vòng lặp MIDI đi kèm được viết bởi chính các bộ tạo của sản phẩm này từ các mô hình phong cách của nó — không vòng lặp nào được trích ra từ âm thanh hay MIDI của ai. Các one-shot nghe thử được tổng hợp từ bộ dao động và nhiễu đã lọc, nên trong chúng hoàn toàn không có chất liệu thu âm nào và không kèm giấy phép bên thứ ba nào.","documentation.1f932b39":"Tôi có dùng nó ngoại tuyến được không?","documentation.a812ebd9":"Plugin và bản độc lập vốn chưa bao giờ cần mạng. Ứng dụng web tự tải về một lần rồi chạy được khi đã tắt mạng.","documentation.a1904ba7":"Không có trình báo lỗi nào lén gửi dữ liệu về nhà, và sẽ không bao giờ có. Thay vào đó là một thư mục: khi một trong hai nửa của plugin gục ngã, nó ghi lại điều đã xảy ra lên chính ổ đĩa của bạn, và bạn quyết định có gửi nó đi hay không.","documentation.801c98db":"Báo cáo nằm ở đâu","documentation.9cacc2d0":"<code>%APPDATA%\\Freally MIDI Master\\crashes\\</code>","documentation.3b993d8d":"<code>~/Library/Application Support/Freally MIDI Master/crashes/</code>","documentation.1a91a6c1":"<code>$XDG_DATA_HOME/freally-midi-master/crashes/</code>, hoặc <code>~/.local/share/freally-midi-master/crashes/</code>","documentation.90d83808":"Tên tệp cho biết nửa nào đã hỏng: <code>-panic</code> là động cơ âm thanh kèm backtrace, <code>-page</code> là giao diện, và trên Windows <code>-fault</code> là lỗi phần cứng như vi phạm truy cập. Hai mươi tệp mới nhất được giữ lại, nên thư mục không bao giờ phình ra vô hạn và bạn có thể đính kèm tất cả vào một báo cáo lỗi.","documentation.4ec55525":"Nếu thứ hỏng là <em>giao diện</em>, bạn sẽ thấy một bảng có lối quay lại phiên làm việc thay vì một hình chữ nhật chết — bản phối nằm ngoài phần bị sập, nên nhấn nút sẽ vẽ lại chính công việc của bạn. Dù vậy vẫn hãy báo lỗi; nhật ký đã nằm sẵn trên ổ đĩa.","documentation.cd05c2a9":"Vậy: khi báo lỗi, hãy cho biết phần mềm chủ nào, định dạng nào (CLAP hay VST3) và phiên bản hệ điều hành nào, rồi đính kèm tệp mới nhất trong thư mục ở trên. Nếu sự cố làm sập cả DAW, hãy đính kèm thêm nhật ký mà DAW của bạn đã ghi — khi phần mềm chủ sập, có thể chúng tôi không còn cửa sổ nào để ghi.","documentation.f7ca8294":"Độc quyền, <strong>Bảo lưu mọi quyền</strong>; mã nguồn là riêng tư. Bạn không được phân phối lại nó hay phát hành sản phẩm phái sinh. Nó <strong>không</strong> phải mã nguồn mở.","documentation.5d361274":"<strong>Âm nhạc bạn làm ra bằng nó là của bạn</strong>, không phí bản quyền và không bắt buộc ghi công.","roster.827703c6":"Mọi nghệ sĩ, nhà sản xuất và thể loại mà plugin mô hình hoá.","roster.numbers.genres":"thể loại","roster.8d0c67df":"<strong>Đây là những tham số viết tay, không phải dữ liệu huấn luyện.</strong> Không phân tích âm thanh của ai để dựng nên bất cứ phần nào trong đây. Mỗi mục là một tập số mà một con người ghi lại từ nghiên cứu đã công bố — dải tempo, độ swing, kick rơi vào những phách nào — và các tên được dùng giống như cách dùng tên một thể loại, để nói một phong cách nghe ra sao. Không có mô hình nào được huấn luyện trên ai ở đây, và plugin tạo ra những mẫu nguyên bản chứ không tái tạo một bản thu.","roster.fb1a2b56":"<strong>Không hàm ý và không tuyên bố bất kỳ sự liên kết, chứng thực hay quyền tác giả nào.</strong> Không nghệ sĩ, nhà sản xuất, hãng đĩa, nhà xuất bản hay chủ sở hữu quyền nào được nêu ở đây đã chứng thực, tài trợ, phê duyệt hay xem xét phần mềm này, và cũng không liên quan tới nó theo bất cứ cách nào. Không tên nào bên dưới được dùng làm thương hiệu, tên sản phẩm, hay dấu chỉ xuất xứ cho phần mềm này hoặc cho bất cứ gì nó tạo ra. Mọi thương hiệu và tên gọi thuộc về chủ sở hữu tương ứng. <a href=\"legal/disclaimer.md\">Đọc toàn bộ tuyên bố miễn trừ</a>.","roster.40f89a05":"Danh mục phong cách","roster.e13848fc":"Tên, thể loại hoặc thời kỳ","roster.bce06414":"Tìm","roster.3deb7456":"Loại","roster.6a720856":"Tất cả","roster.1528d87e":"Nghệ sĩ","roster.a44fa04f":"Nhà sản xuất","roster.96817ade":"Thể loại","roster.5bd44ebe":"Hạng","roster.ab64ea9b":"Chủ lực","roster.2dfa6607":"Chuẩn","roster.2a864697":"Phong cách","roster.f37a89cb":"Thời kỳ","roster.55ac5448":"Đang tải danh mục phong cách…","roster.type.artist":"Nghệ sĩ","roster.type.producer":"Nhà sản xuất","roster.type.genre":"Thể loại","roster.shown":"{shown} trên {total} khớp","roster.none":"Không có kết quả phù hợp.","roster.failed":"Không tải được danh mục phong cách. Hãy thử tải lại trang.","roster.file":"Trang này đang được mở dưới dạng tệp cục bộ, và trình duyệt từ chối tải danh mục phong cách từ một trang file://. Hãy mở trang qua HTTP.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.roster":"Danh mục","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v1.0.0-beta đã xong · tiếp theo là v1.0.0RC","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally MIDI Master hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inAction":"Khi hoạt động","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Tám ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally MIDI Master, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"Đang phát triển · v1.0.0-beta","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.roster":"<span class=\"hl-muted\">Mọi phong cách,</span> <span class=\"hl-bright\">trong một danh sách.</span>","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.styles":"Phong cách","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally MIDI Master, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.changelog.unreleased":"Chưa phát hành","kit.search.none":"Không có gì trên trang này khớp với điều đó.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">Chưa phát hành</span></span>","changelog.2a6141e43be0":"Thay đổi","changelog.e872b6a54c3f":"<strong><code>freally-encode</code> và <code>freally-drag</code> giờ là các crate riêng</strong> (tag dùng chung <code>shared-v2</code>, phần tách A của Freally Unloop). Bộ ghi WAV/AIFF cùng chunk tempo <code>acid</code> của nó, bộ dò WAV và cửa lấy mẫu lại <code>rubato</code> duy nhất đã chuyển từ <code>freally_library::encoder</code> và <code>plugin/src/audio/resample.rs</code> sang <code>encode/</code> (<code>freally-encode</code>); nguồn kéo OLE / Cocoa / GTK chuyển từ <code>plugin/src/drag/</code> sang <code>drag/</code> (<code>freally-drag</code>), tổng quát hoá theo sản phẩm. MIDI Master dùng cả hai và các byte của nó không đổi: cùng những tệp WAV và AIFF, cùng chunk <code>acid</code> ở mọi độ sâu bit, cùng thư mục đệm cho thao tác kéo. Chunk phiên của thư viện vẫn nằm trong <code>freally_library::encoder</code>, nơi xuất lại phần còn lại.","changelog.57c8863aec4f":"<strong>FLAC và MP3, sau các feature.</strong> <code>freally-encode</code> thêm FLAC (<code>flacenc</code>, feature <code>flac</code>, một chú thích Vorbis <code>BPM=</code>) và MP3 (<code>rusty_mp3</code>, feature <code>mp3</code>, ID3v2.3 <code>TBPM</code>/<code>TIT2</code>) cho tính năng Print của Unloop. MIDI Master chưa bật cái nào. Các bộ ghi cấp thấp không bao giờ dán nhãn lại âm thanh: một tần số chúng không mang được sẽ bị từ chối, và các cửa lấy mẫu lại sẽ chuyển đổi trước. Giờ <code>ci:local</code>, CI và <code>cargo deny</code> dựng, kiểm thử và kiểm tra giấy phép cho crate với mọi feature được bật.","changelog.e418959c78ca":"<strong>Adapter webview tự đặt tên thư mục dữ liệu của mình</strong> (<code>WebViewEditor::with_data_dir_name</code>, mặc định không đổi: <code>Freally MIDI Master</code>), và phần khớp màn hình của trình chỉnh sửa (<code>system_scale</code>, <code>work_area</code>) đã chuyển vào mô-đun <code>screen</code> của adapter. Một tên không hợp lệ sẽ quay về mặc định.","changelog.28724e313f97":"<strong><code>engine</code> giờ tự đủ</strong>: <code>data/humanize/groove.json</code>, README của nó và <code>data/novelty/hooks.hash</code> đã chuyển vào <code>engine/data/</code>, nên crate dựng được từ một bản sao được vendor hoặc đã xuất bản, không chỉ từ một bản checkout đầy đủ.","changelog.7542eeec97e8":"<strong><code>engine::smf_read::read_facts</code></strong> — nốt, định dạng, tempo, PPQ, các track, nhịp và độ dài của một tệp MIDI, dành cho Loop Library của Unloop.","changelog.5af8a9a4077e":"<strong><code>freally-extract</code> giờ là một crate riêng</strong> (tag dùng chung <code>shared-v3</code>, cho TASK-020 của Freally Flipcopy và TASK-090 của Freally Unloop). Bộ trích xuất — điểm khởi âm, lưới, trống, các đường có cao độ, phép thử giọng hát, chroma — đã chuyển từ <code>plugin/src/extract/</code> sang <code>extract/</code> (<code>freally-extract</code>), cùng với cửa giải mã đứng trước nó (<code>plugin/src/audio/import.rs</code>, nay là <code>freally_extract::decode</code>), bộ dò cao độ (<code>plugin/src/audio/pitch.rs</code>), <code>midi_hz</code> và <code>SILENCE_PEAK</code>. Mọi đường dẫn cũ đều xuất lại những gì đã chuyển đi, nên phần trích xuất, nhập one-shot và quét thư viện của MIDI Master vẫn đọc cùng những tệp theo cùng cách; chỉ có tác vụ chạy trích xuất trên một worker là ở lại trong plugin. Crate dựng được cho <code>wasm32</code> (ứng dụng web của Unloop), và giờ <code>ci:local</code> cùng CI đều kiểm tra điều đó.","changelog.a04385060482":"<strong><code>freally_extract::decode::decode_facts</code></strong> (và <code>decode_file_facts</code>) — cùng cửa giải mã ấy, giờ trả về thêm những gì tệp chứa trước khi bị gập về mono: số kênh, độ sâu bit, cùng đỉnh và RMS trên mọi kênh. Dành cho các trang in của Flipcopy. Được chính bộ đọc duy nhất kiểm đếm khi các gói đi qua; các cửa có từ trước vẫn trả về đúng như cũ.","changelog.6cb361b3247a":"<strong><code>freally_library::audition::NoteRenderer</code></strong> (<code>render_notes</code> trong kế hoạch của Flipcopy, <code>shared-v3</code>) — các nốt của một clip được kết xuất qua một cài đặt sẵn của thư viện, hoặc qua một máy trống với mỗi làn trống GM một giọng, có tôn trọng pitch bend và pedal ngân, kèm phần đuôi sau nốt cuối. Các giọng là của <code>SynthEngine</code>, trống là của <code>drumkit</code>, các sự kiện được áp đúng khung của chúng, và bản kết xuất cài đặt sẵn lấy hạt giống từ chính cài đặt sẵn đó, nên cùng những nốt sẽ kết xuất ra cùng những byte. Một nốt trống không làn nào đáp lại sẽ được đếm, không bao giờ đoán. Dành cho MIDI → âm thanh của Flipcopy; chưa có gì trong MIDI Master gọi tới nó.","changelog.86cdd25e66f0":"<strong><code>engine::smf_read::read_facts</code> báo mọi pitch bend và controller</strong> (<code>Facts::controls</code>, <code>shared-v3</code>), theo thứ tự thời gian, giới hạn ở 20.000 với <code>controls_capped</code> báo điều đó — một mức trần, không bao giờ là từ chối, nên mọi tệp từng nhập được trước đây vẫn nhập y như cũ.","changelog.ed6c4224859d":"<strong>Lời từ chối dưới dạng giá trị</strong> (<code>shared-v3</code>): <code>decode_facts</code> và <code>read_bounded</code> của cửa giải mã, cùng <code>engine::smf_read::read_facts</code>, từ chối bằng một <code>Refusal</code> có kiểu (quá lớn, quá dài <em>ở chính tần số của tệp</em>, im lặng, SMPTE, quá nhiều nốt…) mà <code>Display</code> của nó chính là câu những cửa ấy vẫn luôn trả về — nên mọi cửa <code>String</code> vẫn nói đúng y như trước. Dành cho Freally Flipcopy, vốn in mỗi lời từ chối bằng ngôn ngữ của nhà sản xuất kèm giới hạn của nó thay vì so khớp chuỗi tiếng Anh. Ở <code>shared-v2</code>, <code>read_facts</code> trả về một <code>String</code>.","changelog.980fad0ffb14":"<strong><code>NoteRenderer::set_sample_rate</code></strong> (<code>shared-v3</code>): một tần số mới giữ lại các động cơ đang chạy sẵn (mỗi cái được đổi tần số ở lần dùng kế tiếp) thay vì dựng lại chúng.","changelog.e9ddffd5fc76":"<strong><code>freally_extract::decode::frame_budget</code></strong> (<code>shared-v3</code>): số khung mà một lần giải mã ở một tần số giữ cho một giới hạn tính bằng giây — chính quy tắc của cửa, nay được công khai, để một sản phẩm kết xuất một tệp mà nó sẽ đọc lại qua cửa (các bản sao của Freally Flipcopy) từ chối lần kết xuất mà cửa sẽ từ chối, trước khi cấp phát cho nó.","changelog.013f4389933a":"<strong><code>read_bounded</code> được giới hạn bởi chính những gì nó đọc</strong> (<code>shared-v3</code>, lượt duyệt mã của Freally Flipcopy): một thiết bị bị từ chối trước khi đọc byte nào, và một tệp lớn lên sau khi kích thước của nó đã được kiểm tra sẽ được đọc tới <code>MAX_FILE_BYTES</code> rồi bị từ chối — riêng bước kiểm tra kích thước đã để <code>/dev/zero</code>, vốn báo độ dài bằng không, bị đọc cho tới khi phần mềm chủ cạn bộ nhớ.","changelog.2d1ace37beb0":"<strong>Một nốt ngắn hơn một khung được nhả ra</strong> (<code>NoteRenderer</code>, <code>shared-v3</code>): lần nhả của nó rơi vào một khung sau cú đánh, không bao giờ trùng đúng khung đó — trong cùng một khung thì nhả được xử lý trước, nên một nốt có điểm đầu và điểm cuối làm tròn về cùng một khung sẽ ngân suốt cả phần đuôi.","changelog.3649549ac755":"<strong><code>drums::proposal_name</code> giờ là công khai (ẩn khỏi tài liệu)</strong> để bộ đo hiệu năng trống tới được nó qua ranh giới crate mới.","changelog.87e36c5e8277":"<strong>nih-plug tiến thêm một commit</strong> (<code>shared-v3</code>): <code>ProcessContext::process_mode()</code> của bản fork, để plugin biết một khối là kết xuất ngoại tuyến kể cả khi một phần mềm chủ CLAP đổi chế độ mà không khởi tạo lại nó (âm thanh cỗ máy của Freally Flipcopy không bao giờ được lọt vào một bản bounce). Adapter và cả hai manifest của plugin cùng tiến lên: chỉ một <code>nih_plug</code> trong bản dựng.","changelog.807f6de9d0ba":"<strong><code>nih-plug-webview</code> nhận được tệp thả vào từ hệ điều hành</strong> (<code>WebViewEditor::with_file_drop_handler</code>, <code>shared-v3</code>, dành cho mặt kính của Freally Flipcopy) — các sự kiện thả tệp của wry kèm đường dẫn, trên luồng giao diện của trình chỉnh sửa. Phải chủ động bật: không có trình xử lý thì webview giữ hành vi riêng của nó, và trình chỉnh sửa của MIDI Master không đặt trình xử lý nào.","changelog.1246fc93bca0":"Sửa","changelog.464aedef592b":"<strong>Một tệp MIDI toàn note-on không bao giờ kết thúc sẽ bị từ chối</strong>, chứ không được đọc: giới hạn nốt đếm cả nốt đang mở lẫn nốt đã đóng, và một note-off tìm nốt của nó trong thời gian lôgarit — một tệp với một triệu note-off lạc không còn tốn hàng giây.","changelog.22e2ad641345":"<strong>Lượt dọn tệp cũ một tuần của thư mục đệm kéo không bao giờ xoá âm thanh trong thư mục con</strong>, không bao giờ đi theo liên kết, và một lần ghi đệm, ghi tràn hay kéo tệp đều từ chối một tên hoặc đường dẫn không phải dạng đơn thuần.","changelog.59ff0563db02":"<strong>Âm thanh xuất ở tần số khác với tần số kết xuất giờ dài đúng như phải dài và nằm đúng chỗ phải nằm.</strong> Bộ lấy mẫu lại đã bỏ mất các khung cuối của mọi lần chuyển đổi (48.000 khung ở 48 kHz ra thành 44.098 ở 44.1 kHz, chứ không phải 44.100) và đặt mọi thứ lệch tới ba khung — trễ +1.17 khung ở 44.1→96 kHz, sớm nửa khung ở 96→48 kHz. Giờ độ dài là <code>frames × to / from</code> làm tròn tới khung gần nhất, và vị trí sai lệch trong vòng một phần năm mươi khung ở mọi tần số xuất. Điều này thay đổi các byte của mọi tệp xuất hay kéo ra ở tần số không phải gốc, và một one-shot của bộ kit được chuyển sang tần số thiết bị khác với tần số của chính nó giờ giữ được các khung cuối; mọi thứ ở đúng tần số của chính nó thì không đổi.","changelog.db671325856c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0RC</span><time class=\"release__date\" datetime=\"2026-09-17\">2026-09-17</time></span>","changelog.2d4bc1529072":"<strong>Bản ứng viên phát hành đầu tiên</strong>, 153 mục kể từ 0.4.0. Không phải bản tải về: các tệp nhị phân này dành cho chính chủ sở hữu thử nghiệm trong Ableton, FL Studio, Reaper và Freally Oscillate, và không có đường dẫn nào xuất hiện trên trang cho tới khi việc đó xong.","changelog.2140e4134a93":"<strong>Giờ nó chạy ở bốn nơi</strong> — plugin này, một bản độc lập, một thẻ trình duyệt chạy cùng bộ tạo được biên dịch sang wasm, và MixSir trên điện thoại. <strong>Mới:</strong> các phòng cộng tác, bốn Gói mở rộng gốc (1.400 nhạc cụ, 5.085 vòng lặp, thêm 189 nghệ sĩ), fade cho clip, khung xem clip âm thanh hiển thị đúng âm thanh thật, xác suất và lực nhấn theo từng nốt, một phiên đi theo bên trong tệp xuất ra, và một sản phẩm màu xanh lá.","changelog.89b5266eb048":"<strong>Đã biết:</strong> chưa có trình chỉnh sửa cho Linux, nên ở đây không dựng cho Linux; các tệp nhị phân không ký theo chính sách, có checksum đi kèm bên cạnh; và mười một phát hiện từ lượt duyệt được ghi lại mà chưa sửa trong <code>docs/product-roadmap.md</code>, không cái nào là lỗi sập hay mất dữ liệu.","changelog.68f004440417":"Sửa - cửa kiểm e2e bị quá thời gian chờ trên một máy chủ dev khởi động lạnh, 2026-09-17","changelog.9656ae419100":"Bốn spec khả năng truy cập thất bại ở <code>page.goto</code> dù trang chẳng có gì sai: một <code>vite</code> khởi động lạnh biên dịch đồ thị mô-đun ở yêu cầu đầu tiên từ trình duyệt (đo được 19.5 s), và với bốn worker thì bốn spec cùng phải trả giá đó một lúc. Giờ <code>e2e/warm.setup.ts</code> biên dịch ứng dụng một lần trước bộ kiểm thử — a11y từ 4 thất bại/3 chập chờn lên <strong>9/9</strong>, và cả lượt chạy nhanh hơn, 4.7 phút so với 7.1.","changelog.aeb4521d29c5":"⚠ Lần thử đầu đặt phần loại trừ vào sai lớp cấu hình và lặng lẽ làm bộ sưu tập còn <strong>0 bài kiểm thử được thu thập</strong>, điều mà một cửa kiểm báo là đạt.","changelog.730e1894b827":"Thay đổi - sản phẩm giờ màu xanh lá, và đó là màu xanh của biểu tượng, 2026-09-16","changelog.b34d121fa3fb":"Mọi sắc tím trong ứng dụng, plugin và trang tài liệu đều đã biến mất. <code>#79D920</code> được <strong>lấy mẫu</strong> từ <code>images/freally-icon.png</code> — tâm có trọng số của các điểm ảnh xanh lá sáng trong đó — nên giao diện và biểu tượng trên thanh tác vụ là cùng một sắc xanh chứ không chỉ gần giống.","changelog.b9820271dd5a":"⛔ Giao diện sáng dùng màu xanh vùng bóng của biểu tượng, <code>#1A6B02</code>, vì <code>#79D920</code> chỉ đạt <strong>1.79:1</strong> trên nền trắng. Cùng phép tính ấy bắt được một lỗi thật: một nút thương hiệu có nhãn trắng viết cứng, không đọc được trên màu xanh mới, giờ dùng <code>--color-on-primary</code>.","changelog.17307457bdf8":"⚠ Các màu trung tính dịch theo sắc độ chứ không theo độ sáng, nên không khẳng định tương phản nào trong số 112 cái bị xê dịch. Màu xanh cyan của vạch phát cố ý được giữ nguyên.","changelog.97e593faa953":"Thêm - cái tên xoay ở đầu cửa sổ, 2026-09-16","changelog.a5f5f81eb744":"«FREALLY MIDI MASTER v1.0.0RC», được khắc nổi và xoay quanh trục Y ở chính giữa phía trên của ứng dụng. Đó là một khối đùn chứ không phải một phép lật — mười bản sao xếp chồng dọc theo trục Z, vì một <code>rotateY</code> đơn lẻ sẽ mỏng đi thành một sợi tóc ở góc 90° và trông như cái tên chớp tắt. Nó dừng hẳn khi có <code>prefers-reduced-motion</code>, giữ ở một góc nghiêng để độ sâu vẫn còn.","changelog.84bc48ed5549":"Thêm - clip fade vào và fade ra, với đường cong bạn uốn được, 2026-09-16","changelog.ef9458203075":"Mỗi clip trong bản phối Bài hát đều có fade vào và fade ra, mỗi cái có một tay nắm cho độ dài và một chấm cho hình dạng — để bản phối của một nghệ sĩ có thể được uốn thành của riêng bạn.","changelog.2cb75c827e48":"⛔ Hai đường không bao giờ cắt nhau được: một cặp cắt nhau không mô tả đường bao nào cả, nên khi chúng sắp chồng lên nhau thì cả hai thu nhỏ <em>theo tỉ lệ</em> thay vì một đường lặng lẽ xoá đường kia. <code>fadeGain</code> của trang phản chiếu chính xác <code>Fade::gain_at</code> của động cơ, nên hình vẽ và âm thanh là cùng một công thức.","changelog.3dfc5811a505":"Thêm - khung xem âm thanh của một clip giờ là âm thanh thật, 2026-09-16","changelog.6279a3048ed5":"Chuyển bản phối sang clip âm thanh và bạn thấy mỗi clip được kết xuất qua chính nhạc cụ của nó, nên bạn biết nó nghe thế nào trước khi kéo vào DAW.","changelog.ee37a55bde55":"⛔ Luồng trình chỉnh sửa không bao giờ kết xuất — 320 clip, mỗi clip nửa giây, sẽ làm treo phần mềm chủ. Plugin trả lời từ bộ nhớ đệm hoặc xếp việc vào hàng đợi, và dòng thời gian giữ bản phác nốt cho tới khi hình ảnh tới. «Thời gian thực» tự có được vì khoá của bộ nhớ đệm là clip <em>cùng âm thanh của nó</em>, nên vặn một núm là một lần kết xuất mới và không có gì phải thăm dò liên tục.","changelog.a9a5cc1bf02a":"⚠ Một thẻ trình duyệt giữ bản phác nốt mãi mãi: không có âm thanh nào được chuẩn bị ở đó.","changelog.7f09fbbe15e8":"Thêm - xác suất và dải lực nhấn theo từng nốt, 2026-09-16","changelog.750b30239ec8":"<strong>Bất kỳ nốt nào trong piano roll cũng có thể được gán một xác suất phát và một lực nhấn dao động.</strong> Mike: <em>«B5-2 — Cơ hội/xác suất theo từng nốt»</em>, <em>«B5-3 — Độ lệch/dải lực nhấn theo từng nốt»</em>. Xác suất được vẽ bằng phần nốt được tô đầy; dải là một vùng quanh đầu thanh của nốt trên làn lực nhấn.","changelog.38ee53053857":"⛔⛔ TỆP XUẤT CHỐT CỨNG KẾT QUẢ, VÀ LẦN NÀO CŨNG CHỐT THEO CÙNG MỘT CÁCH","changelog.a910d8608bd3":"Hoặc tệp <code>.mid</code> chốt cứng một lần gieo và hai lần xuất sẽ khác nhau — phá vỡ các ảnh chụp chuẩn và cửa kiểm <code>web_parity</code> giống hệt từng byte — hoặc tính năng chỉ có khi nghe thử và nói dối về thứ bạn sẽ nhận được.","changelog.a2258c7138d5":"▶ <strong>Cả hai vế của thế lưỡng nan đều giả định việc chốt cứng là ngẫu nhiên. Không phải vậy.</strong> Lần gieo là mã băm của hạt giống clip, lượt phát và chỉ số của nốt, và mọi lần xuất đều ghim lượt phát, nên tệp được chốt cứng <em>và</em> hai lần xuất giống hệt nhau. Ableton chốt cứng một cách không tất định; cách này tốt hơn hẳn mà không tốn gì. Một nốt chưa bị chỉnh sẽ bỏ qua hoàn toàn lần gieo thay vì lúc nào cũng thắng, điều giữ cho mọi ảnh chụp giống hệt từng byte.","changelog.431581274355":"Sửa - biểu tượng của bản độc lập lấy từ một tệp chưa từng tồn tại, 2026-09-16","changelog.a1f30e06011e":"<code>plugin/build.rs</code> bảo mọi người đọc hãy tạo lại <code>icon.ico</code> từ <code>images/freally_app_icon.png</code>, một tệp chưa bao giờ có trong repo này. Giờ nó ghi <code>images/freally-icon.png</code> — biểu tượng thật của sản phẩm.","changelog.d910c7246ee7":"⚠ Các mục trong <code>.ico</code> là DIB và được kiểm từng cái một: các mục nén PNG khiến trình biên dịch tài nguyên quay về biểu tượng Rust mặc định một cách <em>âm thầm</em>.","changelog.1ec023a53376":"Thêm - phiên của bạn đi theo bên trong tệp, 2026-09-16","changelog.fd23b1eb34b6":"Một tệp <code>.mid</code> hay <code>.wav</code> xuất ra giờ mang theo cả phiên đã tạo ra nó. Trong DAW nó là một tệp bình thường; mở ở đây thì nghệ sĩ, hạt giống, các giá trị ghim, tâm trạng, khoá, tắt tiếng và phân bổ pad đều trở lại — nên tệp mở lại như <strong>của bạn</strong> chứ không như nốt nhạc của ai đó. MIDI dùng <code>FF 7F</code>, loại mà trình đọc phải bỏ qua; âm thanh dùng một chunk RIFF đặt cạnh chunk <code>acid</code> vốn đã mang tempo. Thả lại một tệp <code>.wav</code> mà sản phẩm này đã bounce và phiên trở lại ngay lập tức thay vì một phút phân tích để ước lượng nó.","changelog.906d755eff63":"⛔ Một tệp ai đó gửi cho bạn là không đáng tin: khối dữ liệu có phiên bản và giới hạn độ dài, và một tài liệu sai dù chỉ một trường sẽ bị từ chối <strong>toàn bộ</strong>, vì một phiên áp dụng nửa vời là tên nghệ sĩ của bạn đặt trên các giá trị ghim của người khác. <code>midly</code> phân tích một tệp bị cắt cụt mà không kêu ca gì — 200 byte vẫn cho ra một tài liệu trông hợp lý — nên khối dữ liệu tự khai báo độ dài của chính nó.","changelog.7294c9f3bc34":"Sửa - nút Xuất trong trình duyệt không ghi được tệp, 2026-09-16","changelog.f9ee85761134":"Nhấn Xuất ở thẻ Bài hát trong trình duyệt lần nào cũng báo <em>«chưa có gì được tạo để ghi»</em>: một kho trạng thái phục vụ cả plugin lẫn thẻ trình duyệt và gửi <code>{ song }</code>, trong khi lớp tệp của thẻ lại đọc một danh sách <code>files</code> mà không gì gửi tới. Giờ nó kết xuất qua đúng lệnh mà thao tác kéo vốn đã dùng, nên tệp bạn tải về và tệp bạn kéo ra là cùng những byte.","changelog.98dc5d6ecb9c":"Sửa - thả một tệp <code>.mid</code> lên thẻ Bài hát của bản trình duyệt lưu sai thứ, 2026-09-16","changelog.f322f30777de":"<code>explorer_song</code>, <code>explorer_midi_split</code> và <code>explorer_midi_audition</code> đều được trả lời bằng kết quả <em>chia tách</em>, nên thẻ Bài hát nhận một danh sách các phần ở chỗ lẽ ra là một bản phối.","changelog.cd2c30298eab":"⚠ Cả hai lọt ra bản phát hành vì các spec phủ những nút đó chạy trên bản giả lập, vốn trả lời đúng. Lớp tệp của thẻ trình duyệt hoàn toàn không có bài kiểm thử nào; giờ nó khẳng định <strong>cấu trúc</strong> chứ không phải cái tên, vì cửa kiểm theo tên vẫn xanh với cả hai lỗi.","changelog.992288d62132":"Sửa - nút buộc tắt tiếng của chủ phòng không có tác dụng với ai cả, 2026-09-15","changelog.91b56d408438":"Buộc tắt tiếng, buộc tắt máy ảnh và mời ra khỏi phòng là ba nút không làm gì và không báo gì: trang đã gọi <code>collab_force</code> và <code>collab_remove</code> từ khi chúng được viết, còn plugin không trả lời lệnh nào. Trang hiểu mọi lời từ chối là <em>«không có sidecar»</em>, đó là lý do chưa ai từng thấy lỗi — kể cả một chủ phòng đang cố tắt một micro bị kẹt ở trạng thái mở. Giờ cả hai đều được trả lời, và một đối số sai định dạng bị từ chối thay vì dùng giá trị mặc định, vì mọi giá trị mặc định ở đây đều là một quyết định về máy ảnh của người khác.","changelog.63b986d4078b":"Sửa - một thông báo pháp lý không ai đọc được trong giao diện tối, 2026-09-15","changelog.362a34927497":"Ghi chú về cách hiểu tên gọi bên dưới ô chọn danh mục có cỡ ~10.9px và được tô ở tầng màu <strong>nhạt</strong>, tầng mà bảng màu dành cho chữ lớn. Nó đo được <strong>4.33:1</strong>, dưới mức 4.5:1 mà chữ nhỏ cần. Giờ nó dùng tầng màu chữ thân.","changelog.29cb2a06fe81":"⚠ Bộ kiểm thử khả năng truy cập chạy trên giao diện sáng, nơi cùng khai báo đó đo được 5.78:1 và đạt, nên giờ một khẳng định unit kiểm tra cả ba giao diện.","changelog.97a64162696b":"Sửa - cửa kiểm canh chừng các nút điều khiển chết không nhìn thấy phần cộng tác, 2026-09-15","changelog.b5db170b03d8":"<code>bridge_names.rs</code> quét mọi <code>invoke('name')</code> trong frontend — nhưng mọi mô-đun cộng tác đều truyền một <em>hằng số</em> qua một hàm trợ giúp, chính là để một cách viết không thể lệch đi giữa ba chỗ gọi. Chính quy ước làm cho những cái tên ấy an toàn lại là thứ che giấu chúng, và <strong>bảy lệnh được các nút điều khiển đã phát hành gọi tới mà không có gì trả lời.</strong> Giờ cửa kiểm phân giải được hằng số; hai lệnh được sửa ở trên, năm lệnh còn lại được liệt kê trong bài kiểm thử kèm lý do mỗi lệnh chưa được dựng, nên chỗ hổng được gọi tên dưới dạng chạy được thay vì bị lãng quên.","changelog.2296e280a445":"Thay đổi - tên track của một mẫu xuất ra ghi «phong cách», 2026-09-12","changelog.b9aa73561b5e":"Tên track được ghi <strong>bên trong</strong> một tệp <code>.mid</code> từng là <code>trap — Drums</code>; giờ nó là <code>trap style — Drums</code>, đúng sự phân biệt mà giao diện và tên tệp vốn đã làm. Tên một nghệ sĩ mô tả một phong cách, không bao giờ là dấu xuất xứ trên một tệp rời khỏi ứng dụng này.","changelog.a1c7a1a5e076":"⚠ Không một nốt nào dịch chuyển: bốn ảnh chụp chuẩn chỉ khác nhau sáu byte văn bản mỗi cái.","changelog.9d55f9efea57":"Thêm - File Explorer mở ở Danh mục, kèm các con số, 2026-09-11","changelog.8fe51cad16bc":"Trước đây nó mở ở các họ nhạc cụ theo bất kỳ thứ tự nào động cơ đang giữ, không có số lượng — còn các kệ thư viện, gói vòng lặp và bộ trống là một cây thư mục được vẽ <em>bên trong</em> trình duyệt nhạc cụ, nên hoàn toàn không tới được Gói gốc từ cấp trên cùng.","changelog.0297cd02ea56":"Giờ nó mở ở <strong>Danh mục</strong>, mỗi nơi một hàng, mỗi hàng cho biết trong đó có bao nhiêu: <strong>Nhạc cụ</strong> và bốn <strong>Gói mở rộng gốc</strong> (248 và mỗi gói 350), <strong>Gói trống</strong> (mười một bộ kit, 407 one-shot, lần đầu nghe thử được), và <strong>Gói gốc</strong> (5.085 vòng lặp MIDI). Các hàng xếp theo thứ tự chữ cái trong bất kỳ ngôn ngữ nào trong mười tám ngôn ngữ bạn dùng, và một ổ đĩa đã rút vẫn giữ chỗ của nó và được đánh dấu <strong>Không khả dụng</strong> bằng chữ chứ không chỉ bằng màu.","changelog.830c1bfc1fee":"Con số lấy từ động cơ, không qua bộ lọc — những gì có trên kệ, không phải những gì còn lại sau các chip — nên nó không đổi khi bạn nhấn <em>Bassline</em>.","changelog.371bd3942abc":"⛔ Được sửa bởi cùng thay đổi đó: các kệ rò sang nhau. <em>Gói mở rộng gốc 2 → Keys</em> liệt kê mọi nhạc cụ Keys trên cả năm kệ, vì kệ chỉ là một thư mục trên màn hình và hoàn toàn không có mặt trong truy vấn.","changelog.30193f2cd07f":"Thay đổi - giao diện ghi «phong cách», không phải «nghệ sĩ», 2026-09-11","changelog.61bd40930314":"Chín nhãn còn lại ghi <em>nghệ sĩ</em> trong khi ý là <em>phong cách</em> — <em>«Dùng tempo của nghệ sĩ»</em>, <em>«Bất cứ thứ gì nghệ sĩ viết»</em>. Tám nhãn đưa ra một khẳng định về một người thật. Giờ cả chín đều gọi tên phong cách, bằng cả mười tám ngôn ngữ, dùng từ riêng của mỗi ngôn ngữ.","changelog.094d4fef1e50":"Thêm - trang tài liệu bằng mười tám ngôn ngữ, 2026-09-11","changelog.3ec2581c410e":"Một bộ chọn ngôn ngữ trên mọi trang, đưa ra cùng mười tám ngôn ngữ như plugin, mỗi ngôn ngữ ghi bằng tên của chính nó.","changelog.d7aa7f80c47a":"Sửa - đặt tên tệp xuất không còn làm hỏng Cài đặt trong thẻ trình duyệt, 2026-09-11","changelog.8269f52c0420":"Bảng đặt tên tệp xuất hỏi thẻ trình duyệt một mẫu đặt tên và nhận về một cấu trúc khác với cái nó đọc, kéo sập cả bảng Cài đặt theo. Thẻ trình duyệt không có mẫu đặt tên — các tệp tải về được đặt tên trong động cơ — nên giờ nó nói rõ như vậy và bỏ mục đó ra.","changelog.756e358cd7bf":"Sửa - chuông ngân như chuông thay vì bị cắt cụt, 2026-09-10","changelog.f454ead481c6":"Một chiếc chuông nhà thờ chỉ ngân 3.2 giây trong khi các bồi âm của chính nó được chỉnh để ngân tới chín giây: nhả phím ra là kích hoạt bộ giảm âm, mà chuông tháp thì không có. Cồng, chuông dàn nhạc, steel pan và handpan cũng vậy. Giờ chuông nhà thờ ngân 6.6 giây, còn các nhạc cụ thực sự có giảm âm thì không bị động tới, vì làm ngắn âm thanh chính là mục đích của chúng.","changelog.bf56e0465d30":"Bản sửa đó làm lộ ra hai lỗi: <em>dừng tất cả</em> không còn tác dụng với những nhạc cụ ấy, nên một lần panic để một chiếc cồng ngân ở mức âm lượng tối đa — giờ panic và nhả phím là hai việc khác nhau — và uốn cao độ một nhạc cụ gõ làm đổi độ to của nó tới 7 dB, vì chỉnh lại cao độ một bộ cộng hưởng đang ngân cũng làm dịch mức của nó.","changelog.721f6099a36a":"⚠ Đã biết và chưa sửa: 107 trong số 118 nhạc cụ trong thư viện mang tên <em>Bell</em> hoặc <em>Chime</em> được dựng từ các bộ dao động hài thay vì các bồi âm không hài của tiếng chuông. Các bộ tạo chỉ dùng những cái được mô hình hoá.","changelog.a3790f42036f":"Sửa - núm pitch bend giờ uốn được cao độ, và ở yên chỗ bạn đặt, 2026-09-10","changelog.7eae79e5967e":"<strong>Mười hai trong mười ba động cơ nhạc cụ hoàn toàn phớt lờ bánh xe cao độ</strong> — mọi chuông, guitar, dây kéo vĩ, kèn đồng, piano, organ, giọng hát, máy trống và nhạc cụ đặc trưng, từ núm vặn được vẽ <em>lẫn</em> từ bộ điều khiển phần cứng. Một nhạc cụ mô hình hoá chỉ được báo cao độ một lần, và sau đó không có gì truyền bánh xe tới nó. Giờ các bồi âm của chuông, chiều dài dây của guitar và giọng của ca sĩ đều dịch chuyển, trong khi những phần không đi theo nốt vẫn đứng yên — thân đàn violin, các formant của giọng hát, hộp đàn kalimba.","changelog.28b122d799de":"<strong>Và núm vặn không còn phá công bạn.</strong> Trước đây nó bật về giữa khi nhả ra, đó là điều một bánh xe có lò xo giấu kín làm chứ không phải điều một núm vặn được vẽ ra kèm số hiển thị làm. Giờ nó giữ nguyên vị trí; nhấp đúp để đưa về giữa, như mọi núm vặn khác.","changelog.bfc70626288e":"⚠ Điều đó làm lộ ra một lỗi thứ hai, cũng được sửa ở đây: trên các nhạc cụ dùng dàn cộng hưởng hợp âm, nốt <em>thứ hai</em> của một câu chơi trong lúc giữ bánh xe bị cao lên một quãng năm. Trước đây không gì có thể tìm ra nó, vì bánh xe không thể vẫn đang được giữ khi phím kế tiếp được nhấn.","changelog.5acc9d14ec6b":"Sửa - bàn phím ảo lấp đầy khoảng trống được dành cho nó, 2026-09-10","changelog.d414fd02f3e7":"Cây đàn piano dừng lại giữa chừng và dính vào mép phải: hàng chứa nó đặt kích thước các phần tử con theo nội dung của chính chúng, nên bàn phím chỉ rộng bằng mấy nút quãng tám nhỏ phía trên thay vì rộng bằng ứng dụng. Giờ nó lấp đầy khung chứa ở mọi kích thước.","changelog.06900e6126d2":"Thêm - kéo một vòng lặp Gói gốc thẳng vào các mẫu của bạn, 2026-09-10","changelog.e811e0ddcc9f":"Trình duyệt gói có sẵn 5.085 vòng lặp MIDI và phát được từng cái, kéo được một cái <strong>ra</strong> DAW của bạn — nhưng không có cách nào đưa một cái <strong>vào</strong>, nên bạn nghe được beat mình muốn rồi phải dựng lại bằng tay. Giờ mỗi hàng vòng lặp đều là một nguồn kéo: thả nó lên một bộ tạo và nó được chia vào đúng các phần, y như một tệp <code>.mid</code> từ File Explorer.","changelog.aa75d339c210":"⚠ Thẻ Bài hát từ chối một vòng lặp và báo điều đó bằng con trỏ: Bài hát dựng bản phối từ các đoạn của một tệp, mà bốn ô nhịp thì không có đoạn nào.","changelog.470ee0ab09bc":"Sửa - mở được thư mục chia sẻ của người khác, và huy hiệu nói đúng sự thật, 2026-09-09","changelog.184268a38575":"Trình duyệt tệp dùng chung có client ở bản phát hành trước nhưng lẽ ra đã không thể chạy. Ba lỗi, đều vô hình vì trình duyệt giả lập được nạp tay các hàng theo cấu trúc của <em>trang</em> và không có gì so nó với những gì plugin gửi.","changelog.a159c8fdb762":"<strong>Không mở được thư mục nào.</strong> Plugin trả lời <code>kind: &quot;folder&quot; | &quot;sound&quot;</code> mà không có <code>isDir</code>, trong khi đó chính là thứ bảng đọc để vẽ mũi tên mở rộng — nên mọi thư mục gốc được chia sẻ đều hiện thành tệp, và câu hỏi «bạn có cái này không?» lại được hỏi về các thư mục.","changelog.806039630970":"<strong>Tệp nào cũng tự nhận chỉ dài một phần nhỏ của giây.</strong> Trường thời lượng của hàng không phải thời lượng: đó là độ dài được gập theo thang lôgarit vào khoảng 0 tới 1 để một one-shot và một vòng lặp bốn ô nhịp so sánh được với nhau. Nó từng được vẽ thành «0.35s». Giờ nó được đặt đúng tên và hiển thị không kèm đơn vị.","changelog.56c9265a4563":"<strong>«Bạn có thứ gì đó gần giống» chưa bao giờ có thể hiện ra.</strong> Thông báo đó cần bốn con số mô tả một âm thanh trong khi chỉ có dấu vân tay được gửi đi, nên một nhà sản xuất có bản FLAC của một gói mà họ sở hữu ở dạng WAV lại bị báo là không sở hữu nó.","changelog.ddf9187bb139":"⚠ Quy tắc của chủ sở hữu không đổi: <strong>không một byte sample nào đi qua lại giữa hai peer</strong> — chỉ mười sáu byte dấu vân tay và bốn con số.","changelog.67c4f1f163e5":"Sửa - một lần chập chờn Wi-Fi không còn làm kết thúc phiên cộng tác của bạn, 2026-09-09","changelog.658c8087a2ab":"Một gói tin bị rớt hay một máy tính xách tay thức dậy từ chế độ ngủ từng bị coi là người kia rời đi. Kết nối báo «disconnected» trong khi nó vẫn đang thử lại — một trạng thái được nói rõ là tạm thời và thường tự hết — vậy mà sidecar cắt luôn liên kết ngay lần đầu tiên. Giờ nó kiểm tra lại địa chỉ đang có trong tám giây, khiến một lần gián đoạn ngắn trở nên vô hình. Bất cứ gì lâu hơn vẫn là một lần rời đi thật: chỗ ngồi, tên hiển thị và màu được giữ trong hai phút như trước.","changelog.b55b8659f982":"Sửa - nạp một nhạc cụ sẽ hiện bàn phím và các núm vặn của nó, 2026-09-09","changelog.0b543bd7a5ca":"Thả một sample lên một bộ tạo, hoặc định tuyến một sample vào bằng <code>Ctrl</code>+<code>Arrow</code>, cho phần đó một giọng — nhưng hàng núm vặn định hình nó không hiện ra cho tới khi bạn chuyển thẻ rồi quay lại, vì các nút reverb, delay, drive và cao độ đang đọc một câu trả lời cũ cho câu hỏi «phần này đã phát ra âm thanh chưa?». Giờ nạp một nhạc cụ cũng mở luôn bàn phím trên màn hình, để có thứ mà chơi nó.","changelog.1af1ee74267d":"Thay đổi - hai hành vi trống tới được với những nghệ sĩ mà chúng được dựng cho, 2026-09-09","changelog.ec4815846944":"Một tiếng snare đệm và một backbeat chơi bằng clap đều đã được dựng nhưng không cái nào dùng tới được — không nghệ sĩ nào đòi cái nào. Giờ Art Blakey đệm snare, đúng như mục nghiên cứu về ông mô tả; Trina và Trick Daddy đặt backbeat lên clap, đúng điều mà mục của họ nói Miami bass làm.","changelog.6858345a1f88":"Sửa - giờ cùng một cài đặt sẵn nghe giống nhau ở cả hai lần, 2026-09-06","changelog.daafbdc5a835":"Nghe thử một cài đặt sẵn cho ra âm thanh hơi khác nhau sau mỗi cú nhấp — với các pad texture rộng bị lệch tông, chênh tới <strong>bốn lần mức âm lượng</strong>. Bắt đầu một âm thanh mới thì đặt lại delay và reverb nhưng để yên tính ngẫu nhiên của mọi giọng, mà tính ngẫu nhiên đó vừa là điểm bắt đầu của bộ dao động trong chu kỳ <em>vừa</em> là thứ nhiễu tạo nên tiếng trống, nên các giọng của một pad triệt tiêu nhau một lượng khác nhau mỗi lần phát. Giờ chúng lấy hạt giống từ cài đặt sẵn: cùng một âm thanh hai lần là cùng một âm thanh, và các nốt vẫn khác nhau giữa chúng.","changelog.3f7eb09bb886":"⚠ Hai cài đặt sẵn thực sự quá nhỏ tiếng để nghe thử khi phép đo đã đáng tin — <em>Pluck Coin</em> và <em>Frozen Cloud</em> — và cả hai được nhích lên.","changelog.449f05332b7d":"Sửa - không còn nhạc cụ nào bị lệch khỏi trung tâm, 2026-09-05","changelog.e606f1a76e95":"Một số âm thanh được kết xuất sẵn kèm <strong>độ lệch DC</strong> — dạng sóng bị dời khỏi đường tâm thay vì dao động quanh nó. Trên đồng hồ đo nó hiện thành độ to, với tai thì chẳng là gì, nó ngốn headroom và khiến bản mix cư xử lạ lùng vì những lý do không gì trên màn hình giải thích được. <em>Current Pad</em> tệ nhất ở mức −0.26 toàn thang, với bốn mươi hàng trên các Gói mở rộng có cùng hình dạng đó. Synth nào cũng loại bỏ điều này ở đầu ra; giờ Freally cũng vậy.","changelog.a6132c39d808":"⚠ Một số ít pad nhỏ tiếng hơn, và đó là bản sửa đang có tác dụng — một phần mức âm lượng của chúng là do độ lệch đẩy bộ bão hoà mạnh hơn. Không cái nào bị chỉnh lại âm sắc: chúng chỉ vấp phải một bước kiểm tra mức âm lượng vốn đo chúng khi mới lên được một phần năm của đoạn phồng mà nó cho 1.25 giây để hoàn tất. Giờ nó nghe trong bốn giây, như trình phát nghe thử.","changelog.a91d6c053bff":"Sửa - núm vặn, phím đàn và mọi nút điều khiển kéo khác, 2026-09-05","changelog.c585e5feb470":"Vặn một núm trên trang <strong>Synth</strong> có thể hoàn toàn không có tác dụng: nó sáng lên, nhận tiêu điểm, hiện một con số, nhưng âm thanh không bao giờ đổi.","changelog.8794dd5d5b82":"Mọi nút điều khiển kéo đều xin hệ điều hành giữ con trỏ suốt thao tác, để một lần kéo vẫn còn hiệu lực khi con trỏ trôi ra khỏi núm vặn — và yêu cầu đó được gửi <em>trước khi</em> nút điều khiển tự sẵn sàng. Trên máy nào yêu cầu bị từ chối, nút điều khiển không bao giờ bắt đầu lắng nghe và thao tác bị vứt bỏ. Mười hai nút điều khiển cùng mắc lỗi: các núm vặn, phím đàn, lưới trống, piano roll, làn lực nhấn, thước, trình chỉnh sửa đường bao, trình chỉnh sửa pad, các hàng kit, dải nghe thử, thanh chỉnh kích thước thanh bên và dòng thời gian bài hát. Giờ chúng sẵn sàng trước rồi mới xin sau.","changelog.1ba8e646a9fb":"Sửa - piano nghe ra piano, 2026-09-05","changelog.e02d9461473c":"Mọi cây piano đều có tiếng rè ở đầu thay vì tiếng gõ phím. Hai lỗi, cả hai đều được đo chứ không đoán:","changelog.0f157fbd683f":"<strong>Nốt tới ở âm lượng tối đa và cứ ở nguyên đó.</strong> Một dây đàn được gõ sẽ tắt dần ngay từ khoảnh khắc đầu tiên; dây này thì không — năm mili giây thứ hai còn <em>to hơn</em> năm mili giây đầu, vì độ tắt tức thời của dây được đặt ba giây và không thể tạo một điểm gãy gần phần attack.","changelog.96ba7fca5dbd":"<strong>Gần như không có hoạ âm.</strong> Một cây grand ở nốt C giữa chỉ mang nửa phần trăm năng lượng trên 2 kHz và gần như là một sóng sine; hoạ âm thứ mười biến mất sau sáu mươi mili giây và hoạ âm thứ ba mươi sau mười bốn.","changelog.85ae339fad0a":"Giờ tiếng búa to hơn và sáng hơn, trên đàn grand sáng hơn trên đàn upright, đó là khác biệt giữa hai bộ máy. Các dây đồng âm được chỉnh sát nhau hơn — độ toả cũ chênh lệch giữa các nốt đủ để nghe thành tiếng rung lắc.","changelog.7f16b5debe9e":"Sửa - nút Phát dưới trình duyệt tệp, 2026-09-05","changelog.032dc3a33890":"Nút Phát bên dưới trình duyệt và nút bên trong nó làm hai việc khác nhau, và nút bên ngoài thì sai: trên một tệp MIDI, nó phát tệp <code>.wav</code> nào bạn nghe thử gần nhất, dưới tên của tệp MIDI. Giờ cả hai đi qua cùng một cửa.","changelog.6e3d80e0d484":"Sửa - Đảo ngược giờ cho bạn thấy clip chạy ngược, 2026-09-05","changelog.7fc0fa7a1923":"Bật <strong>Đảo ngược</strong> làm đổi âm thanh nhưng để nguyên hình ảnh, nên chính nút điều khiển có nhiệm vụ phải hiển nhiên lại chẳng cho thấy gì. Giờ dạng sóng được vẽ từ cuối khi bật đảo ngược, vạch phát vẫn chạy từ trái sang phải, và nhấp vào một đỉnh sẽ phát đúng đỉnh bạn nhấp.","changelog.a67a54c25c17":"Thêm - trò chuyện thoại tìm được micro và loa của bạn, 2026-09-05","changelog.10fcf618e62d":"Nửa thoại của tính năng cộng tác có mọi thứ trừ phần cứng: bộ khử tiếng vọng, noise gate, codec và bộ đệm jitter đều đã được dựng mà không có gì điều khiển. Giờ trình trợ giúp phiên liệt kê các micro và đầu ra mà máy bạn báo, mở cặp bạn đã chọn, và đóng chúng ngay khi bạn tắt Giọng nói — nên đèn trên audio interface của bạn tắt đúng lúc bạn muốn. Đầu ra là một lựa chọn tách riêng với micro, vì loa kiểm âm và tai nghe là hai thứ khác nhau.","changelog.0772f73fd745":"⚠ Trò chuyện thoại cần thiết bị chạy ở 48 000 Hz. Nếu thiết bị của bạn không vậy, Freally sẽ nêu tên thiết bị và tần số thay vì lặng lẽ thất bại.","changelog.1ff4564ad0c5":"Sửa - vạch phát không còn đứng hình khi cửa sổ đang bận, 2026-09-05","changelog.a38a827fadc1":"Kéo thanh tiêu đề của bản độc lập làm vạch phát đứng hình cho tới khi bạn thả ra, rồi nó nhảy tới — trông y hệt như phát lại bị dừng rồi chạy lại. Thực ra không phải; âm thanh vẫn phát suốt. Vạch phát hỏi plugin nó đang ở đâu ba mươi lần mỗi giây rồi <em>chờ</em>, mà di chuyển một cửa sổ trên Windows sẽ chặn vòng lặp cửa sổ của ứng dụng, nên câu trả lời thôi tới trong khi luồng âm thanh không hề lỡ một phách. Giờ nó tiếp tục di chuyển theo tempo giữa các câu trả lời và tự hiệu chỉnh khi có câu trả lời tới.","changelog.8360bb400211":"⚠ Cùng kiểu treo đó có thể xảy ra bất cứ lúc nào cửa sổ của DAW đang bận, nên chuyện này không chỉ liên quan tới việc kéo.","changelog.df274a80a110":"Thêm - sample của riêng bạn, trên kệ của riêng bạn, 2026-09-05","changelog.10a7ad8818d9":"Trỏ Freally MIDI Master tới các thư mục bạn để one-shot và nó sẽ tìm ra những cái nào chơi được như nhạc cụ. Nhấn <strong>Tìm nhạc cụ trong thư mục của tôi</strong> ở Danh mục; nó báo tiến độ và bạn có thể dừng bất cứ lúc nào. Lượt thứ hai trên các thư mục không đổi diễn ra tức thì. Những gì nó tìm được sẽ nằm trên một kệ của riêng bạn, bên dưới bốn Gói mở rộng gốc, mang tên bạn.","changelog.9d27db12ab2d":"⚠ Một sample nhỏ tiếng vẫn được giữ — nhỏ tiếng là lựa chọn của bạn, và chỉ tệp hoàn toàn không có âm thanh mới bị từ chối. Bất cứ thứ gì dài quá mười giây đều bị bỏ ra: phát một sample thấp hơn sẽ <em>kéo giãn</em> nó, nên một pad tám giây hạ một quãng tám là mười sáu giây giữ cho mỗi nốt.","changelog.6209b0e7418a":"⚠ Việc quét cần đến plugin hoặc bản độc lập. Một thẻ trình duyệt chỉ mở được một thư mục mỗi lần và quên nó khi tải lại, nên chẳng có thư viện nào để nó duyệt qua.","changelog.376464b49a86":"Thêm - ứng dụng hỏi nên gọi kệ của bạn là gì, 2026-09-05","changelog.f7195bf33438":"Lần đầu tiên bạn mở Freally MIDI Master, ngay sau giấy phép, nó hỏi kệ của bạn nên được gọi là gì và sẽ không tạo nhạc cho tới khi bạn trả lời. Mọi thứ bạn lưu đều nằm dưới cái tên đó, và đổi tên sẽ đổi tên kệ — không có gì bị di chuyển và không có gì bị mất.","changelog.f38da5062167":"⚠ Nếu máy của bạn không cho ứng dụng lưu cái tên, nó giữ tên đó trong phiên, báo cho bạn biết và để bạn làm tiếp. Không có gì bị chặn chỉ vì một tệp nó không ghi được.","changelog.bf9a5273bae3":"Thêm - bảng KIT báo cho bạn khi một sample có slide, 2026-09-05","changelog.53f56fa197ef":"Thả một riser hay một 808 có slide lên một pad giai điệu thì trước đây ứng dụng sẽ tự tin tìm ra một nốt trong đó, rồi phát đoạn slide ấy ở mọi phím — mỗi phím một quãng khác nhau. Giờ nó đo xem sample có <em>giữ</em> cao độ hay không và ghi điều đó dưới pad: <strong>«Sample này không giữ một cao độ, nên phím nào cũng sẽ phát đoạn slide của nó.»</strong> Nó cho bạn biết thay vì từ chối tệp: một đoạn slide vẫn đáng để phát, chỉ là nó không phải một nhạc cụ.","changelog.74c665daca9f":"Thêm - những con số đằng sau một tay trống thật, 2026-09-05","changelog.6f4d1b6a2a74":"<code>data/humanize/groove.json</code> chứa những gì 1.150 màn chơi trống thật thực sự làm — với mỗi phong cách là một tỉ lệ swing, và với mỗi trống là nó lệch bao xa so với phần còn lại của bộ trống, nó chệch bao nhiêu, và một nốt ghost, một cú đánh chính và một trọng âm đo được bao nhiêu. <strong>Không có gì bạn đã làm thay đổi</strong>: không nghệ sĩ đi kèm nào dùng các con số mới, nên mọi hạt giống vẫn dựng lại đúng beat như trước.","changelog.6ad4570e7118":"⚠ Một phát hiện nghe ra được: pedal hi-hat của tay trống rơi sớm hơn phần còn lại của bộ trống 7–20 ms ở mọi phong cách được đo. Và một thứ cố ý vắng mặt — độ chệch của tay trống là ~15 ms dù là jazz hay punk, nên không có bảng độ lỏng theo thể loại, vì không tồn tại độ lỏng theo thể loại.","changelog.21279277c064":"Thêm - nghe một phong cách ngay khi bạn dựng nó, 2026-09-05","changelog.95e2355db08d":"Khi thanh điều khiển phát đang chạy, trình soạn phong cách phát những gì bạn đang dựng ngay trong lúc bạn dựng — kéo thanh swing hay đổi vị trí snare và vòng lặp kế tiếp chính là phong cách bạn vừa mô tả. Không có gì được lưu trong lúc đó, và bản thu của chính bạn trở lại ngay khi bạn đóng trình soạn, dù bạn có lưu phong cách hay không. Nghe thử là một âm thanh, không phải một thay đổi.","changelog.23f920ae884b":"Thêm - điện thoại có thể xin máy tính một tệp MP3, 2026-09-04","changelog.e2666ce60865":"MixSir vốn luôn ghi được phần phát lại của chính nó thành WebM, cách này chạy ở mọi nơi nhưng có một nhược điểm không gì sửa được: nó ghi theo <strong>thời gian thực</strong>, nên một bài ba phút mất ba phút. Khi ở cùng mạng với máy tính của bạn, giờ bạn có thể tải thẳng một tệp <strong>MP3</strong>, được mã hoá ngoại tuyến trên chính máy có âm thanh. Mỗi stem có nút riêng, nên gửi ai đó một bassline chỉ là một lần chạm thay vì một tệp WAV 40 MB.","changelog.a0fab848af1f":"⛔ Ba tệp, ba ý nghĩa, được ghi tên ngay dưới các nút: <em>Lưu bản mix của bạn</em> kết xuất mức cân bằng bạn vừa đặt, ngay trên điện thoại; <em>Lưu bản nhẹ</em> là mức cân bằng đó dưới dạng WebM theo thời gian thực; <em>Bản mix từ máy tính — MP3</em> là bản thu <strong>đúng như khi được tạo</strong>, mọi fader ở mức unity. Nhầm lẫn chúng sẽ lặng lẽ vứt đi bản mix bạn đã mất mười phút làm. Stem là ngoại lệ, và đó là lý do nó tốt nhất trong số đó: một stem ở mức unity <em>chính là</em> stem.","changelog.a33866df627b":"⚠ Không có gì được thêm vào plugin — bộ mã hoá nằm trong chương trình đồng hành, sau cờ tính năng riêng của nó, và một bước kiểm tra sẽ thất bại nếu điều đó không còn đúng.","changelog.fef58795ee93":"Thay đổi - bộ sàng tính mới đối chiếu với 47 melody thay vì 7, 2026-09-04","changelog.cada7f45de77":"Mỗi melody mà bộ tạo viết ra đều được lấy dấu vân tay theo <em>hình dạng</em> — chuỗi quãng và khoảng cách giữa các điểm khởi âm — và được đối chiếu với một bảng đóng gói sẵn trước khi bạn nghe; bản nào trùng sẽ bị bỏ và rút lại. Nó ra mắt với bảy melody thuộc phạm vi công cộng và 104 dấu vân tay, tức là một công tắc chạy được mà phía sau gần như chẳng có gì. Giờ nó chứa <strong>47 melody và 834 dấu vân tay</strong>, vẫn dưới mức năm mili giây mà nó hứa.","changelog.43f8d897f696":"⛔ <strong>Nó không phải là gì.</strong> Mọi melody trong bảng đều thuộc phạm vi công cộng, vĩnh viễn: sàng đối chiếu với một hook thương mại đồng nghĩa với việc rút ra đường nét của hook đó, mà một danh sách đường nét <em>chính là</em> dữ liệu nốt — điều duy nhất sản phẩm này không bao giờ được mang. Lớp chắn bắt được việc vô tình trích lại một giai điệu nổi tiếng. Nó <strong>không</strong> phải lý do khiến đầu ra là nguyên bản; lý do là động cơ dựa trên quy tắc, không có bản thu nào ở bất kỳ khâu nào.","changelog.239a6df00f04":"Thêm - bốn Gói mở rộng gốc, 1.400 nhạc cụ mới chơi được theo cao độ, 2026-09-04","changelog.0790681bb3a3":"<strong>Thư viện tăng từ 248 lên 1.648 nhạc cụ, và từ 410.688 cài đặt sẵn lên 2.729.088</strong> — vẫn không có lấy một tệp trên ổ đĩa, vì mỗi cài đặt sẵn được tính ra từ địa chỉ của nó. Chúng đến dưới dạng bốn kệ mới thay vì bị đổ vào các thư mục bạn đã quen: analog trừ âm; FM và digital thời đầu; texture, băng từ và bụi; và giọng hát cùng thân nhạc cụ thế giới, cộng thêm hai âm vực không gì khác dùng tới.","changelog.fb5ae337c7b0":"<strong>Chúng nghe như máy thật, không phải cài đặt sẵn</strong>, trong khi bản nháp đầu không có thứ nào trong bốn thứ làm nên điều đó: bộ dao động chạy <strong>tự do</strong>, nên không có hai nốt nào bắt đầu giống hệt nhau; bộ lọc <strong>bám theo bàn phím</strong>; <strong>lực nhấn mở bộ lọc</strong> thay vì chỉ tăng mức âm lượng, vốn là dấu hiệu lộ liễu nhất của một nhạc cụ tổng hợp; và một LFO thứ hai thêm một hai cent trôi dạt vào cao độ — không phải vibrato, chỉ là patch đang sống.","changelog.23d9f8efe0a6":"Không cái gì nghe giống cái gì khác, và điều đó được đo: cửa kiểm hiện có kết xuất mọi nhạc cụ ở mọi biến thể trong cả 69 thể loại và thất bại nếu có hai cái nào trùng dấu vân tay.","changelog.63aed5e7b3ac":"Thêm — Freally MIDI Master chạy trong trình duyệt, 2026-09-03","changelog.6392d72ebb78":"<strong>Cả ứng dụng, trong một thẻ trình duyệt, không cần cài gì</strong> — không phải bản demo và không bị cắt bớt. Trình duyệt chạy <strong>đúng crate mà plugin chạy</strong>, được biên dịch sang WebAssembly, nên một beat tạo trong thẻ trình duyệt và một beat tạo trong DAW của bạn là cùng những byte. Đó là một cửa kiểm chứ không phải lời hứa: <code>web_parity</code> tạo ở cả hai phía và so sánh tệp <code>.mid</code> từng byte một, kể cả các lời từ chối.","changelog.29825d1f51d3":"⛔ <strong>Hai điều trình duyệt không làm được</strong>, nói trước để bạn khỏi phải tự phát hiện theo cách khó chịu: không có <strong>Theo DAW</strong>, vì một thẻ trình duyệt không có thanh điều khiển phát của phần mềm chủ, và không thể thả thẳng một clip lên track của DAW. Cả hai giới hạn đều hiện trong ứng dụng và trong Cài đặt → Giới thiệu.","changelog.db4a975527be":"Thư viện tới thẻ trình duyệt nguyên vẹn — <strong>410.688 cài đặt sẵn</strong> — mà không tốn gì để chuyển tải, vì mỗi cài đặt sẵn đều được tính ra chứ không được lưu. Sau một lần truy cập, nó tạo nhạc được khi đã ngắt mạng, và cài được thành cửa sổ riêng. <strong>Hiến chương ngoại tuyến được sửa đổi ngay trong cùng thay đổi này</strong>: trang được <em>gửi tới</em> qua mạng, việc tạo diễn ra trên máy bạn, và không thứ gì bạn làm ra bị tải lên.","changelog.7fc622405ce4":"<strong>Các cửa tạo nhạc đã chuyển vào <code>engine</code>.</strong> <code>generate</code>, <code>generate_song</code> và <code>reroll_section</code> từng là nửa trước của <code>plugin/src/bridge.rs</code>; giờ chúng là <code>engine::compose</code>, được cả hai giao diện gọi, nên thẻ trình duyệt và DAW không thể lệch nhau.","changelog.24935964d5ea":"<strong>Thư viện nhạc cụ giờ là một crate riêng.</strong> <code>freally-library</code> chứa các cài đặt sẵn, hệ phân loại, giọng theo từng phần, bộ mã hoá WAV và bộ trống. Plugin xuất lại nó ở chỗ nó từng nằm.","changelog.acd41991926e":"<strong>Hai cửa kiểm mới trong cả hai bộ chạy CI cục bộ</strong>: target wasm dựng được, và thẻ trình duyệt được điều khiển từ đầu tới cuối trong một trình duyệt thật ở kích thước máy tính và điện thoại.","changelog.4aec523a2a62":"Thêm — giờ các nhạc cụ nghe như trên đĩa, 2026-09-02","changelog.6d0a65060c37":"Các nhạc cụ gốc được chỉnh lại theo số đo của sample chuyên nghiệp — hi-hat ngân bao lâu, trọng lượng của kick nằm ở đâu, tiếng dùi gõ tắt dần thế nào. Các nhà sản xuất đã bỏ qua vài nhạc cụ trong số đó, và các con số cho thấy lý do: hi-hat của máy trống <strong>ngắn hơn hi-hat thật từ ba tới năm lần</strong>, nên nghe như tiếng click chứ không phải hi-hat.","changelog.b042e5f2df6f":"<strong>Một lỗi nằm bên dưới bốn động cơ mới là chuyện lớn hơn.</strong> <code>decay</code> trên các động cơ modal, bộ gõ và bộ gõ thế giới, cùng <code>length</code> trên động cơ impact, đều được mô tả là một <em>hệ số nhân</em> có giá trị trung tính là 1.0 — vậy mà cái nào cũng bị kẹp với mức trần 1.0. <strong>Không âm thanh nào trong thư viện có thể ngân lâu hơn nhạc cụ thật.</strong> Marimba đo được 250 ms so với mức tham chiếu 510 ms và không nhúc nhích dù mô hình có đẩy mạnh đến đâu. Cả bốn đều đã được sửa, kèm một cửa kiểm sẽ thất bại nếu mức trần quay lại.","changelog.ef8652a0758c":"Giờ có <strong>248 nhạc cụ</strong>, tăng từ 225, cho <strong>410.688 cài đặt sẵn</strong>. Điều chế cao độ tìm được: 91 nhạc cụ phản hồi với nó và 157 thì không, thư viện lọc được theo nó, và hàng nào có nó đều mang một dấu.","changelog.3632677bb11b":"Thêm — 5.085 vòng lặp MIDI trong Gói gốc, 2026-09-02","changelog.81f74a7b5aa1":"Duyệt và nghe các vòng lặp trống, bộ gõ, bass, hợp âm, melody và melody đối thay vì tạo, nghe rồi lại tạo. <strong>Mỗi vòng lặp đều do chính các bộ tạo của ứng dụng này viết ra từ các mô hình phong cách của nó</strong> — chín megabyte nốt nhạc, không phải một gigabyte bản thu của người khác. Chọn một vòng lặp là nó phát và danh sách vẫn ở trên màn hình, nên có thể đi một mạch qua cả thư mục.","changelog.00e23d8a58a2":"<strong>Có hai thứ phải sửa trước.</strong> Trình duyệt vẽ ra các thư mục nhưng nhấp vào một hàng thì chẳng có gì xảy ra — bộ kết xuất và bộ đọc tệp đều đã xong nhưng không cái nào được nối vào. Và khi đã nối, mọi vòng lặp đều bị đọc thành vòng lặp <em>trống</em> bất kể thư mục, điều này tệ hơn vẻ ngoài của nó: một bassline nằm đúng chỗ kick, snare, clap và hi-hat trên bản đồ chuẩn, nên nó phát lại thành một beat hoàn toàn thuyết phục mà lại không phải là tệp đó.","changelog.c666d6acd7c9":"Thêm — thêm 189 nghệ sĩ và nhà sản xuất, 2026-09-02","changelog.b172c11f2b00":"Những người dựng riddim dancehall, amapiano, Jersey club, drum &amp; bass, house, reggaeton và các dòng Detroit và Michigan. Giờ có <strong>2.413 mô hình phong cách</strong> đi kèm.","changelog.1f6f98bb4f11":"Sửa — một phím đang giữ không bao giờ dừng, 2026-09-02","changelog.efe64f0af95b":"Nhấn một phím bên cạnh piano roll của bộ tạo phát ra một nốt không bao giờ dứt. Giờ nhả chuột sẽ dừng nó, kéo ra chỗ khác, cửa sổ mất tiêu điểm hay bảng đóng lại cũng vậy. Các phím cũng được ghi nhãn đúng: phím đen chữ trắng, phím trắng chữ đen, trên cả hai bàn phím.","changelog.0e9f1cb9b77e":"Sửa — trình duyệt vòng lặp suýt đã phát hành trống rỗng, 2026-09-02","changelog.f2656c4e7099":"Một thay đổi giúp gói vòng lặp không còn bị biên dịch vào ứng dụng hai lần — chín megabyte, trong mọi bản dựng — cũng khiến nó không còn được tìm thấy nữa. Trình duyệt lẽ ra sẽ vẽ ra một cây trống. Bị bắt bởi bài kiểm thử đếm tệp thay vì tin vào mã.","changelog.203799973680":"Thay đổi — bộ kiểm thử chạy chỉ mất một phần nhỏ thời gian so với trước, 2026-09-02","changelog.f050d1cd9b2a":"Không có gì nhà sản xuất nhìn thấy, nhưng đây là khác biệt giữa bắt được một lỗi trong vài phút và trong một giờ. Một cửa kiểm từng tạo lại ô nhịp của mỗi mô hình một lần cho mỗi mô hình khác mà nó được so sánh — <strong>từ 435 giây xuống 1</strong>. Các bộ kiểm thử độ đa dạng giờ dùng mọi lõi: melody <strong>576s → 60s</strong>, melody đối <strong>800s → 66s</strong>. Bộ chạy CI cục bộ cũng đặt các bước kiểm tra rẻ lên trước, nên một lỗi định dạng được báo trong vài giây thay vì sau cả bộ kiểm thử Rust.","changelog.fc2bc79afd01":"Sửa — cửa kiểm độ đa dạng chỉ phủ một thể loại trên sáu mươi chín, 2026-08-31","changelog.909b99ff0cc9":"Cửa kiểm chỉ chạy riêng House; Trap có những sub bass nghe giống hệt nhau mà nó không tìm ra gì vì nó chẳng nhìn tới gần chúng. Giờ có <strong>mỗi thể loại một <code>#[test]</code></strong> — 69 bài, quét qua <strong>372.600 cài đặt sẵn</strong>. Phải mất bốn vòng để chúng xanh:","changelog.128cc96e56d9":"<strong>Tám cặp nhạc cụ dùng chung một biến thể mô hình với tham số giống hệt nhau</strong> — trong đó có <code>Bell</code>/<code>ChurchBell</code>, <code>GrandPiano</code>/<code>AcousticPiano</code>. Chúng không chỉ giống nhau, chúng là cùng một patch mang hai cái tên, và giờ mỗi cặp được tách ra bằng chính điều thực sự phân biệt chúng.","changelog.b445820a134e":"<strong>Nới rộng jitter là bản năng sai, tới ba lần.</strong> Nó đưa số thể loại thất bại từ 56 xuống 13, và 13 cái cuối là hai lần rút tình cờ rơi gần nhau — điều mà jitter lớn hơn chỉ làm cho ít khả năng xảy ra hơn chứ không bao giờ là không thể. Giờ mỗi biến thể lấy một <strong>lát</strong> riêng trong dải nổi bật của nhạc cụ.","changelog.34ce292c4fde":"⚠ Cửa kiểm phân giải đủ mịn để bắt được điều đã được báo — hai mươi bốn biến thể của <code>Sub808</code> tương quan 1.0000 — và không phán xét liệu hai chiếc marimba nghe đã khác nhau có khác nhau <em>đủ</em> hay không.","changelog.e0c180b1af50":"Sửa — một nhạc cụ nghe như nhau trong cả 69 thể loại, 2026-08-31","changelog.36341f1261ab":"Đo được, và rõ đến trần trụi: cài đặt sẵn đặc trưng của <code>Sub808</code> tương quan <strong>0.9938</strong> giữa Trap và House, còn một cây piano acoustic đạt <strong>0.974–0.997</strong> trên toàn bộ danh mục. Nhánh mô hình hoá của <code>apply_genre</code> chỉ chạm được tới <code>filter.cutoff</code>, <code>filter.drive</code> và chuỗi FX — một bộ lọc mà mô hình vật lý hầu như không dùng và một chuỗi nằm <em>sau</em> nó — nên chẳng điều gì nó làm thay đổi cách một nhạc cụ được gõ, kéo vĩ hay thổi.","changelog.43cbc2d5c9d0":"<code>colour_modelled</code> ánh xạ thể loại lên các tham số <strong>riêng</strong> của từng động cơ. Với 808 là decay và glide: 808 trap ngân một ô nhịp hoặc hơn và trượt vào nốt, kick house thì gọn và không trượt, và các hồ sơ vốn đã mang điều đó dưới dạng <code>weight</code> — Trap <strong>0.88</strong> so với House <strong>0.60</strong>. Với piano là độ cứng của búa, đúng thứ mà tài liệu về chỉnh âm sắc bàn tới: Jazz ở <code>drive</code> 0.10 so với 0.70 của Metal. Một thể loại sáng hơn kéo các drawbar trên của Hammond lên; một thể loại gắt hơn gảy dây gần ngựa đàn hơn.","changelog.5e368038fb52":"⚠ Mỗi cú đẩy được dựng từ nhiều hơn một chiều của hồ sơ: một chiều đơn lẻ ở ±0.30 nằm dưới mức mà người nghe hay một dấu vân tay có thể phân biệt.","changelog.151c57cb8bd1":"Thêm — một cửa kiểm trên trục thể loại, và vì sao nó đếm chứ không cấm","changelog.0976e9520f58":"<code>an_instrument_sounds_different_in_every_genre</code> kết xuất cài đặt sẵn đặc trưng của mọi nhạc cụ trong cả 69 thể loại — 15.525 lần kết xuất — và đòi hỏi mỗi nhạc cụ phải nghe khác biệt trong ít nhất <strong>62</strong> thể loại.","changelog.171a63bd1519":"⛔ <strong>Một phép đếm, không phải lệnh cấm theo cặp.</strong> Đòi cả 2.346 cặp thể loại phải khác nhau đã thất bại ở <code>Jungle == Breakbeat</code> và <code>Cinematic == Downtempo</code>, những thể loại thực sự có chung tính cách — và viết ra một khác biệt giữa chúng chỉ để bài kiểm thử xanh chính là sai lầm đứng sau 396 mô hình nghệ sĩ bị hoàn nguyên. Điều được yêu cầu là một nhạc cụ không phải <strong>một</strong> âm thanh khoác 69 cái nhãn, và một ngưỡng dưới cho số lượng khác biệt nói được điều đó mà không bịa ra gì.","changelog.a04ef14ec8d1":"Sửa — phần nghe thử bị kết xuất lại từ đầu mỗi lần, 2026-08-31","changelog.642ec6d63dec":"⛔ <strong>Thư viện này không thể kết xuất sẵn, và con số là lý do.</strong> 225 nhạc cụ × 69 thể loại × 24 biến thể là <strong>372.600</strong> cài đặt sẵn; với bốn giây mono 22 kHz thì đó là <strong>61 GB</strong>, còn ở dạng số thực 48 kHz mà trình phát đọc thì là 266 GB. Nên một clip được kết xuất một lần rồi sau đó cư xử như đã kết xuất sẵn: <strong>trung bình 23.79 ms, tệ nhất 42.5 ms</strong> để kết xuất, so với ~0.1 ms để trả lại một bản đã giữ. Ba mươi hai clip, khoảng 24 MB — bấm mũi tên lên xuống một danh sách sẽ quay lại cùng một nhúm hàng, nên một bộ nhớ đệm nhỏ bắt được gần như mọi lần lặp lại.","changelog.10eb1736b8c9":"Thêm — ↑/↓ đi qua thư viện và phát mục mà chúng dừng lại, 2026-08-31","changelog.43b3eb09cc47":"Cùng thao tác mà cây thư mục đã có từ tháng 8, trong khi thư viện là danh sách duy nhất trong bảng mà hàng nào cũng phải nhấp. ⚠ Gắn vào listbox chứ không phải cửa sổ, nên nó không bao giờ kích hoạt khi piano roll đang dùng cùng các phím để xê dịch nốt.","changelog.6a4614d116ae":"Sửa — một nửa thư viện cài đặt sẵn là một âm thanh lặp đi lặp lại, 2026-08-31","changelog.0f63f6bd0158":"⛔⛔ **<code>modelled_defaults</code> hứa hẹn <em>«một chút nhân hoá theo từng cài đặt sẵn»</em> ngay trên dòng <code>let _ = rng;</code>** — một chú thích mô tả hành vi mà chưa ai viết. Lần tung lại mà nó gọi chỉ biết biến đổi một <em>wavetable</em>, thứ mà mô hình vật lý không hề đọc. Đo đạc cho thấy các biến thể 0–5 của <code>Sub808</code> <strong>giống hệt từng byte, tương quan 1.0000</strong>, trong khi wavetable của patch vẫn ngoan ngoãn thay đổi. Khoảng một nửa thư viện là mô hình hoá, nên một nửa trong 24 biến thể của mỗi tổ hợp là một âm thanh lặp hai mươi bốn lần. <code>randomize_modelled</code> dịch chuyển các tham số <strong>riêng</strong> của từng động cơ, dao động quanh giá trị mặc định của loại đó chứ không tung lại từ đầu, vì một biến thể là một <em>cách chơi</em> khác trên một nhạc cụ, không phải một nhạc cụ khác.","changelog.aafb4b3e7173":"⛔ <strong>Sub là một sóng sine, và tráo nó đi không phải là một biến thể.</strong> Lần tung lại của gói đã thay nó bằng sóng saw và chồng chín giọng lệch tông; ở 32 Hz, đó là cạnh sắc, phách và aliasing — đúng tiếng rè đã được báo.","changelog.99d2732af475":"⛔ <strong>Slap Bass và Pluck Bass dùng chung một nhánh</strong> và là cùng một patch mang hai cái tên. Giờ cả hai đều là dây bass điện, được tách ra đúng ở chỗ người chơi tách chúng.","changelog.c9eec0781f88":"Thêm — một cửa kiểm nghe cả 5.400 cài đặt sẵn trong một thể loại, 2026-08-31","changelog.d954c7fae943":"<code>no_two_presets_in_a_genre_render_the_same_sound</code> kết xuất mọi tổ hợp nhạc cụ × biến thể trong House — 225 × 24 — lấy dấu vân tay mỗi cái theo độ dài, mức âm lượng, độ dốc attack và tám tỉ lệ hoà âm, rồi khẳng định không có hai cái nào trùng nhau. 24 giây.","changelog.f1e878d4342a":"⛔ <strong>Nó phải nghe, chứ không đọc patch</strong>: các biến thể của 808 Sub khác nhau trên giấy, nên một dấu vân tay lấy từ <code>Patch</code> sẽ cho qua cả hai mươi bốn. Nó đã được kiểm <em>đối chiếu</em> với chính lỗi đó — khi tắt <code>randomize_modelled</code>, nó thất bại ngay lập tức và nêu tên các cặp bị trùng.","changelog.e32c895d315b":"Sửa — phần nghe thử không hứa đúng những gì bộ tạo phát, 2026-08-31","changelog.d0db0dc79e31":"<strong>Patch</strong> chưa bao giờ là vấn đề: phần nghe thử và bộ tạo dựng cùng một cài đặt sẵn. Thứ lệch nhau là mọi thứ chồng lên trên — <code>PartSound</code> mang reverb, delay, drive, điều chế cao độ, gain, pan và một ADSR, bộ tạo áp cả bảy còn phần nghe thử thì không áp cái nào, nên một phần vẫn còn khoác reverb của nhạc cụ trước sẽ phát nhạc cụ mới qua reverb đó. Giờ chọn một nhạc cụ sẽ đặt lại phần định hình âm, qua một cửa duy nhất mà cả nút <code>Use in …</code> lẫn <code>Ctrl</code>+→ đều đi qua.","changelog.25007f86466f":"⚠ Cố ý không theo quy tắc ở trên trong trình duyệt, vốn đọc âm thanh đã lưu của một phần trước để chỉ <em>chạm</em> vào một phần thôi không thể xoá các chỉnh sửa của bạn. Chọn một nhạc cụ mới là một hành động khác.","changelog.89099f78768b":"Thay đổi — thư viện mở ở Trap, và các thể loại xếp theo thứ tự chữ cái, 2026-08-31","changelog.49d670380403":"⚠ <code>genre</code> là một chỉ số trỏ vào một danh sách chưa tồn tại lúc giá trị mặc định của kho trạng thái được ghi, nên <code>0</code> chưa bao giờ có nghĩa là một thể loại — nó nghĩa là thể loại nào mà hệ phân loại liệt kê đầu tiên. Nó chuyển sang Trap khi hệ phân loại tới, và chỉ từ một <code>0</code> chưa bị động tới. Việc sắp xếp áp lên những gì được vẽ, không bao giờ lên những gì được lưu: thư viện cắt theo chỉ số của hệ phân loại, nên sắp xếp chính danh sách sẽ lặng lẽ trỏ lại mọi địa chỉ.","changelog.28cf77745a93":"⚠ Bản giả lập trả về <code>Genre 1 … Genre 69</code> — vốn đã xếp theo chữ cái và không có Trap, nên nó không thể kiểm thử quy tắc nào trong hai. Giờ nó trả về tên thật.","changelog.07bc5a7db520":"Sửa — nhạc cụ nào khi nghe thử cũng chỉ là cùng một tiếng bíp chưa tới một giây, 2026-08-31","changelog.3de906154cb6":"Triệu chứng là có thật và nguyên nhân không nằm ở phần tổng hợp: đo qua đường kết xuất thật, trọng tâm phổ của một cây piano acoustic nằm ở 1.32 so với 2.87 của clavinet, và việc định tuyến là đúng.","changelog.b68a797d6d3c":"⛔⛔ <strong>Thứ chúng có chung là hình dạng.</strong> Phần nghe thử mượn một bộ kết xuất định cỡ <strong>one-shot cho sampler</strong> — gate 0.6 s và đuôi 1.4 s. Nửa giây đủ để nghe một chiếc marimba nhưng còn lâu mới đủ để nghe organ, violin hay pad, những họ nhạc cụ mà bản sắc <em>chính là</em> những gì xảy ra sau attack — nên cả 225 nhạc cụ đều trả về những tiếng bíp chưa tới một giây, cùng cao độ và đỉnh xấp xỉ nhau.","changelog.c87553afd32f":"Giờ phần nghe thử giữ nốt của riêng nó, 1.5 s + 2.5 s: các độ dài trước đây đều là 0.6–1.0 s nay là 0.64 s cho clavinet và 1.84–1.91 s cho organ. ⚠ Nhạc cụ gõ không tốn thêm gì, vì nó bị cắt ở ngưỡng im lặng.","changelog.6fffbb4dd6a9":"Sửa — trình phát nghe thử chưa bao giờ hiển thị một nhạc cụ đang phát, 2026-08-31","changelog.06945748a71f":"Vòng thăm dò vạch phát hỏi <code>selected === null</code> — nhưng <code>selected</code> chỉ một <strong>tệp</strong>, và nghe thử một nhạc cụ thì cố ý xoá nó để bảng MIDI thôi mô tả một tệp <code>.mid</code> bạn không còn nghe nữa. Nên một nhạc cụ đang nghe thử bị hiểu là «không có gì đang phát»: không vạch phát, không thời gian đã trôi, không tua được, suốt cả clip. Giờ nó hỏi xem có <strong>dạng sóng</strong> nào được nạp không, điều đúng với cả hai đường.","changelog.bfe82ac019ab":"Sửa — mọi lần tạo trong bản độc lập đều ra 120 BPM, 2026-08-31","changelog.e1391ea65a06":"⛔ <strong>Bản độc lập của nih-plug có báo một tempo, và đó là giá trị mặc định 120 của <code>--tempo</code>.</strong> Chính phần đầu tệp của nó nói rằng không có gì để đồng bộ <em>theo</em>, vậy mà thanh điều khiển phát vẫn báo 120 ở mọi khối — nên tự đồng bộ khi không ghim trở thành một giá trị 120 đè lên mọi nghệ sĩ trong danh mục: suicideboys viết ở 125–160 mà được tạo ở 120, Drake 130–150 mà được tạo ở 120.","changelog.5d84da78d405":"Một dòng sửa được nó: tempo của phần mềm chủ mặc định là chuẩn mực, vì tempo của DAW không bao giờ được phép bị nghi ngờ, và bị bản độc lập xoá đi <strong>trừ khi người dùng tự chỉ định một tempo</strong> bằng <code>--tempo</code>, khi đó nó đúng là thứ họ yêu cầu.","changelog.d7a7889636c7":"Thay đổi — trình kiểm tra phong cách đã rời thanh bên trái, 2026-08-31","changelog.df3b5905432c":"Bảng góc dưới bên trái giờ chỉ hiện tên, thể loại, các âm giai và tempo của phong cách, không gì khác — đúng những gì <code>ArtistPane</code> vốn đã vẽ. Phần đổ tham số bên dưới đã bị bỏ; làm đẹp nhãn của nó hai lần vẫn không giải quyết được lời phàn nàn, vì bản thân các tham số không phải thứ người ta muốn.","changelog.95bc4d0e3982":"⚠ <code>StyleInspector</code> vẫn được giữ, chỉ là không gắn vào, nên khôi phục chỉ mất một dòng — và đi cùng nó là các giá trị ghi đè theo từng tham số và nút «Lưu thành phong cách của tôi» riêng của nó. Hộp thoại Trình soạn phong cách vẫn lưu được phong cách của riêng bạn.","changelog.d0654c4b85c2":"Sửa — nhấp vào một nhạc cụ để nghe cũng dựng luôn patch của nó, 2026-08-31","changelog.4d2ba450de39":"Một hàng trong thư viện từng gọi <code>select</code>, lệnh dựng patch trong Rust <strong>và</strong> tải lại trang synth — hai lượt đi về cho mỗi hàng, do một người chỉ đang nghe lướt qua danh sách phải trả. Phần nghe thử chưa bao giờ cần cái nào trong hai. Giờ một hàng chỉ nghe thử và tô sáng, không hơn, nên một nhạc cụ tới được bộ tạo bằng đúng một thao tác: nút <code>Use in …</code> hoặc <code>Ctrl</code>+→.","changelog.bc2c85aa41fb":"⛔ Và giờ nút đó đặt đúng vào chỗ các hàng nói. Nó đọc <code>activeTab</code> trong khi các hàng đọc <code>targetPart</code>, hai giá trị khác nhau ở trang SYNTH — nên nút ghi tên một bộ tạo còn danh sách bên cạnh lại ghi một bộ khác. Giờ nó cũng <strong>nạp</strong> patch; không có bước đó, bạn vẫn nghe nhạc cụ cũ cho tới khi tạo lại.","changelog.8d96a9b23a8a":"Sửa — một lần tạo có thể dùng một âm giai mà nghệ sĩ không bao giờ viết, 2026-08-30","changelog.0aa78e305fb2":"Động cơ vốn đã lấy mẫu một âm giai không ghim từ chính danh sách của mô hình, nên lỗ hổng nằm ở <strong>giá trị ghim</strong>: theo thiết kế, nó được giữ lại khi đổi nghệ sĩ và không có gì hỏi xem nghệ sĩ mới có viết bằng âm giai đó không. Chọn ngũ cung thứ cho trap rồi chuyển sang UK Drill sẽ tạo drill trong một điệu thức mà drill không dùng — và chip còn làm việc đó dễ dàng, khi đưa ra cả <strong>41</strong> điệu thức mà động cơ biết, trong đó trap chỉ viết bốn. Giờ chip chỉ đưa ra các âm giai của chính nghệ sĩ, và đổi nghệ sĩ sẽ <strong>bỏ</strong> giá trị ghim mà nghệ sĩ mới không viết.","changelog.8f482a9b2c0b":"⚠ Bị bỏ chứ không bị thay thế, trong khi tempo bên cạnh thì bị kẹp: một dải có giá trị hợp lệ gần nhất, còn một tập hợp thì không. Không có điệu thức nào «gần nhất» với phrygian, và tự bịa ra một cái nghĩa là ứng dụng đang chọn âm thanh thay cho nghệ sĩ. Chip tông không bị động tới — tông là dịch giọng, còn điệu thức là chính tính cách của bản nhạc.","changelog.2f2d6d4a01f2":"Thay đổi — «Không viết» đã trở lại trong bảng nghệ sĩ, 2026-08-30","changelog.7983a70d1982":"Đây là nửa ngăn sự im lặng: các bộ tạo bass, hợp âm, melody và melody đối đều trả về một track <em>rỗng</em> khi mô hình không viết khối tương ứng, nên một nghệ sĩ không viết bassline sẽ đáp lại lệnh Tạo trên thẻ đó bằng hoàn toàn không có gì.","changelog.4e9d74d07396":"⚠ Chỉ nửa phủ định. «Viết …» là danh sách bạn tự suy ra được từ các thẻ; «không viết …» mới là thứ thay đổi việc bạn làm tiếp theo, và nó chỉ hiện ra khi có gì đó còn thiếu.","changelog.3ebd75dbc890":"Sửa — hạt giống nằm đè lên bảng STYLE, 2026-08-30","changelog.60812270f2e2":"<code>.stage__controls</code> có kích thước nội tại 740px và từng là <code>nowrap</code> với <code>flex-shrink: 0</code> trên mọi phần tử con — một vật không thể xê dịch trong một track <code>1fr</code> nằm giữa hai thanh bên mà mỗi thanh bạn kéo được tới 560px. Một phần tử quá khổ trong flex container dạng cột sẽ tràn về phía <em>đầu</em>, nên nó vẽ lấn sang trái, đè lên thanh bên.","changelog.3d60f1aa0052":"⛔ <code>SeedChip.css</code> đã giải quyết được một nửa chuyện này nhưng bị lấn át: ô nhập hạt giống là <code>flex: 1 1 20ch</code> với <code>min-width: 0</code> chính là để nó có thể nhường lại một ký tự, còn <code>flex-shrink: 0</code> áp đại trà ở cấp trên khiến nó không bao giờ được hỏi tới. Giờ ô hạt giống xin <strong>10ch rồi nới ra</strong>, vì flexbox chọn chỗ ngắt dòng từ giá trị basis trước khi co lại. Hàng sẽ xuống dòng như phương án cuối cùng, điều trước đây nó chưa từng làm.","changelog.d69262d1a787":"Thay đổi — bảng nghệ sĩ nói ba điều, 2026-08-30","changelog.843ac4d32d6d":"Thể loại, âm giai và dải tempo — và <strong>mọi</strong> âm giai, trong khi trước đây nó chỉ hiện âm giai đầu tiên. Một nghệ sĩ chỉ viết ở thứ tự nhiên và một nghệ sĩ đi qua lại giữa thứ, dorian và ngũ cung thứ là hai người viết cùng rất khác nhau, và một mục duy nhất không phân biệt được họ.","changelog.150a5f8a6f30":"⛔ Những gì đã bị bỏ, nêu tên để không ai vô tình khôi phục lại: thời kỳ, tông đầu tiên, ghi chú half-time, các tâm trạng, và Viết / Không viết. Nó cũng chấm dứt một mâu thuẫn mà bảng này mang theo — nó ghi Bass cho 360 mô hình có 808 <em>chính là</em> bassline, trong khi thẻ Bass lại từ chối chúng.","changelog.db7b20c296bf":"Sửa — Drake được tạo ở 73 BPM, 2026-08-30","changelog.e6fd0aee8b1e":"Drake viết ở 130–150. Theo thiết kế, giá trị ghim tempo được giữ lại khi đổi nghệ sĩ và chỉ bị giới hạn trong dải 20–999 của Ableton, nên con số 73 mang sang từ một nghệ sĩ khác vẫn là 73. Giờ giới hạn nằm ngay trong nút điều khiển bạn đang nhìn, và đổi nghệ sĩ sẽ kéo giá trị ghim mang sang vào dải của nghệ sĩ mới — kẹp lại, không xoá đi, vì ai đã chọn đầu nhanh của một nghệ sĩ thì cũng muốn đầu nhanh của nghệ sĩ kế tiếp.","changelog.5d6b18a3616d":"⛔ Ban đầu đã thử đặt nó sâu hơn hai lớp và các bài kiểm thử bác cả hai. Trong hàm setter của kho trạng thái, ô tempo đặt một giá trị ghim ở <em>mỗi lần gõ phím</em> và chỉ kẹp khi rời ô — nếu không thì gõ «5» trên đường tới «50» sẽ bị sửa ngay dưới con trỏ. Trong động cơ, <code>reroll_section</code> đưa tempo <strong>của bản ghi</strong> qua cùng hàm đó, nên phép kẹp kéo một bài ở 155 xuống 145, từng đoạn một.","changelog.7831fdaa78c2":"Sửa — các nhạc cụ, cho mọi mô hình chứ không chỉ vài mô hình, 2026-08-30","changelog.6d061d82240b":"2.224 mô hình, và chỉ có melody từng được hỏi nó là gì. Ba phần còn lại đến từ một danh sách rút gọn theo thể loại chưa hề đọc gì về mô hình. Giờ mỗi phần trả lời từ khối riêng của nó:","changelog.32d6056dcb8e":"<strong>Melody đối.</strong> <code>styles</code> được viết trên <strong>1.876</strong> mô hình mà cho tới hôm nay chẳng nói gì về âm thanh. ⛔ Một tiếng vọng quãng tám được đáp bằng chính nhạc cụ của melody, vì đó <em>chính là</em> bản chất của một tiếng vọng quãng tám.","changelog.4d54431ef084":"<strong>Hợp âm.</strong> 696 mô hình thiên về hợp âm bảy, tức là phím đàn chứ không phải một pad sóng saw; một <code>vamp</code> là ai đó đang đệm và không thể là một pad.","changelog.23468091c213":"<strong>Bass.</strong> ⛔ <strong>Hoàn toàn không có nhạc cụ bass</strong> cho <strong>360</strong> mô hình mà 808 chính là bassline, vì động cơ từ chối phần đó đúng với những mô hình ấy. Được phát hiện qua một Pluck Bass trên $uicideboy$.","changelog.c1557e2ef5e3":"⚠ Melody đối có kệ riêng vì trước đây nó dùng chung kệ của melody, mà không danh sách lead nào có một pad, một dàn dây hay một dàn hợp xướng — nên 655 mô hình nói <em>«melody đối của tôi ngân dài»</em> đều được đáp lại bằng một Saw Lead.","changelog.3eb279716ce7":"Sửa — 120 BPM và 73 BPM nghe y hệt nhau, 2026-08-30","changelog.20ba9ed93269":"<code>Schedule::arm</code> đặt mọi nốt theo tempo lúc bản thu được <strong>tạo ra</strong>, và không có gì nạp lại lịch khi con số thay đổi: chip đổi, lần Tạo kế tiếp dùng nó, còn thứ gì đã nạp sẵn thì vẫn tiếp tục phát ở tempo cũ.","changelog.be97e25d3228":"⛔ Tempo là một chiếc đồng hồ, không phải một thiết lập tạo nhạc. Các nốt không dịch chuyển; đồng hồ thì có, đúng như những gì một DAW làm khi bạn kéo tempo của nó. Cùng việc nạp lại lịch phát ấy cũng giải quyết chiều ngược lại — khi bật tự đồng bộ, kéo tempo của dự án trước đây vẫn để plugin phát ở tempo lúc nó được tạo ra.","changelog.3b643d7c2f3d":"Sửa — ba chỉ số hiển thị và một thanh tiêu đề, 2026-08-30","changelog.97cc14c61e0e":"<strong>Trình kiểm tra phong cách chỉ là tệp JSON được khoác thêm một stylesheet.</strong> Bỏ <code>$schema</code> đi thì còn ba mươi hàng, hàng nào cũng bắt đầu bằng <code>arrangement.</code>, nửa hữu ích của mỗi đường dẫn nằm ở cuối, trôi ngang ra khỏi một thanh bên hẹp. Giờ khối đó là một tiêu đề và mỗi hàng đọc thành chữ — <code>Section bars › Hook</code>. ⚠ <strong>Giá trị</strong> không bị động tới: làm đẹp <code>[4,8]</code> thành «4 hoặc 8» sẽ khiến một ô có thể sửa nói dối về những gì nó nhận.","changelog.0affc50612cd":"<strong>Dòng trạng thái cho biết âm thanh là của ai</strong> — <em>«Nhạc cụ có sẵn: Tambourine»</em>, <em>«One-shot của bạn: 808long.wav»</em> — đó là điều người đang quyết định mình được phát hành gì cần biết.","changelog.469d7247448c":"<strong>Trình phát nghe thử</strong> được ghim ở chân trình duyệt tệp: thanh bên cuộn được, nên một thư viện có mục yêu thích đã đẩy thanh điều khiển phát ra khỏi tầm nhìn, không còn nút Dừng nào trên màn hình trong khi plugin vẫn phát.","changelog.83ea9df0754e":"<strong>Thanh tiêu đề mang biểu tượng Windows mặc định</strong>, vì thanh tiêu đề lấy biểu tượng từ lớp cửa sổ còn <code>baseview</code> đăng ký một lớp không có biểu tượng. ⛔ Chỉ ở bản độc lập — trong DAW, cửa sổ đó thuộc về phần mềm chủ.","changelog.8db43618eb5d":"Sửa — những nhạc cụ mà một nghệ sĩ thực sự nạp, 2026-08-30","changelog.124d7acd17d3":"⛔⛔ <strong>Melody của Drake là Hand Bell còn melody đối của anh ấy là Recorder.</strong> Ba lỗi, đã đo:","changelog.d4d7ff8f906c":"<strong><code>melody.timbreHint</code> không có ai đọc.</strong> Nó được viết <strong>1.966 lần với 252 giá trị khác nhau</strong> mà <code>grep</code> chỉ tìm thấy nó trong các bài kiểm thử, nên âm thanh của mọi mô hình đều được rút từ cả 77 nhạc cụ phục vụ phần có cao độ. Giờ nó đã được đọc: danh từ thành nhạc cụ còn từ bổ nghĩa thành âm sắc.","changelog.cb4b176767c3":"<strong>Lần rút dự phòng không hề biết nó dành cho thể loại nào.</strong> ⚠ Bản đầu tiên lọc theo <em>họ nhạc cụ</em> mà vẫn sai — họ Keys có cả bandoneon, nên hợp âm của Drake ra thành <strong>Bandoneon</strong>.","changelog.9ec8b19d2a99":"<strong>Biến thể được rút trong khoảng 0..23</strong>, dù mã vẫn luôn nói biến thể 0 là cài đặt sẵn đặc trưng, nên mặc định của một nghệ sĩ lại là một trường hợp lạc loài của bất kỳ nhạc cụ nào họ nhận được.","changelog.83d8f379ed55":"▶ Đo sau khi sửa: melody của Drake là một Electric Piano mềm, của Future là một Bell sáng, của Adele là một Grand Piano ấm. Động cơ chưa bao giờ là vấn đề — 179 trong 225 nhạc cụ vốn đã định tuyến tới một mô hình vật lý.","changelog.d24230b7e18c":"Thêm — các chỉ dẫn của đêm đó, 2026-08-30","changelog.94468f71b792":"<strong>Nghe thử dạng one-shot cho các nhạc cụ có sẵn.</strong> Trình duyệt nghe thử được mọi tệp <code>.wav</code> trên ổ đĩa mà không nghe được một nhạc cụ nào trong 225 nhạc cụ. ▶ Ba mảnh ghép đã có sẵn trong mã nguồn mà chưa bao giờ được nối lại.","changelog.d9630357c37d":"<strong>Một nốt nghe thử riêng cho từng nhạc cụ.</strong> Bảng trả về C4 cho mọi thứ trừ bass, nên tuba và piccolo được nghe thử trên cùng một nốt.","changelog.a0f4946b92e6":"<strong>Một thanh trạng thái ở chân trang.</strong> Con số <code>1.1.00</code> ở góc đó là vị trí phát nhưng trông như số phiên bản. ▶ Vùng live lấp đầy thanh này vốn đã viết những câu ấy từ trước mà chưa từng hiển thị cho ai.","changelog.24e91666084b":"<strong>Giờ máy đếm nhịp rơi đúng phách</strong>: tiếng click từng được kích ở đầu khối nào chứa phách đó, tức là lệch tới <strong>43 ms</strong> với chu kỳ 2048 khung của bản độc lập.","changelog.40c605708dea":"<strong>Một làn kit có thể được chọn làm đích định tuyến</strong>, và <code>Ctrl</code>+→ gửi nhạc cụ đang chọn tới đó. Không có gì đi ngược vào một bộ tạo.","changelog.8a97e46ad351":"Sửa — ba chỉ số hiển thị đang nói dối, 2026-08-30","changelog.13efc12c8cad":"<strong>Trình kiểm tra phong cách từng liệt kê <code>$schema</code> và khối nghiên cứu.</strong> Giờ nó bỏ qua phần sổ sách của tệp và nguồn gốc nghiên cứu; <code>era</code> và <code>genres</code> vẫn ở lại, vì bộ chọn nhạc cụ đọc chúng.","changelog.31e9eda443e8":"<strong>Trình chỉnh sửa đường bao vẽ các tay nắm ở hai đầu chỉ còn một nửa.</strong> Một tay nắm nằm đúng ở giá trị của nó, nên sustain ở 0 dB nằm trên mép trên còn release ở mức tối đa nằm bên phải, với năm đơn vị của hình tròn nằm ngoài viewBox. Giờ khung có lề.","changelog.5ba045b1b88b":"<strong>Bảng kit ghi «Tích hợp» bất kể nghệ sĩ đã nạp gì</strong>, vứt bỏ cái tên mà trình nạp cài đặt sẵn đã trả về.","changelog.3f52a91cd88b":"Thêm — những thứ bắt buộc phải có của v1.0.0, 2026-08-29","changelog.fd9a52e845e2":"<strong>Khoá theo từng tham số.</strong> Khoá <em>tiết tấu</em> rồi tung lại cao độ, hoặc ngược lại. ⛔ Được ghép bên trong <code>withLocks</code> chứ không phải ở từng cửa, nên Tạo và Tạo tất cả đều có nó ngay từ cấu trúc — một quy tắc cài ở cửa này mà không ở cửa kia là kiểu lỗi mà repo này đã ghi lại bảy lần.","changelog.17455804e395":"<strong>Vai trò one-shot dựa trên nội dung.</strong> Khi tên tệp không nói lên gì, sample được phân loại từ sáu đặc trưng DSP đọc được và bảng in ra lý do: <em>«808 · 1.9 s · 62 Hz · 4% nhiễu»</em>. ⛔ Là các ngưỡng, không phải một bộ phân loại, và tên tệp luôn thắng.","changelog.3ba97e819e31":"<strong>Trình kiểm tra phong cách</strong>, với mỗi giá trị đều ghi rõ mô hình nào cung cấp. ⛔ Một giá trị ghi đè được áp sau chế độ và trước lint, nên một chế độ không thể lặng lẽ đè lên giá trị bạn vừa ghim.","changelog.b3fc14e1aaf9":"<strong>Biên nhận nguồn gốc.</strong> Mặc định tắt, được ghi cục bộ, không bao giờ gửi đi đâu.","changelog.e9eeec6e1529":"<strong>Trình chẩn đoán tệp bị thiếu.</strong> ⛔ «Đã xác minh» và «khớp theo tên» là hai khẳng định khác nhau và được vẽ khác nhau, vì chỉ một mã băm được ghi lại <em>trước khi</em> tệp biến mất mới chứng minh được một ứng viên.","changelog.4c2e5321dca4":"<strong>Chơi nốt vào.</strong> ⛔ Điểm khởi âm được bắt vào lưới còn độ dài thì không — kéo giãn một nốt đã chơi cho khớp lưới chính là điều khiến đầu vào được lượng tử hoá nghe như máy.","changelog.8c0513f107b0":"<strong>Đồng tác giả một phong cách.</strong> ⛔ Một bản diff đặt trên mô hình gốc, không bao giờ là bản sao: một bản sao sẽ đóng băng các giá trị mặc định của hôm nay, và mọi cải tiến về sau của mô hình cha sẽ lặng lẽ không còn tới được nó.","changelog.beb404bfb850":"Đã kiểm chứng là đã có sẵn","changelog.9c1a0003d15a":"FMM-S01 (sampler trong plugin), FMM-S02 (bỏ qua để chỉ xuất MIDI, và tắt tiếng âm thanh theo từng làn trong khi MIDI vẫn chảy) và FMM-S03 (kéo ra gốc cho MIDI và âm thanh đã kết xuất) đều đã được phát hành dưới các mã nhiệm vụ trước đó.","changelog.18fb79233d8e":"Thêm — nút ghi, máy đếm nhịp, và một phím chơi cả hợp âm, 2026-08-26","changelog.55c7530e6073":"<strong>Ghi lại những gì bạn chơi, vào clip của phần đó</strong>, từ bàn phím trên màn hình, một bàn phím MIDI hoặc các phím máy tính. ⛔ Một nốt giữ qua điểm lặp vòng vẫn là một nốt, không bị cắt ở vạch nhịp, và <strong>lượt thứ hai sẽ ghi chồng</strong>. Cả hai đều xuất phát từ một quyết định: thời gian được đếm từ lúc bắt đầu ghi và chỉ được đổi thành vị trí khi nốt được ghi xuống.","changelog.29e9a0b6f948":"⛔ <strong>Chỉ có Huỷ bỏ mới làm trống một bản thu.</strong> Một trình ghi một lượt tự nuốt mất bản thu của chính nó là kiểu lỗi mà nhà sản xuất nào cũng từng gặp ở công cụ khác và sẽ thử ngay trong ba mươi giây đầu.","changelog.2339bbf1e7ae":"<strong>Một máy đếm nhịp bên cạnh.</strong> ⛔ Nó là công cụ hỗ trợ nghe kiểm và không bao giờ có thể lọt vào bản mix đã kết xuất, tệp kéo ra hay gói xuất ra.","changelog.6136b9c1d42c":"<strong>Một phím chơi cả hợp âm.</strong> ⛔ Chỉ có một bộ dựng hợp âm, trên luồng âm thanh; trang chỉ gửi nốt gốc và không bao giờ gửi một hợp âm, vì một bản sao các nửa cung của âm giai bằng TypeScript sẽ chính là bộ dựng thứ hai mà điều này tồn tại để ngăn chặn.","changelog.fd3543d53681":"<strong>Nhãn hợp âm trên roll và trên phím đàn.</strong> ⛔ Tông lấy từ phiên, không bao giờ từ các nốt: C–E♭–G là <code>i</code> ở C thứ và <code>vi</code> ở E♭ trưởng, và một nhãn nhấp nháy qua lại giữa hai cách đọc còn tệ hơn không có nhãn.","changelog.0c3159dec9e4":"Bảo mật — ba lối vào một phòng lẽ ra không được tồn tại, 2026-08-27","changelog.f18e6a3e8b22":"⚠ Chưa lỗi nào chạm tới được trong một bản dựng đã phát hành, nhưng mỗi lỗi là một lỗ hổng thật trong phần mã vốn đã xong, và mỗi lỗi đều được sửa kèm một bài kiểm thử tái hiện nó.","changelog.866ebdbc95a0":"⛔⛔ <strong>Một phản hồi lời mời được dán vào có thể mạo nhận danh tính của chủ phòng.</strong> Mã peer của phản hồi do chính người tạo ra nó viết, và nó dễ đoán tới mức tầm thường vì phòng và chủ phòng được tạo từ cùng một lần đọc đồng hồ — <code>room-&lt;t&gt;</code> làm lộ luôn <code>me-&lt;t&gt;</code>.","changelog.839fdc680905":"⛔⛔ <strong>Một khách có thể ký thay cho thành viên khác.</strong> Một khung tín hiệu ghi tên peer mà nó nói tới và cái tên đó được tin luôn, nên một khách có thể chiếm chỗ chủ phòng trong bảng kết nối của nạn nhân. ⚠ Một bài kiểm thử đã khẳng định hành vi cũ là đúng; nó đang ghim cho lỗ hổng luôn mở.","changelog.21f5bf6627b0":"⛔⛔ <strong>Người vào muộn có thể bị chỉ sai người kế nhiệm</strong>, vì danh sách thành viên mà họ nhận được xếp theo chỗ ngồi chứ không theo thứ tự đến.","changelog.2a4225044c45":"<strong>Tệp cổng của sidecar có quyền <code>0600</code> trên Linux</strong>, được tạo ra đúng như vậy chứ không phải thu hẹp quyền sau đó.","changelog.ae9b66d28161":"Sửa — trình ghi, ở lần xem lại thứ hai, 2026-08-27","changelog.bf75d500547e":"Lỗi nào cũng nằm trong mã vừa phát hành, và bản sửa nào cũng có một bài kiểm thử thất bại với hành vi cũ.","changelog.06a1e90fa8d5":"⛔⛔ <strong>Một bản thu rơi vào chỗ bạn nhấn ghi, không phải chỗ bạn chơi.</strong> Đồng hồ bắt đầu từ nút bấm chứ không phải từ thanh điều khiển phát, nên một hợp âm chơi ở phách mạnh của ô nhịp 4 sau khi bật ghi ở ô nhịp 3 lại vào clip lệch đi một ô nhịp.","changelog.df8e2475b858":"⛔ <strong>Mọi nốt sau nốt thứ 1.024 trong một lượt đều bị bỏ</strong>: bước chuyển giao đẩy con trỏ lên trước khi kiểm tra xem nốt đã được đặt chưa.","changelog.a60f121ecd2e":"⛔ <strong>Một bản thu chơi trên hai bộ tạo bị dồn về một</strong>, vì động cơ đã phát ra từng nốt bị vứt bỏ để nhường cho thẻ nào đang mở.","changelog.398bb76fb6e9":"⛔ <strong>Một nốt bị nút panic cắt lại kéo dài tới hết bản thu</strong>, nên một hợp âm 200 ms bị ghi thành một nốt kéo dài suốt cả bản ghi.","changelog.e8057c8ad5f1":"<strong>Vòng lặp quay lại sai điểm ở mọi nhịp không phải <code>x/4</code>.</strong>","changelog.225cbcabcd7f":"Sửa — bản dựng cho trình duyệt, và một fixture nói dối, 2026-08-27","changelog.6cff7080b85d":"⛔⛔ <strong>Bảy lệnh cầu nối không có fixture, nên trình ghi và chế độ hợp âm chết hẳn bên ngoài plugin</strong> — trong <code>vite dev</code>, bản dựng web và mọi lượt chạy end-to-end — mà không có gì báo đỏ, vì mỗi chỗ gọi đều nuốt lỗi. Roll xin nhãn hợp âm ngay từ trong bước vẽ của nó, nên cứ mỗi khung hình là một lần gọi bị từ chối, suốt vòng đời của trang.","changelog.dd41a2bcdfe7":"⛔ <strong>Sau đó fixture lại từ chối ba mươi lăm trong bốn mươi mốt âm giai</strong>, nên chế độ hợp âm vẫn chết với bất kỳ ai ghim Dorian, và nó gọi tên hợp âm bằng dấu thăng trong khi động cơ gọi bằng dấu giáng. Một fixture có thể trả lời khác với thứ thật là điều duy nhất nó không được phép làm.","changelog.8dae7783d759":"<strong>Sửa một pad của một rack dẫn xuất đã đặt lại bảy pad còn lại</strong>, vĩnh viễn, vì bố cục đã sửa từ đó luôn thắng.","changelog.130d4f5e7331":"<strong>Một dự án mới gọi tên mọi hợp âm theo C</strong>, vì «chưa đặt tông» bị gửi đi thành «tông C».","changelog.dbf257322b22":"Thay đổi — trang quyền riêng tư nói rõ những gì thực sự rời khỏi máy, 2026-08-27","changelog.a78636091f9d":"⛔⛔ <strong>Nó từng ghi «không có máy chủ STUN nào được cấu hình và không có mặc định nào được biên dịch vào». Điều đó không đúng.</strong> Bản dựng có sẵn hai máy chủ — Cloudflare và Google — và liên lạc với một trong số đó khi bạn mở hoặc tham gia một phòng, nên nó có thể biết rằng một địa chỉ nào đó đang dùng một ứng dụng WebRTC. Không biết bạn đang nói chuyện với ai, và không biết bạn gửi gì. Giờ cả hai được nêu tên trên trang bằng cả mười tám ngôn ngữ, kèm thời điểm chúng được liên lạc và những gì chúng biết được.","changelog.48cff82da9bd":"⚠ Một bài kiểm thử đã khẳng định đúng câu sai sự thật ấy, đó là cách nó tồn tại được. Thứ vẫn còn nợ, và giờ đã nói rõ, là một cài đặt để thay đổi hoặc tắt chúng.","changelog.0b9b24ca1f7c":"Thêm — nhạc cụ có thêm bàn phím, một thư viện bạn lưu vào được, và một rack sample, 2026-08-23","changelog.bbd370386f96":"<strong>Bốn nhạc cụ cùng lúc.</strong> Melody, Melody đối, Bassline và Hợp âm mỗi phần sở hữu một <code>SynthEngine</code>. ⚠ Đo được <strong>26% của một khối 128 khung</strong> cho bốn phần với 16 giọng.","changelog.8d4e8720aff1":"<strong>Lưu một âm thanh</strong> dưới một danh mục và tên do bạn chọn. ⛔ Một <em>âm thanh</em> là một nhạc cụ; một <em>cài đặt sẵn</em> ở thanh bên phải là một phiên đã lưu. Khác thư mục, không bao giờ chung một danh sách.","changelog.8945b84546af":"<strong>PACK — một rack sample 25 ô</strong>, được kết xuất ngoài luồng của trình chỉnh sửa, có thanh tiến độ và nút Huỷ, và các bản kết xuất gần như im lặng bị loại trước khi vào rack.","changelog.b0679c7fd0e5":"<strong>Chơi vào từ phần cứng.</strong> ⛔ Một nốt bị dịch giọng vượt quá hai đầu sẽ bị bỏ, không bị vòng lại: một nốt bị vòng lại là một nốt sai và không có gì trên màn hình báo điều đó.","changelog.0a8a403c1283":"<strong>AIFF, 24-bit, số thực 32-bit và tần số tới 192 kHz.</strong> ⛔ Một vòng lặp được kéo ra vẫn luôn là WAV 16-bit, vì chỉ WAV mới mang chunk <code>acid</code> giúp nó vào đúng tempo của chính nó.","changelog.becd79896add":"Sửa — bốn lỗi không ai đi tìm, 2026-08-23","changelog.5aa574085b3e":"⛔⛔ <strong>Một dự án mở lại ghi tên một âm thanh mà nó không phát.</strong> <code>part_sounds</code> được khôi phục cùng phiên, nên bảng trở lại hiện nhạc cụ đã gán — nhưng không có gì gửi lại patch, nên mọi động cơ vẫn ở âm thanh khởi tạo. Pan cũng chưa bao giờ tới được luồng âm thanh.","changelog.e41b41f68e79":"⛔⛔ <strong><code>Shift+ArrowUp</code> không có tác dụng trên macOS là do tranh chấp khi đọc lại, không phải do phím bổ trợ.</strong> Mỗi lần ghi giá trị núm vặn đều đi một vòng rồi đọc lại, và phản hồi của một lần ghi có thể tới sau một chỉnh sửa mới hơn và ghi đè lên nó. Giờ bước kiểm tra diễn ra khi phản hồi tới. Shift chỉ làm lỗi lộ ra: một bước thô bị hoàn nguyên rơi vào chỗ sai rõ ràng, còn một bước tinh bị hoàn nguyên thì vẫn nằm trong dung sai.","changelog.8da0d11157f2":"<strong>Tệp WAV số thực 32-bit bị từ chối vì «đã nén»</strong>, điều đó không đúng, và đó lại là định dạng mà phần lớn DAW bounce ra.","changelog.eab27dba438d":"<strong>Gain, pan và đường bao theo từng phần hoàn toàn không tác động tới âm thanh nào.</strong>","changelog.33498857d52b":"<strong><code>MAX_EXTRACT_SECONDS</code> 60 → 300</strong>, dựa trên phép đo chứ không phải nhích thử. Bộ nhớ đỉnh khi phân tích từng được biện minh là «gấp vài lần độ dài đã giải mã»; đo bằng một bộ cấp phát theo dõi đỉnh thì nó là <strong>1.2×, không đổi</strong> — 13.9 MB với một phút, 69.5 MB với năm phút. ⛔ Nó vẫn <strong>từ chối</strong> chứ không cắt bớt: năm phút đầu của một tệp bảy phút sẽ là một phỏng đoán được trình bày như một bản ký âm.","changelog.034ba0a65cf5":"<strong>Reverb, delay và drive chỉ được hiển thị trên một nhạc cụ gốc</strong>, vì sampler không có chuỗi hiệu ứng và trên sample của riêng bạn chúng sẽ chẳng thay đổi gì.","changelog.975e6e71fd3a":"Thư viện dùng chung của plugin đã chuyển sang crate riêng. ⛔ <code>cargo test --workspace --release</code> đã không liên kết được suốt nhiều tháng — 413 tham chiếu ngoài không phân giải được — vì <code>panic = &quot;abort&quot;</code> và một target <code>[&quot;cdylib&quot;, &quot;lib&quot;]</code> khiến Cargo dựng một thư viện hai lần vào cùng một tên tệp.","changelog.2cecc0c1d888":"Các tệp zip tải về có kèm <code>INSTALL.txt</code>.","changelog.38fbbc3ec4b5":"Sửa — một <code>secondaryAnchor</code> được kế thừa đã ngốn toàn bộ ngân sách kick của mô hình con, 2026-08-22","changelog.37aab3338c62":"⛔⛔ <strong>129 mô hình đi kèm giờ tạo ra một kick khác.</strong> <code>drums.kick.anchors</code> là một mảng, nên mô hình con viết mảng riêng sẽ thay thế mảng của mô hình cha — nhưng <code>secondaryAnchor</code> là một giá trị vô hướng riêng nằm cạnh nó, nên nó sống sót qua lần thay thế đó và bị hợp lại vào. Một mô hình nói <em>«anchor của tôi là 1 và 3»</em> lại nhận 1, 2&amp; và 3, và ở chỗ điều đó lấp đầy ngân sách mật độ thì mọi cú kick đều thành chắc chắn và làn đó thôi biến đổi. Đo trên <code>darius-rucker</code>: <strong>92 hình kick khác nhau trong 200 hạt giống</strong> trên nền của chính anh ấy, <strong>4</strong> trên một nền có anchor phụ là <code>&quot;2&amp;&quot;</code>.","changelog.7b1e2aadc5b3":"Một mô hình con viết <code>anchors</code> mà không viết <code>secondaryAnchor</code> sẽ không còn kế thừa trường đó. 34 thể loại viết trường này và 282 mô hình viết anchor riêng với một ngân sách mà một anchor phụ được thêm vào sẽ lấp đầy, nên đây chưa bao giờ là vấn đề của riêng một mô hình.","changelog.42019e6efdae":"Sửa — màn hình Giới thiệu ghi công một bộ dữ liệu mà sản phẩm không dùng, 2026-08-22","changelog.e38cc70c3c1f":"Ở cả mười tám ngôn ngữ, nó ghi <em>«Thống kê thời điểm và lực nhấn lấy từ Magenta Groove MIDI Dataset»</em>. <strong>Điều đó không đúng</strong>: bộ nhân hoá được viết tay từ nghiên cứu kỹ thuật đã công bố, và công cụ lẽ ra sẽ đọc GMD chưa bao giờ được viết. Đã gỡ khỏi bảng Giới thiệu và khỏi <code>docs/credits.md</code>. Ghi công là nghĩa vụ khi bạn <em>dùng</em> một tác phẩm; ghi công một tác phẩm bạn không dùng là một khẳng định sai về nguồn gốc các con số của sản phẩm.","changelog.36015e08f729":"Thêm — nhãn trong File Explorer, và cuối cùng thư mục báo sập cũng được đưa ra cho bạn","changelog.1e983e7b7fd6":"<strong>Nhãn.</strong> Thêm và gỡ nhãn trên tệp đang chọn có tự hoàn thành, và lọc cây thư mục theo nhãn hoặc dấu sao. ⛔ Một thư mục không bao giờ thoả bộ lọc nhãn chỉ nhờ tên của nó: bộ lọc nhãn là một phát biểu về <em>tệp</em>, nên một thư mục tên <code>808s</code> không được để lọt lại các tệp chưa gắn nhãn bên trong.","changelog.3ef25c4b3313":"<strong>Thư mục báo sập được đưa ra cho bạn thay vì bị giấu đi.</strong> Panic hook và error boundary đều đã ghi các báo cáo mà chẳng có gì từng đọc.","changelog.8d8b9b03bc3f":"<strong>Mỗi lần tạo được thông báo cho trình đọc màn hình</strong>, trước đây chúng không nhận được gì — lưới là một canvas và mọi thứ khác đều chỉ là hình ảnh.","changelog.20ad24384bcf":"<strong>Clip mới mở ra với độ dài của chính bạn.</strong>","changelog.6e286b860c79":"<strong>Các tâm trạng được khai báo trước khi huấn luyện, không suy ra sau đó.</strong> Đọc ngược chúng từ các bản thu đã giữ là trả lời câu <em>«bạn đã tạo ra gì»</em> chứ không phải <em>«quy trình này là gì»</em>, nên một phong cách huấn luyện trên hai mươi bản dark và một bản bounce tự ghi mình là cả hai.","changelog.273946b10440":"<strong>Thêm mười bốn nghệ sĩ dòng ngầm</strong> — rage, opium và jerk — đưa danh mục lên <strong>1.317 mô hình</strong>.","changelog.50f34d3336e8":"Thêm — ba cửa kiểm bịt những lỗ hổng không ai canh chừng","changelog.12458ceaee7b":"<strong>Không tên gọi khác nào được trùng với tên riêng của một mô hình khác.</strong> Với 1.317 mô hình, điều này cần được ép buộc bằng thứ gì đó ngoài sự cẩn thận. ⚠ Nó chỉ thất bại với một kiểu trùng: một tag nhóm gọi tên nhiều mô hình là cách hợp lệ để tìm tới một nhóm người.","changelog.5b575339b3de":"<strong>Không có <code>std::net</code> trong mã Rust của chính chúng tôi</strong>, dưới dạng một <code>clippy.toml</code>. Mọi bước kiểm tra phụ thuộc đều mù trước một socket mở qua <code>std</code>, vì nó không liên kết gì và không phân giải gì mới trong <code>Cargo.lock</code>. ⚠ Một bản quét văn bản mã nguồn được viết trước rồi bị bỏ đi: nó không phân giải gì cả, nên <code>use std::net as n</code> lọt qua sạch sẽ.","changelog.8ba8228a27d5":"<strong>Năm từ mà hướng dẫn giọng văn cấm dùng.</strong> ⛔ Lần chạy đầu tiên bắt nhầm cả câu chữ <em>đúng</em> — «Re-roll every unlocked pad» — nên quy tắc nhắm vào động từ kiểu startup và dạng danh động từ của nó, không bao giờ là quá khứ phân từ: sản phẩm này có khoá thật.","changelog.6951117e4210":"Thêm — thêm mười ba tham số mà bộ dữ liệu đã viết nhưng chưa đoạn mã nào đọc, 2026-08-18","changelog.02b8b216112f":"Mười ba khoá đã được gạch khỏi sổ nợ, trên khoảng <strong>1.600 thiết lập đã viết</strong> mà không làm gì cả.","changelog.22595cc7e4a2":"<strong>Rimshot dưới tiếng snare</strong> (231 mô hình), nhân đôi backbeat ngay trên phách chứ không phải bên cạnh — rimshot dưới snare là một chiếc trống được đánh theo hai cách.","changelog.759a885d7eed":"<strong>Thời gian glide của 808</strong> (105 mô hình). Drill bật trong 20–35 ms còn afroswing lượn qua 130–220, vậy mà tất cả đều phát ra loa thành «phần còn lại của nốt» vì quãng trượt bị viết cứng ở ba chỗ. ⚠ Rút một lần cho cả bản thu, không theo từng nốt: rút theo từng nốt sẽ dịch vị trí rng của 105 mô hình ở mỗi lần slide — một khoá về <em>âm sắc</em> lại viết lại <em>cao độ</em> của chúng.","changelog.46c9a98765f4":"<strong>Backbeat được khoá</strong> (5 mô hình), để phách 2 và 4 đứng yên trong khi các nốt ghost quanh chúng được thở.","changelog.712e506631ab":"<strong>Four-on-the-floor ở đoạn hook</strong> (29) và <strong>phiên khúc cross-stick</strong> (74), cả hai đều gọi tên một đoạn mà phần trống chưa từng thấy. ⛔ Cross-stick <em>dời</em> backbeat sang vành trống thay vì nhân đôi nó, chính điều đó làm phiên khúc nhẹ hơn điệp khúc.","changelog.d833b34971a3":"<strong>Độ chỉnh âm của snare</strong> (7 mô hình). ⛔ Sổ đăng ký xếp mục này vào 808, nơi mà ghi nó vào sẽ làm lệch tông một <em>bassline</em> — ra một nốt sai chứ không phải một âm sắc.","changelog.86a977b8200a":"Sửa — những gì lượt duyệt tìm ra, 2026-08-18","changelog.b6906fa13a4e":"⛔⛔ <strong>Một tiếng trống phát ở cao độ không đổi trong plugin nhưng lại đổi cao độ trong stem xuất ra.</strong> Một số nốt phục vụ hai bên đọc: phần mềm chủ, vốn cần <strong>giọng GM</strong> của trống, nếu không một tiếng kick đi cao độ sẽ kích bốn trống khác nhau trong rack của bạn; và sampler nghe thử, vốn đọc cùng con số đó để quyết định đổi cao độ pad bao xa. Khi bị ghim vào GM, mọi tiếng trống đều phát ở cao độ không đổi <em>chỉ trong phần nghe thử trực tiếp</em>, trong khi bản kết xuất đổi cao độ đúng.","changelog.f91f216318eb":"⛔⛔ <strong>Một đoạn phiên khúc chơi cross-stick làm tắt luôn quy tắc dừng của chính 808.</strong> Backbeat được viết thẳng lên làn rim, trong khi 808 đọc các cú snare mà nó không được ngân đè qua — nên trong phiên khúc danh sách đó trả về rỗng và 808 ngân kéo qua đúng cú đánh mà drill được định nghĩa bằng việc dừng lại vì nó.","changelog.df60688769f5":"⛔ <strong>Nhịp four-on-the-floor của đoạn hook đã viết lại ngữ pháp riêng của kick từ ô nhịp 2</strong>, vì các nhịp thêm vào rút lực nhấn từ cùng dòng mà mọi ô nhịp sau đó đọc.","changelog.c566b1219e10":"⛔ <strong>Một lần tung lại đã rút lại độ dài vòng lặp của bản ghi</strong>, nên một đoạn được tung lại trở về với độ dài clip khác và phần đuôi của mỗi lần lặp rơi vào im lặng.","changelog.6bafa094d3d1":"Thay đổi — sổ nợ ghi đúng những gì thực sự còn nợ, 2026-08-18","changelog.9c4c6538b967":"Bốn mục đã cũ hoặc sai: <code>timbreHint</code> ghi 21 mô hình nhưng thực ra là <strong>1.234 lần được viết</strong>, khoá đã viết mà không ai đọc lớn nhất trong bộ dữ liệu; nửa <code>true</code> của <code>monoCutSelf</code> vốn đã chạy, thứ chưa được đọc là bốn mô hình viết <code>false</code>; <code>minimalism</code> và <code>chordFrequency</code> bị xếp sai cấp, và cái sau được cả 590 mô hình kế thừa. Ba mục giờ được đánh dấu là <strong>câu hỏi dành cho Mike</strong> thay vì việc cần làm, vì mỗi mục hoặc đè lên một khoá mà chính mô hình đó viết, hoặc không có tác dụng gì.","changelog.148f80ce9161":"Thêm — mười sáu tham số mà bộ dữ liệu đã viết nhưng chưa đoạn mã nào đọc, 2026-08-18","changelog.5a6d1f5a2389":"<strong>Nốt chùm giờ là một kiểu diễn tấu riêng.</strong> Ba cửa kiểm cần phân biệt một nốt hoa mỹ với phách mà nó bao quanh nhưng không cửa nào làm được: đánh dấu là roll thì nó bị tính là <em>fill</em>, đánh dấu là ghost thì bị tính là snare <em>đáp lại</em> backbeat, còn để không đánh dấu thì nó chính là backbeat — nên một bài kiểm thử đã lặng lẽ bắt đầu đo một nốt hoa mỹ rộng một nốt 1/32 như một cú xê dịch và lẽ ra sẽ cứ tiếp tục qua vì một lý do sai.","changelog.da3d109cb5d7":"<strong>Cụm snare</strong> (19 mô hình), dấu hiệu nổi bật của jerk. ⛔ Căn giữa quanh phách chứ không bắt đầu trên phách, nên backbeat được bao quanh thay vì bị kéo trễ.","changelog.3af1edb2e147":"<strong>Dải lực nhấn riêng của từng làn</strong>, <strong>lớp sub của kick</strong>, <strong>một phách bị bỏ qua</strong> (43 mô hình) và <strong>một 808 phớt lờ kick</strong> (15). ⛔ 808 lọc theo chính các điểm khởi âm của kick, nên phép khoá chỉ có thể làm sub <em>thưa hơn</em> — không bao giờ dời được nó.","changelog.ce23805b3729":"⛔ <strong>Mỗi cái rút từ dòng ngẫu nhiên có hạt giống của riêng nó.</strong> Việc phá quy tắc đó bị bắt ở cách hai làn: lực nhấn của lớp sub làm dòng của kick tiến lên, kick dịch chuyển, bassline đi theo kick, và một mô hình tụt xuống còn 946/1000 bassline khác nhau so với ngưỡng 950 — một cửa kiểm bassline thất bại vì lực nhấn của một tiếng trống.","changelog.3838ea6a725f":"Sửa — hai lỗi panic có thể bị gây ra từ một mô hình sửa bằng tay, 2026-08-18","changelog.5d8e80129d6f":"<strong>Một khoá không phải ASCII trong mô hình của người dùng làm DAW chủ dừng đột ngột.</strong> Bộ lint duyệt mọi khoá của mọi mô hình, kể cả mô hình được nhập vào hay sửa bằng tay, và cắt ba byte cuối — thao tác này panic khi chỉ số rơi vào giữa một ký tự nhiều byte. Bản phát hành được dựng với <code>panic = &quot;abort&quot;</code>, nên DAW sập luôn, ở <strong>mỗi lần khởi động</strong>, cho tới khi tìm ra tệp đó và xoá đi. Giờ phép so sánh làm theo byte. ⚠ Không mô hình đi kèm nào có khoá không phải ASCII, nên CI sẽ không bao giờ thấy lỗi này.","changelog.9ca14e5ed251":"<strong>Một độ dịch rộng hơn mức <code>f64</code> có thể trừ được đã gây panic bên trong <code>rand</code>.</strong> Một khoảng <code>[-1e308, 1e308]</code> tới được bộ lấy mẫu, nó tính <code>high - low</code>, nhận <code>inf</code>, rồi unwrap một lỗi. Giờ một giới hạn duy nhất phủ cả ba khoá độ lệch.","changelog.df3a55b59625":"Sửa — một phong cách trống rỗng không còn lưu được nữa, 2026-08-18","changelog.58a45134d22e":"Một bản nháp không nói thêm gì ngoài những gì nền của nó đã nói, mở ra khi không có beat nào trên màn hình, sẽ bị từ chối kèm lý do thay vì được ghi. ⛔ Đánh dấu một âm giai cố ý không được tính là nội dung: danh sách âm giai mà trình soạn đưa ra được thu hẹp về chính các âm giai của nền, nên mọi âm giai bạn đánh dấu được đều là âm giai nền của bạn đã dùng.","changelog.4dd7f6210e64":"⛔ Đo so với bản nháp mà hộp thoại mở ra cùng, không phải so với một biểu mẫu trống — bản đầu tiên làm sai điều này theo cách khiến quy tắc gần như không bao giờ kích hoạt, vì bản nháp lấy swing khởi đầu từ giá trị mặc định của mô hình đang chọn và có sáu trên 1.303 mô hình tình cờ trùng khớp.","changelog.7da6467e020c":"Thay đổi — hai chi phí khi nạp bộ dữ liệu đã được đo và loại bỏ, 2026-08-18","changelog.7355c12f6bd4":"Bộ lint không còn cấp phát một con trỏ JSON cho mỗi khoá của mỗi mô hình — trước đây nó dựng một con trỏ đầy đủ dù có phát hiện nào hay không, cộng thêm một bản sao viết thường của mọi khoá. Và <code>resolve_all</code> hợp nhất mỗi chuỗi tổ tiên đúng một lần: 534 trong 590 mô hình là nghệ sĩ dựa trên vài chục khuôn mẫu thể loại, và mô hình nào cũng làm lại cùng một lần hợp nhất.","changelog.715106ffd3f6":"Sửa — một melody đối ngân dài không còn vào ở cùng một chỗ mỗi lần, 2026-08-17","changelog.7ad05d0e7f17":"Một melody đối kiểu <code>sustain_pad</code> giờ tự chọn chỗ vào trong câu nhạc. Trước đây điểm vào là tick đầu tiên mà giọng chính để trống — cùng một đáp án cho mọi hạt giống rút ra cùng độ dài câu — nên trên một vamp, nơi cả bốn ô nhịp là một hợp âm, một phần ba số hạt giống nhận được một nốt giữ ở cùng một chỗ. Chỉ riêng vì thế mà hai mươi bảy mô hình nằm ngay dưới ngưỡng đa dạng của melody đối; giờ hai mươi ba mô hình đã vượt qua mà dữ liệu không đổi gì.","changelog.c4353fab112d":"⚠ Điểm vào được chọn trong <em>nửa đầu</em> của câu nhạc: một pad vào ở ô nhịp cuối của câu thì không phải pad, và độ dài là toàn bộ điều mà <code>sustain_pad</code> khẳng định. Đáp án cũ được giữ làm phương án dự phòng cho một giọng chính legato tới mức nửa đầu không còn chỗ nào, nên không pad của mô hình nào bị im lặng.","changelog.be20007c0663":"Thêm — những phần mà một bộ tạo đáp lại, và bốn khuôn mẫu mà nghiên cứu còn nợ, 2026-08-15","changelog.a6502afe501a":"<strong>Tạo một melody đối sẽ lấp đầy melody mà nó đáp lại, cùng phần hoà âm mà cả hai được viết theo.</strong> Động cơ vốn luôn kết xuất những phần đó dù bạn có nhấn Tạo hay không, nên một melody đối trong phiên mới lại đáp lại một thứ không ai nghe được. ⛔ Phần lấp đầy lấy từ RECORD, không phải một bản thu mới, nếu không thẻ sẽ hiện một melody khác với melody mà nó đáp lại.","changelog.a5ea6391fc17":"<strong>Mười một khuôn mẫu thể loại mà nghiên cứu từng phải đi vòng</strong>, đưa bộ dữ liệu lên <strong>61 thể loại và 602 mô hình</strong>. Thiếu sót hệ trọng nhất là <strong>Techno</strong>: Jeff Mills, Robert Hood, Underground Resistance, Carl Craig, Derrick May, Juan Atkins và Kevin Saunderson đã bị bỏ ra vì không có chỗ nào hợp lệ để đặt họ. ⛔ Động cơ cũng không viết được Lowend — snare ở phách 1 và 3 không khớp vị trí nào nó biết. ⚠ Techno và Dominican Dembow được phát hành ở mức <code>confidence: low</code> và nói rõ lý do.","changelog.d0cb1f806314":"<strong>Một công tắc Đơn giản / Dày cho cả bốn bộ tạo có giai điệu.</strong> ⛔ Nó co giãn trong phạm vi mỗi mô hình đã viết và không bao giờ đè lên — <em>«một vamp rage bị làm cho dày đặc thì không còn là rage»</em> — và trạng thái ở giữa trong ba trạng thái của nó chính là mô hình như đã viết, nên mọi hạt giống đã lưu vẫn dựng lại đúng beat của nó.","changelog.97da7ec59349":"<strong>Trình soạn phong cách giờ chạm tới vốn từ roll, vị trí snare, hành vi 808 và các họ vòng hoà âm.</strong> ⚠ Mọi nhóm đều bắt đầu ở «Từ nền»: một giá trị đã viết sẽ <em>thay thế</em> giá trị của mô hình cha, nên một nút điều khiển không có trạng thái chưa đặt sẽ khiến chỉ việc mở hộp thoại cũng đủ ghi đè lên thứ mà phong cách dựa vào.","changelog.0c5372d37a10":"Thay đổi — danh mục lại nghe đúng như nghiên cứu của nó, 2026-08-15","changelog.58f17233fd10":"<strong>396 mô hình nghệ sĩ và nhà sản xuất được khôi phục về các giá trị mà mục nghiên cứu của chúng ghi</strong>, theo chỉ dẫn của chủ sở hữu: <em>«tôi không quan tâm chuyện chúng trùng nhau, chỉ cần bảo đảm nó không dùng tài liệu có bản quyền.»</em> Hai lượt sửa hàng loạt đã dịch chuyển chúng, cả hai đều để vượt qua các cửa kiểm độ khác biệt theo cặp. ⚠ Sáu mô hình giữ trạng thái về sau vì thay đổi đó sửa một điều về mặt âm nhạc và có nói rõ là gì.","changelog.0540e2c3eea0":"<strong>Hai cửa kiểm so từng cặp không còn thất bại vì trùng lặp.</strong> Hai nghệ sĩ trên cùng một làn, cùng bộ kit, cùng tempo <em>nên</em> thỉnh thoảng ra trùng một ô nhịp — đó là điều làm mỗi người nghe giống chính mình thay vì một người hàng xóm bị cố tình chỉnh lệch. Cả hai vẫn in ra mức trần của mình, và cả hai vẫn thất bại với một cặp giống hệt nhau ở <strong>mọi</strong> hạt giống.","changelog.f4e63eedd08b":"<strong>Giờ bộ sàng tính mới sàng cả bassline</strong>, đó là điều khiến việc này an toàn. ⛔ Trước đây nó loại mọi bassline dựa trên một lập luận chỉ đúng với một trên năm tiết tấu — <em>«bassline bị khoá theo kick»</em> — trong khi <strong>194 mô hình đi kèm viết <code>independent_riff</code></strong>. ⚠ Bảng vẫn chỉ chứa mã băm: một dấu vân tay là một đường nét, và không có đường nào đi ngược từ nó về một nốt.","changelog.415ba45149dd":"Sửa — những gì lượt duyệt tìm ra trong bốn ngày ở trên, 2026-08-16","changelog.9254a5cab370":"Sáu người duyệt trên một nhánh. Ba người tìm ra cùng một lỗi một cách độc lập.","changelog.2f8b7a34fe32":"<strong>Công tắc Đơn giản / Dày chỉ được truyền qua đúng một trong bốn cửa đọc nó.</strong> Cả ba chỗ đọc trong động cơ đều đúng; trang chỉ gửi nó qua một cửa. ⛔ Chế độ Bài hát phối theo cách đọc đã viết của mô hình trong khi mọi vòng lặp bên cạnh đều trả lời ở mức Dày đặc, và tung lại một đoạn thì nó trở về đơn sơ hơn các đoạn lân cận — tái hiện được, nên nghe như có chủ ý.","changelog.3447f687fc83":"<strong>Đánh dấu một âm giai trong trình soạn phong cách làm phong cách không lưu được, và chuyện đó có từ khi nút điều khiển này ra mắt.</strong> <code>session.scales</code> được ghi mà không kèm <code>weights</code>, trong khi <strong>599 trên 620 tệp mô hình viết cặp đó</strong>. Không ai trong sáu người duyệt tìm ra — bài kiểm thử viết cho lỗi roll đã bắt được nó ngay lần chạy đầu.","changelog.343ec0c7ac53":"<strong>Đánh dấu bất kỳ phân nhịp roll nào cũng làm phong cách không lưu được</strong> vì cùng lý do, chỉ ở khối bên cạnh. Nếu lọt qua được lint, phong cách đó sẽ <strong>hoàn toàn không viết roll hi-hat nào</strong>. ⚠ Bài e2e vẫn qua suốt và vẫn sẽ qua, vì bản giả lập không có linter.","changelog.be4f92504204":"<strong>Một phong cách được nhập vào có thể làm treo DAW</strong>: hai khoá điều khiển vòng lặp được đọc mà không bị kẹp giới hạn, trong khi việc tạo chạy đồng bộ trên chính luồng mà phần mềm chủ dùng để vẽ cửa sổ.","changelog.e73c794fa7f5":"Sửa — 2026-08-15","changelog.a20c61b94daf":"<strong>«Tạo tất cả» hiện thành một nút chính thứ hai đậm như nút Tạo ngay bên cạnh.</strong> Lớp CSS của nó đã được áp từ tháng 8 mà <strong>không được định nghĩa ở đâu trong <code>src/</code></strong>. Giờ nó chỉ được tạo kiểu bằng màu và một đường viền lõm vào trong: hàng đó nằm dưới trình chỉnh sửa, nên bất cứ thứ gì cao hơn sẽ lấy mất chiều cao của làn lực nhấn.","changelog.c1d850ee5c0a":"<strong>Một lần lấp đầy phía trên bị thất bại đã vứt bỏ lần tạo đã thành công</strong>, nên chỉ một lời từ chối đã vứt đi một melody đối vốn đã trả về đúng.","changelog.89075c088097":"<strong>Hai tâm trạng <code>live band</code> và <code>one drop</code> của Salaam Remi tạo ra cùng một melody</strong> ở mọi hạt giống, nên cặp đó chỉ để trang trí. Khác biệt được viết vào là đúng khác biệt mà one drop thực sự tạo ra: trọng tâm dời sang phách 3 và giai điệu ngả về sau.","changelog.b89dcb6ed30c":"<strong>Gõ «uk» lại ra Bassline thay vì UK Drill.</strong> Một tag trơn hai chữ cái được tính là khớp <em>chính xác</em>, thắng cả phần <em>tiền tố</em> trong tên UK Drill. Ba tag nữa đã bị gỡ trước khi chúng gây ra điều tương tự.","changelog.e34b5632786a":"Thêm — duyệt theo thời kỳ, và một lần tắt được giữ lại cùng dự án, 2026-08-15","changelog.ee5867f7128b":"<strong>Bốn nút thời kỳ phía trên danh mục: 90s · 2000s · 2010s · 2020s.</strong> Gõ phím có tác dụng khi bạn đã gọi được tên thứ mình cần; duyệt là việc bạn làm khi chưa gọi được. ⛔ <strong>Một bộ lọc, không phải sắp xếp</strong>: <code>boom-bap</code> là <em>thập niên 1990–nay</em>, nên nó thuộc cả bốn thập niên cùng lúc, và sắp xếp sẽ ép nó vào một thập niên rồi nói dối về ba cái kia. Chúng thu hẹp những gì bạn DUYỆT và không bao giờ thu hẹp những gì bạn TÌM được.","changelog.20cce385b4bc":"<strong>Một bộ tạo đã tắt vẫn tắt khi dự án được mở lại.</strong> Trạng thái đó trước đây nằm trong trạng thái giao diện, nên mở lại thì công tắc bassline được bật trở lại với clip vẫn lưu bên cạnh — và phiên phát một phần bass mà bản ghi đã nhập không hề chứa.","changelog.b9dd2c70835c":"<strong>Một tệp <code>.mid</code> thả lên một bộ tạo được chia ra các bộ tạo mà các giọng của nó thuộc về</strong>, trước đây thao tác thả đọc cả tệp vào đúng một thẻ bạn nhắm tới.","changelog.93349a364b1f":"<strong>Hộp thoại one-shot và con xúc xắc của bộ kit tranh nhau cùng một câu trả lời.</strong> Cả hai đều thăm dò một hộp thư tự xoá khi đọc, nên vòng lặp nào thăm dò trước sẽ lấy mất kết quả còn vòng kia báo thành công trên một lỗi mà nó không hề thấy.","changelog.aca47e54cbfd":"<strong>Xoá một bộ tạo từ thẻ Bài hát làm im lặng cả bản phối</strong>, trong khi dòng thời gian vẫn trên màn hình và nút Phát vẫn sáng.","changelog.2d60765bc992":"<strong><code>chroma</code> cấp phát 11.5 MB mỗi lần đọc chỉ để vứt đi</strong> — trên luồng trình chỉnh sửa trong DAW của ai đó. Kết quả vẫn y hệt, từng bit.","changelog.0eb460ecdc4a":"<strong><code>explorer_midi</code> là một lệnh cầu nối không có gì gọi tới</strong>, điều mà dự án này xếp vào loại lỗi. Đã gỡ bỏ cùng thao tác đọc một phần mà nó phục vụ.","changelog.e21415352325":"Thêm — một sample trở thành nốt, 2026-08-14","changelog.1cb3d917d3aa":"<strong>Kéo một tệp âm thanh lên một bộ tạo và nó được chia vào các bộ tạo mà các phần của nó thuộc về.</strong>","changelog.286f68904eb7":"<strong>Trống được phân loại qua hai lượt.</strong> Phổ tần đề xuất — kick dưới 150 Hz, snare dải rộng, hi-hat ở trên cùng — còn <em>ô nhịp</em> phân định những gì phổ không phân định được: bất cứ thứ gì ở phách hai và bốn là backbeat dù nó nghe như thế nào, và các cú đánh dải cao cách nhau kiểu chùm ba là một roll. ⛔ Lượt hai chỉ được gán lại những gì lượt một đã phát hiện, đó là ranh giới giữa một bộ phát hiện và một bộ tạo.","changelog.fd25cb74ee0a":"<strong>Bass không cần ký âm.</strong> Lọc thông thấp ở 250 Hz và những gì còn lại <em>chính là</em> bassline; tiếng kick tự loại mình ra vì nó không có chu kỳ ổn định.","changelog.b79f5af7a4a1":"<strong>Hợp âm trả về dưới dạng một vòng hoà âm, không phải một thế bấm</strong>, và bảng nói rõ như vậy. ⛔ Ký âm đa âm cho cả một bản mix là bài toán học máy, mà học máy bị cấm ở đây, và một tính năng tuyên bố trích xuất hoàn hảo nhưng lại đưa ra nốt gần đúng còn tệ hơn một tính năng nói rõ nó làm gì.","changelog.fe6b6349383f":"<strong>Một đường giai điệu được hát sẽ được để yên.</strong> Tách <em>âm thanh</em> giọng hát cần học máy; còn quyết định một <em>đường nốt</em> đã trích xuất có phải được hát hay không chỉ là số học. ⚠ Auto-Tune mạnh đánh bại ba trong bốn phép đo cùng lúc; vibrato thì còn trụ được.","changelog.bf43f015b953":"Sửa — một tệp dự án có thể kéo sập DAW theo, 2026-08-14","changelog.d7f36c2594cb":"⛔ <strong>Một nhịp mang theo trong dự án được chia sẻ có thể làm phần mềm chủ dừng đột ngột.</strong> Nhịp đến từ trang và từ các giá trị ghim đã lưu, mà không nguồn nào được kiểm tra phạm vi: 25/1 khiến một phần chín mươi sáu ô nhịp dài hơn một nốt đen, và phép kẹp giới hạn độ dài nốt trống sẽ <strong>panic</strong> khi mức sàn vượt quá mức trần. <code>panic = &quot;abort&quot;</code> chỉ có ở bản phát hành, nên trong một bản dựng đã phát hành, điều đó nghĩa là cả DAW cùng mọi dự án chưa lưu trong đó. Nhịp được thu hẹp ở chỗ nó đi vào <em>và</em> được giới hạn ở chỗ nó được dùng, vì chỉ một trong hai sẽ để ngỏ cửa còn lại. ⚠ Được phát hiện bằng cách đọc mã, không phải bằng một bài kiểm thử thất bại — bộ kiểm thử vẫn xanh.","changelog.b0f4be8222cd":"<strong>Phần nghe thử của trình duyệt có thể giải mã cả một tệp không phải âm thanh</strong>: nó kiểm tra rằng đường dẫn là cục bộ, nằm trong thư viện và là một tệp, nhưng chưa bao giờ kiểm tra phần mở rộng.","changelog.505a5ca6f9a1":"Sửa — chip tempo theo kịp tâm trạng, 2026-08-14","changelog.cf21ff1cb729":"Ghim một tâm trạng giờ cập nhật các chip ngay lập tức thay vì đợi tới lần đổi nghệ sĩ kế tiếp — trap là 140 còn chế độ <code>dark</code> của nó là 136, nên chỉ số hiển thị một tempo mà động cơ sẽ không bao giờ dùng. ⛔ Giá trị ghim gốc có cùng lỗ hổng theo cách trông như đã sửa: nó có đọc lại các chip, nhưng <em>trước khi</em> giá trị ghim tới được plugin, nên nó điền vào chính giá trị mà bạn vừa bỏ đi.","changelog.d9b7864d6aea":"Thêm — một nghệ sĩ tạo được trong mọi thể loại mà họ làm, 2026-08-14","changelog.a3d424256825":"<strong>«Drake, nhưng là R&amp;B».</strong> Danh mục vẫn luôn liệt kê một nghệ sĩ dưới mọi thể loại họ làm — <strong>529 trên 534</strong> mô hình nghệ sĩ và nhà sản xuất nêu một thể loại mà họ không kế thừa — vậy mà Tạo luôn chỉ trả lời theo thể loại họ kế thừa. Một chip <strong>Tạo trong</strong> cho chọn thể loại nào: các khối riêng của nghệ sĩ đặt trên nền móng của một thể loại khác, nên 2Pac dưới boom-bap là <em>2Pac trên nền boom-bap</em> chứ không phải chỉ một trong hai.","changelog.0a39f9a2654c":"⚠ Được lưu cùng dự án, giống như tâm trạng — mở lại ở thể loại riêng của nghệ sĩ sẽ lặng lẽ tạo ra một bản nhạc khác từ cùng một hạt giống. ⛔ Không phải pha trộn hai thể loại: hợp nhất hai nền chỉ ra một mớ hỗn độn chứ không phải hai chế độ.","changelog.5484dab868bd":"Thêm — âm thanh có trình chỉnh sửa riêng, 2026-08-14","changelog.94523aee9a25":"<strong>Giờ mỗi pad đều có trình chỉnh sửa, không chỉ mỗi nốt.</strong> Trước đây <strong>nốt</strong> có trình chỉnh sửa còn <strong>âm thanh</strong> thì không. Giờ một pad có <strong>ADSR</strong> dạng đồ hoạ (sustain tính bằng dB, đọc theo bản tham chiếu), <strong>âm lượng</strong>, <strong>pan</strong>, <strong>dịch giọng</strong>, <strong>chỉnh tinh</strong>, công tắc <strong>chuẩn hoá</strong>, <strong>cắt đầu/cuối</strong> trên dạng sóng và <strong>fade vào/ra</strong> — tất cả theo từng pad, được lưu lại, và nghe thử lại ngay khi vặn. ⛔ Nó tác động cả tới các giọng đi kèm, không chỉ các sample bạn đã thay. ⚠ Một pad chưa ai chỉnh vẫn y nguyên từng bit: một đường bao đồng nhất hoàn toàn không được lưu, nên luồng âm thanh bỏ qua phép tính.","changelog.cce1ec869482":"<strong>Hai nút điều khiển mà bản tham chiếu có được cố ý bỏ ra</strong>, và bảng không nói gì thay vì vẽ ra một thứ không thể hoạt động.","changelog.4b17bad89480":"<strong>Trình duyệt có thể phát một tệp ở mức âm lượng riêng của nó, hoặc đúng y nguyên.</strong> Phần nghe thử nằm dưới mức toàn thang để một one-shot phát trên một mẫu đang chạy không bị clip — hợp lý, nhưng thành nói dối ngay khi điều bạn đang làm là đánh giá một sample to cỡ nào.","changelog.398db3f04b48":"<strong>Đặt một sample lên pad sẽ mở trình chỉnh sửa của pad đó</strong>, từ cả ba lối.","changelog.6765e374d806":"<strong>Tệp nhị phân kiểm thử chạy lâu nhất trong dự án giờ chỉ mất 1.70 giây thay vì 1300.91.</strong> Nó đọc lại 609 tệp JSON và phân giải lại toàn bộ 590 mô hình <strong>ở mỗi lần gọi</strong>, mỗi lần tạo một lần, qua bảy bài kiểm thử. Cùng hàm trợ giúp đó có mặt trong mười lăm tệp nhị phân của động cơ.","changelog.79803c0d1988":"<strong>Một chỉnh sửa pad không còn có thể khiến bạn mất cả dự án.</strong> Năm trường mới theo từng pad có chặn dưới ở không nhưng không bao giờ có mức trần, nên một giá trị không hữu hạn lọt vào phiên đã lưu — nơi nó được ghi thành <code>null</code>, lưu trơn tru, rồi nạp thất bại, kéo theo hạt giống, các clip đã sửa, bản phối, các thư mục sample và các one-shot về mặc định.","changelog.82d7ba79435d":"<strong>Một dự án mở lại giờ phát đúng các chỉnh sửa pad mà nó hiển thị.</strong> Định hình một giọng <em>tích hợp</em> khôi phục các núm vặn đúng nhưng không bao giờ báo cho động cơ âm thanh, nên stem xuất ra mang đường bao còn phần nghe thử thì không.","changelog.1a72d30e7569":"<strong>Một bài hát được tạo khi đã ghim thể loại giờ dùng đúng thể loại đó</strong>: trước đây giá trị ghim chỉ tới được một đoạn được tung lại chứ không tới chính bài hát.","changelog.3b327e41cadd":"<strong>Cắt gọn một sample không còn gây tiếng lách cách</strong>, và giờ Release định hình phần đuôi của một làn trống thay vì không làm gì ở đó.","changelog.79fab545a936":"<strong>Một đường bao thiếu trường không còn làm mất cả khối</strong>, lỗi từng khiến một dự án do bản dựng cũ hơn ghi bị từ chối với <code>missing field attackMs</code>.","changelog.308a6a7f8aa6":"Thêm — trình duyệt ở quy mô thư viện, và một lịch sử sống lâu hơn phiên, 2026-08-13","changelog.99f4a587028c":"<strong>Cây sample chỉ vẽ một khung nhìn, không vẽ cả thư mục.</strong> 2.000 hàng mỗi thư mục, nhiều thư mục mở cùng lúc, mỗi hàng sáu phần tử, bên trong các danh sách lồng nhau do một thành phần tự gọi chính nó tạo ra. Giờ nó là một chuỗi phẳng duy nhất và chỉ những hàng trên màn hình mới tồn tại — một thư mục 2.000 tệp mở trong chưa tới 300 ms.","changelog.118279c360c1":"<strong>Gõ để lọc cây thư mục.</strong> ⚠ Nó nói rõ đã tìm ở đâu: plugin đọc một thư mục mỗi lần gọi, nên bộ lọc chỉ tới được các thư mục bạn đã mở, không xa hơn.","changelog.c74f7d9b9f46":"<strong>Một thư mục thư viện không còn ở đó sẽ báo như vậy</strong>, trước đây gốc của một ổ đĩa đã rút ra được vẽ như một thư mục bình thường nhưng không chịu mở.","changelog.62d394953cc6":"<strong>Mọi lần tạo bạn đã làm, duyệt được và được lưu lại.</strong> ◀/▶ trả lời câu «lùi một bản» nhưng vô dụng với câu «tìm bản đó trong tám mươi bản». Giới hạn <strong>theo từng phong cách</strong>, vì một giới hạn chung sẽ để một buổi tối với một nghệ sĩ đẩy văng những bản thu mà bạn quay lại để tìm.","changelog.d004a114800f":"<strong>Nghe một tệp <code>.mid</code> ngay từ trình duyệt</strong>, qua một nhạc cụ <strong>trung tính</strong> để nó nghe như nhau dù đang chọn nghệ sĩ nào.","changelog.be3f0d023b9a":"<strong>Tìm kiếm trong danh mục giờ tốn chưa tới một nửa so với trước.</strong> Ô tìm kiếm chấm điểm 590 mục ở mỗi lần gõ phím và từng chuẩn hoá lại truy vấn một lần cho mỗi mục, chuẩn hoá lại cả chín trường tìm kiếm được, và tách mỗi trường thành từ hai lần. Trước là 5.5 ms mỗi lần gõ, sau còn 2.9 ms, thứ hạng không đổi.","changelog.547ba1349053":"<strong>Bản độc lập ghi nhật ký ra tệp trong bản phát hành.</strong> Trình báo sập bắt được <em>lỗi phần cứng</em>; còn một <strong>panic</strong> thì đi vào stderr mà bản dựng <code>windows_subsystem = &quot;windows&quot;</code> không có — nên chính lỗi có khả năng cao nhất nằm sau vụ sập chưa tái hiện được lại là lỗi không để lại bằng chứng nào.","changelog.1dfc33ad2e89":"<strong>Mở một tệp <code>.mid</code> sẽ ghi nó vào lịch sử của trình duyệt.</strong> Trước đây nó được ghi khi nghe thử sample và khi <em>thả</em> vào một phần, nhưng không phải từ cú nhấp mở nó — nên ai đã nhấp hai mươi vòng lặp và nhập một cái chỉ thấy lịch sử có đúng một cái đó.","changelog.b2294b88f311":"<strong>Bản giả lập IPC rút một hạt giống mới cho mỗi lần Tạo không ghim</strong>, như động cơ vẫn làm. Trước đây lần nào nó cũng trả về đúng giá trị <code>424242</code>, điều mà không bài kiểm thử nào nhận ra cho tới khi một lịch sử dùng khoá <code>(part, seed)</code> biến ba lần nhấn thành một bản thu.","changelog.931244f782e4":"Thêm — mỗi làn trống mở rộng thành một làn cao độ, 2026-08-13","changelog.07f98c226e98":"<strong>Bất kỳ làn nào cũng mở ra được thành các hàng cao độ</strong> — nốt gốc của làn, ba nửa cung lên và ba nửa cung xuống — để cao độ của một cú đánh là thứ bạn thấy và kéo được chứ không phải một giá trị lưới đã vứt đi. 808 là cái đòi tính năng này; cơ chế thì giống nhau cho cả 33 làn, nên không làn nào được miễn.","changelog.04591dfc7ca3":"<strong>Hành trình không giới hạn trong khi hàng vẫn cao bảy ô.</strong> Kéo quá mép trên sẽ dịch khung nhìn của làn đó thay vì dừng lại, và mỗi làn giữ độ lệch riêng.","changelog.ab9329495924":"<strong><code>sub</code> và <code>subLow</code> ghi nhãn các hàng của chúng bằng tên nốt; mọi làn khác bằng nửa cung</strong>, vì ở đó độ lệch là phép dịch giọng sample, và gọi một tiếng shaker là «D#2» sẽ là một chỉ số nói dối.","changelog.a600b5a40e8c":"<strong>Các cú đánh nằm ngoài khung nhìn được đánh dấu, không bị ẩn</strong>, nên một 808 đang trượt không bao giờ có thể nghe thấy mà lại không nhìn thấy.","changelog.7a1adb84f977":"<strong>Một lần kéo cao độ là một bước hoàn tác</strong>: khung nhìn đi theo ngón tay nhưng nốt chỉ được đặt khi nhả ra, nếu không một lần kéo sẽ tốn một Ctrl+Z cho mỗi nửa cung.","changelog.768b595223be":"<strong>Kéo trên dạng sóng nghe thử để tua</strong>, đó là cách bạn săn một transient mà không phải nhấp hai mươi lần.","changelog.055c12f8042f":"<strong>Một phần giữ nốt không còn sụp lại trên một vamp.</strong> Cả hai kiểu ngân dài đều viết một nốt cho mỗi hợp âm, nên một mô hình có hoà âm nằm yên trên một hợp âm chỉ nhận một nốt cho cả clip — hai mô hình đạt 959 và 963 melody đối khác nhau trên 1.000 so với ngưỡng 0.98, và <code>mobb-deep</code> đo được <strong>8 bassline khác nhau trong 1.000 hạt giống</strong>. Giờ một quãng giữ dài hơn hai ô nhịp sẽ được đánh lại theo một câu nhạc rút riêng cho từng quãng.","changelog.fc0cebf8ea13":"<strong>Bassline của KRS-One lại là của riêng anh ấy.</strong> Nó và Wu-Tang Clan đã bị dời sang cùng một tiết tấu và viết ra cùng một bassline ở 42 trên 200 hạt giống: <code>mirror_kick</code> lấy điểm khởi âm từ kick và 62 mô hình boom-bap dùng chung nó, nên một mô hình không có chính kiến riêng sẽ viết theo bất kỳ người hàng xóm nào chung kick với nó. Giờ bassline của KRS-One nói đúng điều nghiên cứu vẫn luôn nói — reggae: cú trượt dub, nốt bảy giáng, và một tiếng bass chơi trước phách một.","changelog.5ce722b37761":"<strong><code>country-train</code> viết 73 beat khác nhau qua 200 hạt giống, tăng từ 24</strong>, và <code>rapsody</code> từ 136 lên 199.","changelog.b395a0b52253":"Thêm — lưới trống trở thành trình chỉnh sửa, 2026-08-11","changelog.f102e9a48f1f":"<strong>Kéo một khung để chọn.</strong> Shift-kéo chọn mọi ô bên trong hình chữ nhật, không chỉ những ô mà con trỏ đi qua.","changelog.73e932010c9a":"<strong>Sao chép, dán, nhân bản và xoá một vùng chọn.</strong> Một chùm ba đã sao chép khi dán vẫn là chùm ba: bộ nhớ tạm giữ thời điểm thật của nốt thay vì bắt vào lưới.","changelog.91eb18c0cd6e":"<strong>Nhấp chuột phải và kéo để xoá</strong>, hoàn tác bằng một lần <code>Ctrl+Z</code>. Một cú nhấp chuột phải không di chuyển vẫn mở bảng công cụ của roll.","changelog.879ec004b17a":"<strong>Tên làn lại đọc được</strong> — trước đó chúng chỉ hiện thành một chữ cái. Ổ khoá đã khoá luôn hiện ra dù con trỏ đang làm gì, vì một cái khoá bạn không thấy là cái khoá bạn quên mất mình đã đặt.","changelog.f9921d6b3fab":"Thêm — bảng phím tắt, 2026-08-11","changelog.d9b9605194c9":"<strong>Giờ nó có một nút</strong>, cạnh Cài đặt và Giới thiệu. Trước đây chỉ mở được bằng cách nhấn <code>?</code> hoặc <code>F1</code> — một bảng mà toàn bộ việc của nó là cho bạn biết các phím làm gì, lại chỉ tìm được nếu bạn đã biết sẵn một phím. Nó cũng vừa trong một màn hình, và các thao tác riêng của lưới trống lần đầu được ghi lại, bằng cả mười tám ngôn ngữ.","changelog.62dcea291c83":"Sửa — 2026-08-11","changelog.ec59fc38e138":"<strong>Mọi nốt đều hiện ra khi một clip được tạo, cả theo chiều dọc lẫn chiều ngang.</strong> Giờ roll đặt kích thước hàng theo âm vực của chính clip và căn giữa nó, thay vì ghim nó lên trên cùng với khoảng trống thừa ở dưới.","changelog.1cb0980e60e7":"<strong>Ngoặc vùng lặp có thể đổi kích thước từ hai mép.</strong> Thao tác nắm từng lấy tay nắm <em>đầu tiên</em> trong tầm thay vì tay nắm gần nhất, nên mép phải của một vùng lặp ngắn hoàn toàn không nắm được — và cả thước hiện con trỏ đổi kích thước, khiến chính dải duy nhất đổi được kích thước lại trở nên vô hình.","changelog.78dcc84c55af":"<strong>Mười danh sách thả xuống gốc cuối cùng đã bị bỏ</strong>, vốn được hệ điều hành vẽ theo cửa sổ thay vì theo ô nhập.","changelog.3aae90a5883e":"<strong>Mười lỗi tìm ra khi duyệt các phần trên</strong>, mỗi lỗi đều được sửa kèm một bài kiểm thử được theo dõi thất bại trước. Bốn lỗi nằm ở thao tác dán của lưới, tất cả đều do đo nó bằng tick trong khi lưới nghĩ theo cột: một cú đánh được nhân hoá cho sớm biến mất khi dán vào ô đầu tiên, một hình tiết tấu thưa dán lên một vùng dày vẫn giữ các cú đánh thừa của vùng dày, và một lần dán có thể mang trở lại một làn mà bạn đã gán đi chỗ khác.","changelog.ba30e336f27a":"Thêm — 32 thể loại mới, 2026-08-10","changelog.eee977220c4e":"<strong>Danh sách thể loại tăng từ 20 lên 52</strong> — dark plugg, Detroit bounce, Jersey club, ATL swag rap, UK underground, EDM rage, digicore, jump-up DnB, neurofunk, jungle, pop DnB, UK garage, house, dance pop, pop 2020s, country pop, country shuffle, neo-soul, funk, future bass, afrobeats, amapiano, dancehall, reggaeton, baile funk, afroswing, Memphis rap, G-funk, lo-fi hip hop, sexy drill, hyphy và crunk.","changelog.42f059fbabae":"Mỗi thể loại tự viết trống, hợp âm, melody, melody đối và bassline của riêng mình — không thể loại nào kế thừa trọn một phần — và mỗi thể loại đến cùng ba tâm trạng, nên chọn một thể loại cho ra ba bản nhạc khác nhau chứ không phải một. Thể loại nào cũng được đo đối chiếu với phần còn lại của danh mục.","changelog.10d9e1d4972b":"Sửa — một nốt có thể ngân quá điểm cuối của mẫu, 2026-08-10","changelog.bbb3fb833dc4":"Một snare ghost bị đẩy trễ, hay một tiếng tambourine ở phân nhịp cuối cùng, có thể mang độ dài của nó vượt ra ngoài mẫu — nên clip bạn kéo ra chứa một nốt mà ô nhịp không có chỗ. Bốn bộ tạo kia vẫn luôn cắt gọn; bộ kit thì chưa bao giờ.","changelog.e9fa1c28ce6f":"Sửa — bassline có thể đi lạc khỏi tông, 2026-08-10","changelog.37090d443d59":"<strong>Một nốt bass chromatic giờ có chỗ để đáp.</strong> Nốt lướt được viết như một quãng tính từ <em>hợp âm</em>, và trên một hợp âm bình thường quãng đó có thể ra khỏi tông — nên bass chơi một nốt chẳng từ đâu tới và chẳng dẫn tới đâu. Giờ nó tiến về nốt đứng sau nó, như cách một tay bass đi vào một lần đổi hợp âm. Các nốt bảy giáng và blue note đi bằng bước được giữ lại: đó là thành ngữ âm nhạc, không phải lỗi.","changelog.2d6b36e508b4":"<strong>Bass không còn chơi cao hơn các hợp âm mà nó đang đỡ</strong>, và bốn mô hình có bass nhân đôi y từng nốt 808 của chính chúng giờ chơi một bè thứ hai thật sự.","changelog.d0b5a7643bda":"Sửa — plugin có thể phát hành kèm một danh sách thể loại đã cũ, 2026-08-10","changelog.9411b413d18e":"Bộ dữ liệu được biên dịch vào tệp nhị phân mà không có gì bảo hệ thống dựng theo dõi nó, nên một plugin dựng sau khi một mô hình thay đổi vẫn có thể tiếp tục cung cấp danh mục mà nó đã được biên dịch cùng, mà không có chỗ nào báo điều đó.","changelog.77caf45cd87d":"Sửa — File Explorer không mở được thư mục con, và nó còn làm hỏng bốn thứ khác, 2026-08-10","changelog.b5ed0979ba9d":"<strong>Bạn lại duyệt được vào các thư mục con, ở mọi độ sâu.</strong> Mở một thư mục thư viện thì được; mở bất cứ thứ gì <em>bên trong</em> nó thì bị từ chối, vì <code>canonicalize</code> của Windows trả về đường dẫn bắt đầu bằng <code>\\\\?\\</code> và bước kiểm tra từ chối đường dẫn mạng coi phần <code>\\\\</code> ở đầu ấy là một đường dẫn mạng. <strong>Cùng lần từ chối đó cũng đang âm thầm làm hỏng trình phát nghe thử, dạng sóng, việc đọc <code>.mid</code> và việc thả sample lên pad trống</strong> — tất cả đều đi qua cùng lớp chắn. Đường dẫn UNC thật vẫn bị từ chối.","changelog.ade18cd195aa":"<strong>Trình duyệt có thể dùng cả thanh bên</strong>, trước đây nó bị giới hạn ở khoảng nửa chiều cao dù thư mục của bạn sâu đến đâu.","changelog.1b52bf9f1edf":"Bảo mật — một đường dẫn do trang cung cấp có thể khiến plugin xác thực với một người lạ, 2026-08-10","changelog.b99ed6cfdb4b":"**Gắn sao cho một tệp đã kiểm tra thư viện <em>trước khi</em> kiểm tra đường dẫn mạng**, mà bước kiểm tra thư viện chính là bước chạm tới ổ đĩa. Trên Windows đó không phải một lần đọc — đó là một phiên SMB đi ra ngoài, trao đi thông tin đăng nhập Windows của bạn. Chỉ một tin nhắn từ chính web view của plugin là đủ. Giờ lớp chắn nằm ngay trong bước kiểm tra phạm vi, nên không lệnh nào trong tương lai có thể đưa lỗi đó trở lại.","changelog.c11b4781c6b1":"<strong>Một tệp dự án được chia sẻ có thể trỏ thư viện sample vào toàn bộ ổ đĩa của bạn.</strong> Các thư mục thư viện đi theo bên trong tệp dự án và chỉ đường dẫn <em>mạng</em> mới bị từ chối, nên một dự án có thể mang theo <code>C:\\Users</code> và lặng lẽ cấp quyền cho mọi thứ đọc tệp trong thư viện của bạn.","changelog.436b592f6cec":"<strong>Một tệp MIDI sai định dạng có thể làm sập DAW của bạn.</strong> Một tệp khai báo một nhịp cực đoan với một tick mỗi phách đã đẩy bộ đọc bản phối vượt quá điểm cuối không gian tick của chính nó; trong bản dựng phát hành, điều đó kéo sập phần mềm chủ cùng với phiên chưa lưu của bạn.","changelog.4c1f2cf3c0a6":"Sửa — ba cách mà thành quả của bạn có thể bị mất, 2026-08-10","changelog.4c212624c7d8":"<strong>Một dự án có hơn tám thư mục sample bị mất những thư mục dư ra.</strong> Giới hạn cho những gì bạn có thể <em>thêm</em> cũng bị áp khi <em>nạp</em>, và danh sách đã cắt bớt được ghi thẳng đè lên dự án của bạn. Giới hạn những gì bạn được thêm không phải là giấy phép để xoá những gì bạn đã có.","changelog.880491ce97f6":"<strong>Một bài hát được nhập vào chưa bao giờ được lưu.</strong> Kéo một tệp MIDI lên thẻ Bài hát lấp đầy dòng thời gian nhưng không có gì yêu cầu dự án lưu nó lại.","changelog.8e4f72c4b2d3":"<strong>Hoàn tác đã xoá một bài hát được nhập vào.</strong> Một bài nhập vào không thuộc về nghệ sĩ nào, và lớp chắn ngăn bản phối của nghệ sĩ này rò sang nghệ sĩ khác đã hiểu đó là sự không khớp: chỉ một lần gõ phím sau khi nhập, Ctrl+Z xoá sạch nó và Ctrl+Y không mang lại được.","changelog.cdb3914ece4a":"Thêm — một cây thư mục thật, thẻ thư mục, mục yêu thích gắn sao, và MIDI biết mình là gì, 2026-08-10","changelog.8f46d9bab3fb":"<strong>Trình duyệt là một cây thư mục đúng nghĩa</strong>, nhớ những gì bạn để mở khi chuyển giữa các thư mục, với tối đa tám thư mục thư viện dưới dạng thẻ.","changelog.d384c27e9841":"<strong>Thư viện của bạn còn nguyên sau khi đóng ứng dụng.</strong> Trước đây nó chỉ được lưu bên trong <em>dự án</em>, nên nó trở lại cùng một tệp <code>.als</code> nhưng không bao giờ với bản độc lập.","changelog.0985960cb1d0":"<strong>Mục yêu thích gắn sao.</strong> Nhấp vào một mục và cây thư mục mở mọi thư mục nằm giữa gốc và tệp đó — hoặc, nếu thư mục của nó không còn là một trong tám thẻ của bạn, thì mở vị trí của tệp trong Explorer hoặc Finder.","changelog.6fdc895ea960":"<strong>Bàn phím đi qua cây thư mục.</strong> <code>↑</code>/<code>↓</code> di chuyển giữa các hàng, <code>→</code> mở một thư mục và <code>←</code> đóng nó — còn trên một <em>tệp</em>, cũng những phím đó phát nó xuôi và ngược. Thư mục không có gì để nghe thử còn sample không có gì để mở rộng, nên ý bạn muốn không bao giờ mơ hồ.","changelog.60837102da5c":"<strong>Tệp <code>.mid</code> được hiển thị</strong> và được tách bạch rõ ràng với âm thanh: pad từ chối một tệp như vậy trước khi bạn thả tay thay vì báo lỗi sau đó.","changelog.b1043457ecb3":"Thêm — thả một tệp MIDI vào và nó tự tìm ra trong đó có gì, 2026-08-10","changelog.fd88ab1f798a":"Kéo một tệp <code>.mid</code> lên một bộ tạo và các nốt của nó rơi vào đó, hoặc thả nó lên thẻ Bài hát và lấy những phần bạn muốn — cả tệp đến dưới dạng một bản phối và không có gì ghi đè lên những gì bạn đang có cho tới khi bạn chọn. Một tệp nhiều lớp được tách thành Bass, Melody, Melody đối, Hợp âm và Trống, và <strong>mỗi phần đều nói vì sao nó được chuyển tới đó</strong> — «trên kênh trống GM», «giọng thấp nhất», «từ tên tệp» — nên một phán đoán sai chỉ cần một lần nhấp để chuyển hướng.","changelog.e560b4cd27a4":"<strong>Nó được dạy bằng tệp thật, không phải bằng giả định.</strong> Bốn tệp xuất từ sample pack đã làm hỏng phiên bản đầu ba lần trên ba: các gói đặt trống ở <strong>kênh 0</strong>, không phải kênh trống GM, nên trống được nhận ra qua hình dạng — một nhúm cao độ, đánh nhiều lần, ngắn. Các nốt giai điệu được giữ thì chồng lên nhau liên tục, nên hợp âm là những nốt được đánh <em>cùng lúc</em> chứ không chỉ chồng lên nhau. Và <strong>nốt MIDI của một 808 cho biết phím nào kích sample, không phải nó vang trầm tới đâu</strong>, nên một bassline thường xuyên nằm ở âm vực melody — đó là lý do chính tên của tệp được tin hơn mọi phép đo.","changelog.08e81ba37df8":"Thêm — pad trống trên sân khấu, một ô để tìm bất kỳ nghệ sĩ nào, và một cửa sổ cuối cùng đã chịu nghe lời, 2026-08-09","changelog.5a8e71fc3e5d":"<strong>Tám pad trống nằm ngang phía trên sân khấu</strong>, mỗi pad mang mọi thứ ngay trên mặt: tên làn, thứ đang nằm trên nó, một chấm xanh hoặc đỏ cho biết bạn có nghe được nó không, nút Phát để nghe thử riêng nó, nút xáo trộn để tung lại, và một nút ✕ để trả lại âm thanh tích hợp. Hai pad có thể dùng chung một làn để chồng lớp snare, và bố cục được nhớ <strong>theo từng nghệ sĩ</strong>.","changelog.7a967cc608c0":"<strong>Một ô chọn duy nhất thay cho một ô tìm kiếm, một hàng chip và một danh sách năm trăm hàng.</strong> Gõ để lọc qua nghệ sĩ, thể loại, tên gọi khác và lỗi chính tả. Dừng giữa chừng rồi nhấp ra ngoài thì nó lấy kết quả khớp nhất, nên bạn không thể rơi vào tình trạng chưa chọn gì. «Quy trình riêng» được ghim ở trên cùng dù đang chọn gì.","changelog.cca505068909":"<strong>Các công tắc tắt tiếng bộ tạo đã chuyển lên các thẻ</strong>, vì chúng là một hàng thứ hai mang đúng sáu chữ ấy — nên muốn biết công tắc nào tắt Trống thì phải đọc chữ «Trống» hai lần.","changelog.635de9290198":"<strong>Cả clip hiện ra trọn vẹn khi được tạo</strong>, dù dài bao nhiêu.","changelog.34647eb32c75":"Sửa — 2026-08-09","changelog.cb746382c26e":"⛔ <strong>Plugin chạy ở chế độ không nhận biết DPI trong khi WebView2 thì có.</strong> Trên màn hình 150%, Windows kéo giãn cửa sổ thêm một nửa trong khi trang kết xuất theo điểm ảnh thật, nên giao diện chỉ phủ hai phần ba cửa sổ và nội dung không đi theo khi kéo. Một chỗ lệch, cả hai triệu chứng.","changelog.1c0e1181baae":"<strong>Cửa sổ có thể được kéo, đổi kích thước và phóng to</strong>, và sẽ không thu nhỏ dưới kích thước mà ứng dụng được thiết kế.","changelog.395cd7a6da0c":"<strong>Các sample đã sao chép của một phong cách giờ được nạp lại.</strong> Bước xin đồng ý và việc sao chép đều chạy; chỉ là không có gì từng đọc chúng, nên lời hứa của ô đánh dấu là sai trong suốt thời gian bản dựng phát hành nó.","changelog.cab98edaf117":"<strong>«Một tiếng» không còn xoá nốt mà nó gọi tên</strong> — nó thu một roll trở lại thành một tiếng đánh đơn.","changelog.535170bf7968":"<strong>Nhấp đúp vào bản độc lập là chạy được.</strong> Nó tự cung cấp kích thước chu kỳ âm thanh thay vì phụ thuộc vào một cờ dòng lệnh.","changelog.06c7109c2a8c":"Thêm — mọi nghệ sĩ đều có tâm trạng, bạn có thể dựng và huấn luyện phong cách của riêng mình, và không có gì sao chép sample của bạn mà không hỏi, 2026-08-09","changelog.a4377a96815d":"<strong>Giờ mọi nghệ sĩ và thể loại đều có tâm trạng.</strong> Mười hai thể loại trước đây không có, và giờ mỗi thể loại đưa ra ba — <em>dusty / jazzy / hard</em> của boom bap, <em>shuffle / ballad / barnburner</em> của country. Nhấn Tạo sẽ đi khắp dải của một nghệ sĩ thay vì trả về một âm thanh chỉ khác hạt giống: <strong>96 cặp (nghệ sĩ, tâm trạng)</strong>, tăng từ 33.","changelog.89a78f654f4d":"<strong>Quy trình riêng — dựng một phong cách của riêng bạn.</strong> Đặt tên, lấy bất kỳ nghệ sĩ hay thể loại nào làm nền, đặt dải tempo, swing, mật độ và các âm giai, rồi lưu. Nó tạo, khoá, tung lại và xuất y như một phong cách đi kèm, vì nó <em>chính là</em> một phong cách như thế — kế thừa mọi thứ bạn không thay đổi, kể cả những cải tiến mà nền nhận được về sau.","changelog.ce63a23ea1c7":"<strong>Huấn luyện một quy trình từ những bản thu bạn giữ lại.</strong> Khi đủ ba mươi bản, Huấn luyện khớp một phong cách vào những gì bạn đã giữ và sẽ không lưu một phong cách tự lặp lại chính nó. <strong>Trong đó không có học máy</strong>: nó đo các bản thu của bạn rồi ghi các con số trở lại, và ứng dụng vẫn hoàn toàn ngoại tuyến.","changelog.5f1d99513891":"<strong>Các chip thể loại tự nói rằng chúng không nhấp được.</strong> Hàng Thể loại hiện con trỏ «cấm vào» trên những nút điều khiển hoạt động hoàn hảo, và đã như vậy từ khi bố cục được vẽ lần đầu.","changelog.f5f2401fda2d":"<strong>Huấn luyện có thể đã làm treo DAW của bạn.</strong> Bước kiểm tra rằng một phong cách đã huấn luyện không tự lặp lại chạy hàng nghìn lần tạo trên chính luồng mà phần mềm chủ dùng để vẽ cửa sổ.","changelog.7de627bf6f0a":"Thêm — melody thôi trích dẫn người khác, mỗi thể loại có giọng riêng, và hi-hat biết lên tiếng, 2026-08-08","changelog.c0ae9370557e":"<strong>⛔ Một bộ sàng tính mới</strong>, để melody được tạo ra không phải một hook mà ai đó đã sở hữu. Mọi melody và melody đối đều được sàng đối chiếu với một bảng đóng gói sẵn các đường nét nổi tiếng trước khi bạn nghe. <strong>Không thứ gì trong bảng là một melody</strong>: nó chứa các dấu vân tay một chiều của <em>đường nét</em>, và không có đường nào đi ngược từ đó về một nốt. Dịch giọng một hook không giấu được nó.","changelog.30b1c2284c32":"<strong>Giờ mọi thể loại đều có melody, melody đối và hợp âm riêng</strong>, thay vì năm thể loại phải dựa vào một mặc định dùng chung. Sáu thể loại không có 808 đã có bassline thật.","changelog.030f3251348a":"<strong>⛔ Fill hi-hat.</strong> Hi-hat là nơi trap, drill và plugg lên tiếng: một hình tiết tấu cuối câu phá vỡ dòng chảy — một roll, một cú lắp, một chùm ba dồn dập, một đoạn tăng dần, hoặc một <strong>khoảng lặng</strong>, khi hi-hat dừng phắt lại.","changelog.d453628fda56":"<strong>⛔ Khoá một tiếng trống để lần tung lại không thể động tới nó</strong>, và <strong>solo trên mọi làn trống</strong>. Một làn bạn đã tắt tiếng vẫn tắt tiếng khi có solo.","changelog.28b35f4817da":"<strong>⛔ Một thư viện mẫu sống lâu hơn dự án</strong> — lưu dưới dạng nốt, không kèm bộ kit. Mỗi mẫu là một tệp riêng, nên một lần lưu hỏng chỉ mất một vòng lặp chứ không mất cả kệ.","changelog.f3ac9ded3a5f":"<strong>⛔ Mọi bản thu bạn đã làm trong phiên này</strong>, mang trở lại toàn bộ thiết lập: nghệ sĩ, tâm trạng, hạt giống, số ô nhịp và các giá trị ghim.","changelog.1e86a4e5892e":"Bốn ảnh chụp chuẩn đã thay đổi, mỗi bản diff đều được đọc trước khi tạo lại: trap và UK drill giờ viết một fill hi-hat; <code>ny-drill</code>, <code>liquid-dnb</code>, <code>country-train</code> và <code>boom-bap</code> chơi bassline của riêng mình thay vì kế thừa; và một hi-hat đóng nằm đè lên một hi-hat mở đã bị bỏ, điều này làm đổi lực nhấn của mọi hi-hat sau đó vì <code>humanize</code> đi qua một làn theo thứ tự nốt.","changelog.bff5ca6b89e9":"Sửa — những gì lượt duyệt tìm ra, 2026-08-09","changelog.5267b9a16e83":"Mười lăm phát hiện đứng vững qua kiểm chứng độc lập. Nghiêm trọng nhất trước:","changelog.0c5c4cec0863":"<strong>⛔⛔ Mở thư viện mẫu có thể kéo sập cả DAW</strong>, vì nó chia cho một độ dài clip tính từ chính các con số của tệp đã lưu — một cặp số xui xẻo là chia cho không, và plugin dừng hẳn thay vì tháo ngược an toàn.","changelog.4c20acd804e4":"<strong>⛔⛔ Lưu một mẫu có thể lặng lẽ xoá một mẫu khác</strong>: «Take 1» và «Take-1» trở thành cùng một tên tệp.","changelog.89c7905e0b4b":"<strong>⛔⛔ Một làn đã khoá có thể biến mất khỏi dự án đã lưu</strong>, vì clip được dựng lại từ hạt giống khi mở lại — và có thể mang nốt vượt quá điểm cuối của một clip ngắn hơn, nên lưới vẽ bốn ô nhịp sạch sẽ trong khi tệp xuất ra lại phát các cú đánh ở ô nhịp năm tới tám.","changelog.96f10a153c71":"<strong>⛔ Chế độ Bài hát chưa bao giờ chạy bộ sàng tính mới</strong>, vì nó được cài trên đường mà thẻ Melody dùng trong khi chế độ Bài hát gọi thẳng các bộ tạo. Một bài kiểm thử khẳng định cách nối dây chứ không phải đầu ra, vì với danh mục đi kèm thì đầu ra đã sàng và chưa sàng giống hệt nhau và bài kiểm thử hiển nhiên sẽ không thể thất bại.","changelog.f4b2d931a43d":"<strong>⛔ Một fill hi-hat thêm bằng tay rơi sớm 40 tick</strong>, vì nó dùng cửa sổ mà lưới dùng để quyết định một nốt đã <em>nhân hoá</em> thuộc ô nào — đúng khi đọc, sai khi ghi.","changelog.0830687ca248":"⚠ Hai cửa kiểm đã báo thành công trên phạm vi hẹp hơn những gì chúng tuyên bố: danh sách làn đã trôi xuống còn 21 trên 37 làn của động cơ, và bài kiểm thử solo lại <em>đòi</em> các phần có giai điệu phải im lặng — đó là cách hành vi ấy lọt qua được lượt duyệt.","changelog.4e59efdbda65":"Thêm — trình duyệt sample bạn thực sự dùng được, và clip trông ra clip, 2026-08-07","changelog.3ac5714f8a97":"<strong>⛔ Trình duyệt sample đã lên màn hình.</strong> Thêm thư mục của bạn một lần và chúng trở lại cùng dự án; nhấp vào một sample để xem dạng sóng và <strong>kéo nó thẳng lên một làn trống</strong>. Mọi thứ phía sau tính năng này đã được phát hành ở phiên trước mà không có cách nào tới được.","changelog.e158007006c0":"<strong>Một trình phát nghe thử bên dưới trình duyệt</strong> — nhấp vào bất kỳ đâu trên dạng sóng để phát từ chỗ đó.","changelog.2c629c57d407":"<strong>⛔ Một clip trong bản phối trông như một clip</strong>, vẽ chính các nốt của nó thay vì một cái tên trên một ô tô bóng, nên hai clip của cùng một phần không còn trông giống hệt nhau, và mỗi clip có thể được kéo riêng vào DAW của bạn.","changelog.ef9a103aedc5":"<strong>⛔ Clip đổi được kích thước</strong>: kéo mép phải và hàng đó lặp trên ít ô nhịp hơn bên trong đoạn của nó, mà không dời đoạn hay bất kỳ phần nào khác.","changelog.84e02b004ba3":"<strong>⛔ Khung xem bản phối được bố trí như một DAW.</strong> Tên track trước đây nổi đè lên các clip, nên ở ô nhịp 1, chữ «DRUMS» nằm trên clip đầu tiên của mọi hàng.","changelog.0b3d5bf7e564":"Sửa — những gì ba lượt duyệt tìm ra, 2026-08-07","changelog.b35639f57cb2":"<strong>⛔ Những nốt dài hơn của một clip đã đổi kích thước ngân lấn sang lần lặp kế tiếp của chính nó</strong>, nên DAW cắt cụt chúng khi va vào nốt đã được đánh lại.","changelog.0c66c5b6f618":"<strong>⛔ Hi-hat mất mọi nốt ghost khi không ở 4/4</strong> — ở 6/8, 12/8 và mọi nhịp x/16, cả dòng ra với cùng một lực nhấn phẳng lì.","changelog.6af16dde009c":"<strong>⛔ Bộ gõ đặt ở «nghịch phách» im bặt hoàn toàn</strong> ở các nhịp x/16 và x/32.","changelog.e476442a0ddc":"<strong>Một clip đã đổi kích thước vẽ ra những nốt nó không phát</strong>, hiện cả mẫu bị ép vào mỗi lần lặp.","changelog.4f5db5bbdf0a":"<strong>Tung lại một đoạn, hoặc sao chép, dán hay kéo một clip, đã vứt bỏ độ dài vòng lặp mà bạn đặt cho nó.</strong>","changelog.5878d98d269b":"<strong>Bassline vẫn có thể phản chiếu sai tiếng kick</strong> nếu bạn đổi số ô nhịp, ghim một tempo hay đổi tâm trạng giữa lúc tạo trống và tạo bass.","changelog.6e929e8afe20":"Sửa — trình phát nghe thử, 2026-08-07","changelog.b2864d845e0f":"<strong>⛔ Nghe thử một sample bị im lặng mỗi khi công tắc Âm thanh tắt.</strong> Nút Phát sáng lên, trình phát nói nó đang phát, còn vạch phát đứng im ở 0:00. Tắt âm thanh nghĩa là «gửi MIDI tới sampler của riêng tôi, đừng phát chồng» — nó chưa bao giờ nhằm ngăn trình duyệt phát tệp bạn vừa nhấp.","changelog.b9168982fff3":"<strong>Nhấp vào một dạng sóng đang tạm dừng sẽ dời vạch phát rồi tự hoàn tác</strong> nửa giây sau, và nhấn Phát thì vạch phát đứng yên tới nửa giây trong khi sample đã vang lên.","changelog.86b2b194f286":"Sửa — 2026-08-07","changelog.9163da2a1dd7":"<strong>⛔ Toàn bộ khung xem bản phối được vẽ mà không có kiểu dáng</strong>, và đã như vậy từ khi nó được viết: mọi màu nó yêu cầu đều là một cái tên mà ứng dụng này không định nghĩa, nên các clip không có màu nền, các đường lưới vô hình và vạch phát là một dải trong suốt.","changelog.3a92a8640214":"<strong>Bassline rơi vào những tiếng kick mà phần trống không hề chơi.</strong> Một tiếng bass phản chiếu kick — phần lớn danh mục trap và drill — đang sao chép một mẫu kick được dựng lại từ sai hạt giống: với boom-bap, 13 trên 13 nốt bass từng nằm trên một tiếng kick thật, và với quy trình làm việc thông thường con số đó đã tụt xuống 9; với UK drill, xuống 1 trên 14.","changelog.6683ee09105f":"<strong>Bộ gõ đặt ở «nghịch phách» lại chơi thẳng trên phách</strong> ở mọi nhịp x/8 — lớp lẽ ra nằm giữa các nhịp đập lại nhân đôi chúng.","changelog.81d18857bf68":"<strong>Sáu giọng trống được phát hành mà không có cách nào nghe được.</strong> Ride, crash, tom, shaker và cowbell có trong bộ kit mà chưa nghệ sĩ nào được viết để chơi chúng.","changelog.7644b0a943fa":"Thêm — một bộ trống thật, một trình duyệt sample, và mỗi thể loại một bộ kit, 2026-08-07","changelog.ff8354926c13":"<strong>⛔ Giờ phần trống của bạn có nhiều hơn năm làn</strong> — mười sáu giọng bộ gõ, và nghệ sĩ dùng những giọng nào là một phần của chính nghệ sĩ đó. Mười lăm mô hình đi kèm đã được <em>viết</em> sẵn một khối bộ gõ mà chưa có gì từng đọc nó, nên UK drill đã đòi một chiếc mõ gỗ từ ngày nó được viết mà chỉ nhận về im lặng.","changelog.90dc63284666":"<strong>⛔ Mỗi thể loại có bộ kit riêng.</strong> Mười một họ, mỗi họ có cách chỉnh âm, dải cao và độ drive riêng. Mức trần của boom-bap là 8 kHz vì đó là mức mà một chiếc SP-1200 lấy mẫu được, và chính dải cao bị thiếu ấy <em>là</em> âm thanh. Tám nghệ sĩ đã gọi tên bộ kit họ muốn suốt nhiều tháng mà tất cả vẫn đang phát sample trap.","changelog.2b625ec90b28":"<strong>Làn 808 giờ được gọi là Sub</strong>, vì nó là phần bass có cao độ và trượt, không phải trống bass. Các dự án đã lưu mở ra y như trước.","changelog.704ed387ab2f":"<strong>⛔ Tạo làm biến đổi bản thu mà không đổi bản ghi.</strong> Nhấn Tạo ở phần trống, chuyển sang melody, nhấn lần nữa: bạn nhận được một melody khác viết trên <em>cùng</em> tông và vòng hoà âm. Trước đây, lần nhấn thứ hai rút ra một phần hoà âm chẳng liên quan và hai phần chưa từng được viết theo nhau.","changelog.ff4a09ab118e":"<strong>Một ngoặc vùng lặp bạn kéo bị bỏ qua mỗi khi một bộ tạo thứ hai được bật</strong> — vốn là mặc định. Nó chạy khi một phần đang phát và lặng lẽ không làm gì khi có hai phần.","changelog.41b8497a15e0":"<strong>Phát và Dừng sáng hay tối sai lúc.</strong> Tạo trống, nhấp Melody, và Phát tắt sáng trong khi phần trống đã sẵn sàng và lẽ ra sẽ vang lên.","changelog.ab49c439eefd":"<strong>Chỉ số vị trí đếm theo sai clip</strong>: bốn ô nhịp trống cạnh tám ô nhịp melody hiển thị từ 1.1 tới 5.1 trên tám ô nhịp thời gian thật.","changelog.649c3a0d7720":"<strong>Lặp tự bật lại sau khi mở lại cửa sổ plugin</strong>, dù bạn đã đặt nó thế nào.","changelog.ded642647f5b":"Thêm — phát các bộ tạo cùng nhau, và 808 biết slide, 2026-08-06","changelog.9e2b80b85108":"<strong>Phát nhiều bộ tạo cùng lúc, hoặc riêng bất kỳ bộ nào.</strong> Một lịch phát chỉ giữ một clip, nên các phần được gộp làm một trước khi vào lịch — đó là lý do không thể làm điều này bằng cách lần lượt nhấn Phát trên từng thẻ.","changelog.b6951a486c5e":"<strong>⛔ Plugin phát được mà không cần DAW chạy.</strong> Nghe thử một beat không còn đồng nghĩa với việc bật ghi một track và chạy cả dự án. Khởi động thanh điều khiển phát của DAW sẽ lấy lại quyền ngay, nên hai bên không bao giờ cùng phát một lúc.","changelog.f10831f4b7f5":"<strong>⛔ Nút Lặp đã hoạt động.</strong> Trước đây nó luôn ở trạng thái được nhấn và bị vô hiệu hoá, kèm chú thích khẳng định phát lại luôn lặp vòng — điều thậm chí còn không đúng trừ khi đã kéo một ngoặc vùng lặp.","changelog.8d2084738b75":"<strong>⛔ Các cú slide 808 đã nghe thấy được.</strong> Các bộ tạo đã viết slide từ lâu và MIDI vẫn luôn mang chúng, nhưng mọi tệp WAV kết xuất đều phát chúng thành nốt phẳng. Giờ cao độ có di chuyển, giữ nốt xuất phát trong nửa đầu và lướt qua trong nửa sau — và cùng đoạn mã phục vụ phần nghe thử, phần xuất và thao tác kéo, nên một stem nghe giống tệp <code>.mid</code> bên cạnh nó.","changelog.f9fa438e3093":"Sửa — các làn trống, bảng KIT, và một thanh bên phải bị ngắn, 2026-08-06","changelog.e9469a9c1fda":"<strong>⛔ «Tất cả các track» cho âm thanh trống được gắn nhãn ngược với cách người ta đọc nó.</strong> Nó cho mỗi làn một tệp trong khi một mục thứ hai tên «Thành một clip» lại cho bản mix. Giờ mỗi làn có một mục, và <strong>«Tất cả các track» là mọi làn được trộn vào một tệp duy nhất</strong>.","changelog.ab3f925aaf69":"<strong>⛔ Bảng KIT không còn vẽ đè lên bảng STEMS.</strong> Trong một cửa sổ thấp, mục KIT thu lại còn không có gì trong khi nội dung của nó vẫn giữ nguyên chiều cao, nên chữ của nó bị vẽ đè lên bảng bên dưới thành một vệt nhoè không đọc được.","changelog.b8b2c0b5ce11":"Sửa — cửa sổ trình chỉnh sửa tự đặt kích thước đúng, 2026-08-06","changelog.91804d15bbeb":"<strong>⛔ Dải đen bao quanh giao diện đã biến mất.</strong> Cửa sổ trình chỉnh sửa được đặt kích thước theo một tỉ lệ hiển thị đọc ở một thời điểm khác với phần hình học còn lại, nên ứng dụng chỉ chiếm hai phần ba cửa sổ bao quanh nó.","changelog.0e393d0c7690":"<strong>⛔ Nút kích thước đưa ra hai kích thước, không phải bốn.</strong> Tỉ lệ hiển thị được đọc mới ở mỗi lần nhấn và thay đổi ngay dưới trình chỉnh sửa — nó đọc ra 100% cho tới khi hệ thống cửa sổ được báo rằng tiến trình nhận biết DPI, điều xảy ra <em>sau khi</em> trình chỉnh sửa đã được đặt kích thước — nên mỗi mức trong hai mức thiết lập sẵn lặng lẽ mang nghĩa hai cửa sổ khác nhau.","changelog.8c4d3b4461cd":"<strong>⛔ Bảng Stem không còn biến mất ở kích thước cửa sổ mặc định.</strong> Thanh bên mở ra ở 1440px và trang được bố trí đúng 1440px, nên thanh bên không có chút lề nào: cả thanh bên biến mất ở mọi kích thước trừ đúng kích thước tình cờ phóng to đúng hệ số 1.","changelog.f3d631ac4ef8":"<strong>⛔ Menu kéo ra theo từng làn không còn bị cắt mất một nửa</strong>, nên các làn trống phía dưới giờ đã kéo ra được.","changelog.65a1a2828214":"Sửa — sáu lỗi tìm ra khi chạy plugin trong Ableton, 2026-08-06","changelog.ae0a642482e3":"<strong>⛔ Giờ Tạo thực sự tạo ra cái mới.</strong> Nhấn Tạo liên tục trả về <em>cùng một beat</em> mãi mãi, khiến sản phẩm trông như chỉ có một vòng lặp cho mỗi nghệ sĩ: hạt giống do động cơ chọn bị chép ngược vào ô hạt giống và gửi lại ở lần nhấn kế tiếp. Giờ ô này phân biệt hạt giống do bạn chọn với hạt giống do động cơ chọn.","changelog.132f99a15823":"<strong>⛔ Âm thanh được thả vào không còn phát sai tempo.</strong> Một tệp <code>.wav</code> được kéo ra trước đây không mang tempo nào cả, nên Ableton warp nó theo phỏng đoán — một vòng lặp 140 BPM phát ở 96 trong một dự án 120.","changelog.afcec78896e3":"<strong>Bảng Stem tự mở ra</strong> ở lần đầu tiên một phiên tạo nhạc: trước đây nó nhớ trạng thái thu gọn qua các lần tải lại, trong khi nó chứa cách duy nhất để đưa một mẫu ra ngoài.","changelog.5029b5a24655":"<strong>⛔ Các nút điều khiển không còn nằm đè lên làn lực nhấn.</strong> Lỗi tồn tại hàng tháng trời: hàng Tạo/hạt giống/ô nhịp nổi lơ lửng trên trình chỉnh sửa, nên một đầu thanh lực nhấn nằm bên dưới hoàn toàn không kéo được.","changelog.6b02e0d363a4":"Thêm","changelog.b62d9b57e008":"<strong>Kéo một phần thẳng ra khỏi plugin và thả lên track của DAW.</strong> Mỗi phần có một tay nắm <strong>MIDI</strong> và một tay nắm <strong>Âm thanh</strong>; khi bật <strong>Theo làn</strong>, phần trống thành mỗi làn một tay nắm. Tệp mang cái tên mà một nhà sản xuất sẽ đặt — <code>trap - Snare - 140 BPM - C# Minor</code>. ⚠ MIDI và Âm thanh cố ý đưa ra hai danh sách khác nhau: một làn mà bộ kit không chơi được vẫn kéo ra dưới dạng MIDI, vì các nốt là thật, nhưng không dưới dạng âm thanh, vì sẽ kết xuất ra im lặng.","changelog.4de5200c76df":"<strong>Cả bản phối kéo ra được dưới dạng âm thanh</strong>, có báo tiến độ và dừng ngay khi thao tác bị bỏ dở — đó mới là mảnh còn thiếu, không phải phần kết xuất.","changelog.39b376291b8b":"<strong>Các clip có thể được kéo đi khắp bản phối</strong>, trước đây sắp xếp lại nghĩa là sao chép, dán, rồi quay lại xoá bản gốc.","changelog.f94f8922bef2":"<strong>Lưới trống là một trình chỉnh sửa</strong>, trước đây nó chỉ đọc và chính tiêu đề của nó nói vậy. ⚠ Chỉnh sửa tác động lên <strong>tick, không bao giờ lên ô</strong>: một ô đã vứt bỏ thông tin cú đánh nằm ở đâu bên trong nốt 1/16, mà đó chính là thứ tạo nên một liên âm.","changelog.eebab717e7db":"<strong>Xuất riêng từng phần</strong>, dùng chung cách đặt tên và byte với thao tác kéo — một vòng lặp bạn kéo ra và cũng vòng lặp đó khi xuất phải là cùng một tệp.","changelog.f1cc8234d750":"<strong>One-shot của riêng bạn trên bất kỳ phần nào</strong>, được lưu dưới dạng <strong>đường dẫn</strong>; một tệp đã bị di chuyển sẽ được báo lại thay vì lặng lẽ quay về mặc định.","changelog.adbfdc511003":"<strong>Các cú đánh trống dịch cao độ</strong> trong một khoảng mà mỗi nghệ sĩ tự viết — rage đi tám, Drake hai, <code>country-train</code> không đi, vì một train beat không đổi cao độ snare của nó.","changelog.c68e2faaa335":"<strong>Tạo nhạc cho chọn 4 hoặc 8 ô nhịp.</strong> Hai ô nhịp đã bị bỏ — hai ô nhịp không đủ chỗ cho các fill và đoạn quay vòng mà mô hình viết, nên nó làm mọi nghệ sĩ nghe giống nhau. ⚠ Một dự án đã lưu ở hai ô nhịp vẫn mở ra ở hai ô nhịp.","changelog.992aa08533ad":"<strong>Piano roll dùng con trỏ thường</strong>, không phải <code>+</code>: hình chữ thập là thứ dành cho công cụ vẽ, còn nhấp vào lưới trống thì chọn chứ không vẽ.","changelog.0b87415f26cb":"Sửa — một lượt duyệt mã mức xhigh cho các phần trên, 2026-08-06","changelog.a5979ff4f5ab":"Mười lăm lỗi đã được xác minh, bốn trong số đó lẽ ra đã đưa thứ gì đó hỏng vào bản phát hành.","changelog.059b3952ef8a":"<strong>⛔ Kéo một clip trong bản phối có thể xoá một clip khác.</strong> Mỗi đoạn giữ một clip cho mỗi phần, nên kéo hai clip của cùng một phần nghĩa là clip thứ hai ghi đè lên clip thứ nhất sau khi cả hai đã được nhấc lên — mất luôn, mà không có gì trên màn hình báo.","changelog.e6019aec8c0d":"<strong>⛔ Các chip kéo Âm thanh biến mất nếu bạn từng thu gọn bảng KIT</strong>, vốn là thứ duy nhất nạp bộ kit — nên Stem kết luận không có gì phát được và ẩn mọi tay nắm Âm thanh, vĩnh viễn, trong khi Xuất vẫn tiếp tục đưa ra âm thanh.","changelog.4513b1c417f8":"<strong>⛔ Phần trống không còn kéo ra được thành một tệp</strong>, vì các nút đã thành nút mở menu mà nút mở menu thì không kéo được.","changelog.2eabac1a208f":"<strong>⛔ Âm thanh được thả vào phát sai tempo ở 6/8, 9/8, 12/8 và 7/8</strong>: chunk tempo đếm số phách của một ô nhịp bằng tử số, nhưng âm thanh được đo theo nốt đen. Đó chính là lỗi mà chunk này được thêm vào để sửa, giờ quay lại qua bộ chọn nhịp.","changelog.4c29aba1855d":"<strong>Một clip đã cắt gọn khi kéo ra dưới dạng «Tất cả các track» ghi ra các tệp im lặng</strong> — tám tệp thả vào DAW, bảy tệp không chứa gì.","changelog.4f7838402f37":"Đã kiểm chứng","changelog.02dc39a2cae1":"<strong>⛔ Nguồn kéo trên macOS giờ được một trình biên dịch kiểm tra, ngay từ Windows.</strong> Đó là tệp duy nhất không bản dựng cục bộ nào biên dịch, và nó có <strong>bốn lỗi và hai lỗi lint</strong> — lỗi nào cũng sẽ bị bộ chạy macOS của CI tìm ra, mỗi lần push một lỗi. <code>cargo check --target aarch64-apple-darwin</code> kiểm tra kiểu cho macOS mà không cần bộ công cụ của Apple, vì chỉ bước <em>liên kết</em> mới cần. ⚠ Nó vẫn không chứng minh được gì về hành vi.","changelog.ffd42ed2f7ee":"<strong>Thao tác kéo trên macOS và Linux không còn làm treo phần mềm chủ.</strong> Cả hai bắt đầu một lần kéo rồi chặn chính vòng lặp sự kiện phải chạy nó — mười phút DAW đứng hình mà không tệp nào được thả. Windows chưa bao giờ bị ảnh hưởng; thao tác kéo của nó thực sự là modal, chính điều đó khiến sai lầm này dễ lặp lại tới hai lần.","changelog.061558cb7b58":"<strong>Lần đầu tiên plugin vượt qua cả hai trình kiểm định tự động</strong> — <code>pluginval</code> ở mức nghiêm ngặt tối đa với VST3 và <code>clap-validator</code> với CLAP: 33 đạt, 10 bỏ qua, 1 thất bại, mà lỗi đó là phép chia cho không của chính trình kiểm định.","changelog.1a78eb82eb61":"<strong>Linux được kiểm chứng cục bộ</strong>, trong Docker.","changelog.11350441bdbc":"<strong>Mọi nghệ sĩ đều viết cùng một roll snare</strong>, dựng từ một đường dốc viết cứng không đọc mô hình cũng không đọc hạt giống: <strong>sáu trong mười nghệ sĩ trap chủ lực tạo ra roll giống hệt từng byte</strong>, và mỗi mô hình chỉ đạt từ một tới bốn roll khác nhau trong bốn mươi hạt giống.","changelog.c2fd00b3b92c":"<strong>UK drill, NY drill và Pop Smoke chỉ viết đúng một mẫu kick, mãi mãi</strong>, một ngữ pháp bốn ô nhịp tường minh không bao giờ chạm tới hạt giống. ⚠ Mọi biến thể mới đều nằm trong khuôn tresillo mà nghiên cứu mô tả.","changelog.bf5ae982968d":"<strong>Một 808 có thể ngân xuyên thẳng qua một fill</strong>: danh sách tắt tiếng chỉ chứa backbeat, nên một tiếng kick ở phách mà fill bắt đầu để 808 ngân suốt cả đoạn roll — đúng điều mà drill được định nghĩa để chống lại.","changelog.0948365cea7b":"<strong>Hai mô hình anh em quá gần nhau để phân biệt</strong>: <code>pop-smoke</code> chỉ khác <code>ny-drill</code> 0.05 ở bốn con số và tạo ra beat giống hệt ở 16 trên 200 hạt giống. Số beat trùng nhau trên toàn danh mục giờ là <strong>không</strong>.","changelog.732bec7f510f":"<strong>Một bài hát xuất ra không còn đến dưới dạng một nhạc cụ chơi mọi thứ cùng lúc.</strong> Mọi phần có cao độ đều nằm trên kênh MIDI 0, mà nhiều phần mềm chủ tách một tệp SMF nhập vào theo <strong>kênh</strong> chứ không theo track.","changelog.2aebbfe45729":"<strong>Hoà âm không còn bão hoà.</strong> Các thế bấm từng được chọn theo chi phí tối thiểu tuyệt đối, khiến thế bấm thành một hàm thuần tuý của hợp âm: <code>rage</code> chỉ tạo ra <strong>8 vòng hoà âm khác nhau trong 1.000 hạt giống</strong> trong khi melody của nó tạo ra 823.","changelog.c44613bc0e19":"<strong>Chế độ Bài hát: chọn một nghệ sĩ, nhấn Tạo, và nhận cả một bản phối.</strong> Động cơ lấy mẫu một trong những cấu trúc bài hát của chính nghệ sĩ và dựng mỗi phần một clip cho mỗi đoạn. Các đoạn cùng loại dùng chung một clip, vì phiên khúc 1 và phiên khúc 2 là cùng một beat.","changelog.a6592c5774d6":"<strong>Chuyển đoạn</strong> — các nhịp ngắt trước một đoạn hook, cú đổi kiểu ở nửa sau, đoạn fade của outro. Mỗi cái là thuộc tính của <em>vị trí một đoạn nằm</em> chứ không phải của các nốt trong nó, và mỗi cái được ghi vào tệp xuất ra chứ không chỉ được vẽ ra.","changelog.5829c0281641":"<strong>Một bài hát đã phát được</strong>, và việc xếp lặp giờ nằm ở một chỗ mà cả trình phát lẫn trình xuất đều đọc — nên <strong>những gì bạn nghe và những gì bạn xuất ra đều từ cùng một phép tính</strong>.","changelog.c57be389be35":"<strong>Tung lại một đoạn</strong> mà không động tới phần còn lại. Một phần Hợp âm hay Trống đã khoá được trao lại làm phần hoà âm và bộ kit để viết theo.","changelog.032c26527262":"<strong>Một bản phối đã chỉnh sửa được lưu cùng dự án</strong>, trước đây phối cả một bài rồi mở lại là mất sạch.","changelog.1d66ba0727df":"⚠ <strong>Stem là MIDI, không phải âm thanh</strong>: ghi ra bốn tệp <code>.wav</code> im lặng rồi gọi chúng là stem còn tệ hơn không đưa ra chúng.","changelog.61e0a7809c2d":"<strong>Mỗi bộ tạo giữ clip riêng.</strong> Trước đây năm bộ dùng chung một ô, nên tạo một bassline sẽ huỷ melody đang có ở đó.","changelog.383945d46625":"<strong>Tạo tất cả sẽ lấp đầy mọi phần từ một hạt giống</strong>, đó là điều khiến năm phần thành một bản nhạc chứ không phải năm vòng lặp cùng tông.","changelog.a16dc6673cf2":"<strong>Các bộ tạo có giai điệu đã phát ra âm thanh</strong>, trước đây bộ kit nghe thử chỉ có bộ gõ và bốn bộ tạo trong số đó kết xuất ra im lặng.","changelog.8a132c8da61f":"Chế độ Bài hát đã qua bốn lượt duyệt trước khi phát hành, mỗi phát hiện đều có một bài kiểm thử được theo dõi thất bại trước: <strong>giờ hoàn tác chạm được tới tệp dự án</strong>; <strong>hoàn tác qua một lần đổi nghệ sĩ không còn làm sống lại bản ghi của nghệ sĩ trước</strong>; <strong>khoá và vòng lặp đi theo đoạn của chúng khi bạn nhân bản</strong>, trước đây một ổ khoá bị vẽ ở sai đoạn và một lần tung lại tạo lại đúng những clip mà nó nói là đã ghim; và <strong>tung lại tôn trọng bản ghi mà nó thuộc về</strong>.","changelog.696a4b7c3c6f":"<strong>Một piano roll, và cuối cùng bốn phần có giai điệu cũng hiện lên được.</strong> Chúng được tạo qua cầu nối và rơi vào track của phần mềm chủ mà chưa từng xuất hiện trên màn hình. Dùng canvas thay vì DOM, vì một roll sâu 128 hàng và cách làm của lưới trống sẽ cần khoảng 15.000 phần tử trước cả khi có một nốt — kèm các nốt được xuất ra dưới dạng một danh sách ẩn về mặt hiển thị, để trình đọc màn hình tới được trình chỉnh sửa và bài kiểm thử khẳng định được nó. Chọn, đổi độ dài, các phép biến đổi và một làn lực nhấn theo bộ chuẩn của Ableton và FL, và <strong>bộ âm giai tăng từ 12 lên 41</strong>. ⚠ Một clip đã chỉnh sửa được lưu cùng dự án: plugin lưu <em>yêu cầu</em>, vì động cơ là tất định, và ngay khi bạn dời một nốt thì điều đó không còn đúng nữa.","changelog.326ba70fe140":"<strong>Plugin phát ra âm thanh</strong>, được kết xuất theo từng đoạn cắt tại mỗi note-on để một cú đánh rơi đúng sample của nó thay vì bị lượng tử hoá theo ranh giới khối — lệch tới 11 ms ở 512 sample, tức một nốt 1/32 ở 140 BPM.","changelog.e6b17ec4bff4":"<strong>Cả năm bộ tạo đều dùng được trong plugin.</strong> Melody, melody đối và bassline vẫn luôn nằm trong động cơ mà cầu nối lại từ chối chúng với thông báo «chưa được triển khai» — lời từ chối nằm ở cầu nối chứ không phải ở thứ nó báo về.","changelog.4765927194b2":"<strong>Crate của ứng dụng máy tính đã không còn.</strong> <code>src-tauri/</code> — vỏ ứng dụng, khay hệ thống, trình cập nhật, trình báo sập và đường âm thanh — đã bị gỡ. Sản phẩm đã ngừng vào 2026-07-29; crate sống lâu hơn nó vì nó sinh ra <code>ipc-audio-types.ts</code> và giữ sampler duy nhất mà dự án này có, và sampler đã được chuyển vào plugin trước, đó là điều khiến việc gỡ này an toàn chứ không làm mất gì. Hai thứ được sửa trên đường đi, cả hai đều hỏng trong plugin đang phát hành chứ không chỉ là mã chết: <strong>Cài đặt và Giới thiệu không mở được</strong>, vì thanh tiêu đề từng là lối vào duy nhất của chúng, và <strong>bảng Giới thiệu hiện một dấu gạch dài thay cho phiên bản</strong>.","changelog.c7c7dc30d37e":"<strong>Plugin không mở bất kỳ kết nối đi ra nào.</strong> Không phải đổi câu chữ: danh sách cho phép của chuỗi cung ứng từng chứa <code>reqwest</code>, <code>hyper</code>, <code>hyper_rustls</code> và <code>hyper_util</code>, cái nào cũng được biện minh bằng trình cập nhật, và giờ nó <strong>trống rỗng</strong> — 187 crate được liên kết mà không có client HTTP nào. Sáu miễn trừ RUSTSEC không còn khớp với gì và cũng đã bị xoá; một mục bỏ qua không khớp với gì là một sự cho phép thường trực để một cảnh báo bảo mật quay lại mà không ai hay.","changelog.3c9e09d2a535":"<strong>Một máy không có WebView2 không còn kéo sập cả DAW theo.</strong> Mở trình chỉnh sửa khi không có runtime WebView2 — hoặc khi thư mục tạm chỉ đọc, hoặc khi hồ sơ trình duyệt của plugin đã bị một môi trường WebView2 khác giữ, chính là điều xảy ra khi mở bản độc lập song song với một DAW — gây panic ngay trong callback mở trình chỉnh sửa của phần mềm chủ. Bản dựng phát hành dừng hẳn khi panic, nên phần mềm chủ không bắt được và phiên làm việc mất theo. Giờ trình chỉnh sửa mở ra trống và cho biết lý do. Hai lỗi panic liên quan cũng được xử lý tương tự: trình xử lý giao thức tuỳ chỉnh, vốn chạy từ một khung mà panic thậm chí không thể tháo ngược ra ngoài, giờ trả về 500.","changelog.6daf228152f8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.cc6bcb5b7f8b":"Thêm — hoàn tác/làm lại không giới hạn, và cửa chặn giấy phép","changelog.8566f666d778":"<strong>Hoàn tác/làm lại không giới hạn</strong> (FMM-U01). Mọi thay đổi trong phiên — nghệ sĩ, hạt giống, số ô nhịp, các giá trị ghim, tự đồng bộ và từng lần tạo — lùi lại bằng <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> và tiến tới bằng <code>Ctrl</code>/<code>Cmd</code>+<code>Shift</code>+<code>Z</code> hoặc <code>Ctrl</code>+<code>Y</code>. Không giới hạn độ sâu: một mục chỉ là vài giá trị vô hướng cộng một tham chiếu <code>Pattern</code> <em>dùng chung</em>, vì một mẫu được suy ra từ hạt giống chứ không được lưu, nên một trăm bước trên cùng một lần tạo chỉ tốn một mẫu. Một loạt chỉnh sửa trên cùng một nút điều khiển trong vòng 600 ms được gộp thành một bước; hai lần tạo không bao giờ gộp lại, dù tung lại nhanh đến đâu. Được ghi nhận qua một đăng ký vào kho trạng thái chứ không phải qua lời gọi theo từng hành động, nên một hành động trong tương lai không thể quên đăng ký — cùng lập luận mà phần lưu phiên đã đưa ra. Được kích hoạt <em>sau khi</em> khôi phục dự án, nên <code>Ctrl</code>+<code>Z</code> không thể lùi về trước phiên mà phần mềm chủ đã trao lại cho một plugin trống.","changelog.31f95ffe2fd4":"<strong>Cửa chặn giấy phép ở lần chạy đầu.</strong> Thoả thuận được biên dịch vào từ <code>EULA.md</code> và hiện ra trước mọi thứ khác; không có gì được tạo, phát, xuất hay lưu cho tới khi nó được chấp nhận. <strong>Nút Đồng ý bị vô hiệu hoá cho tới khi văn bản được cuộn tới cuối</strong>, vì yêu cầu là «bạn không thể dùng nó cho tới khi đọc nó», mà một nút bấm được ngay thì chẳng đòi ai đọc gì. ⛔ Được ép buộc ở ranh giới RPC của plugin chứ không ở giao diện — một trang bị tải lại, bị vượt qua hay bị điều khiển từ devtools vẫn không thể tạo nhạc — và bằng một <em>danh sách cho phép</em>, nên một lệnh mới phải được cố ý thêm vào mới gọi được trước khi chấp nhận. <strong>Từ chối khiến plugin bất động chứ không đóng DAW</strong>, điều mà một plugin không bao giờ được làm; thoả thuận có thể được mở lại và chấp nhận bất cứ lúc nào, và mọi thứ hoạt động ngay sau đó. Việc chấp nhận được lưu theo người dùng, cạnh các cài đặt sẵn — không bao giờ trong tệp dự án, vì như thế sẽ bắt một người cộng tác chấp nhận lại chỉ vì họ mở bài hát của bạn.","changelog.eaa77cffa60d":"<strong>Bản độc lập mang biểu tượng ứng dụng trên Windows</strong>, kèm chuỗi tên sản phẩm, công ty và bản quyền, qua một <code>plugin/build.rs</code> mới. Thiếu trình biên dịch tài nguyên chỉ sinh cảnh báo chứ không làm hỏng bản dựng.","changelog.56cc4a00bc11":"<strong>Một trang tài liệu</strong> trong <code>docs/</code>: plugin làm gì, nó đi theo phần mềm chủ ra sao, hạt giống, cài đặt sẵn, phím tắt và quyền riêng tư, kèm tìm kiếm và một nhật ký thay đổi ngắn.","changelog.79779a61c76b":"<strong>Bản độc lập trên Windows mở ra một cửa sổ trống</strong> (TASK-P16). <code>open_blocking</code> của <code>baseview</code> bơm thông điệp bằng <code>GetMessageW(&amp;mut msg, hwnd, …)</code> — một <code>hwnd</code> khác NULL, vốn chỉ lấy thông điệp cho cửa sổ đó và các cửa sổ con của nó và <strong>không bao giờ lấy thông điệp của luồng</strong>. WebView2 là COM/STA và gửi các thông báo hoàn tất của nó đúng dưới dạng đó, qua một cửa sổ chỉ nhận thông điệp do COM sở hữu, nên trình xử lý giao thức tuỳ chỉnh không bao giờ được gọi, việc điều hướng không bao giờ hoàn tất và trang cứ nằm ở <code>about:blank</code>. Giờ adapter được vendor vào sẽ rút cạn hàng đợi từ <code>on_frame</code>, <strong>tắt trừ khi tiến trình chủ động bật</strong> — <code>plugin/src/bin/standalone.rs</code> là nơi gọi duy nhất và DAW không bao giờ chạy nó, nên hàng đợi của phần mềm chủ không bao giờ bị động tới. ⛔ Nó bỏ qua các thông điệp thuộc về cửa sổ trình chỉnh sửa và các cửa sổ con: gửi đi những thông điệp đó sẽ vào lại thủ tục cửa sổ của baseview trong khi nó đang giữ một lần mượn <code>RefCell</code>, gây panic trong một khung <code>extern &quot;system&quot;</code> và làm tiến trình dừng hẳn. Đã kiểm chứng bằng cách chụp ảnh cửa sổ, không phải bằng một bản dựng xanh.","changelog.2589337da507":"<strong>Không có bản tải về trước <code>v1.0.0</code>.</strong> Các bản phát hành ứng dụng máy tính <code>v0.1.0</code> và <code>v0.2.0</code> đã được rút khỏi GitHub (chuyển thành bản nháp; tệp vẫn nguyên vẹn), và trang tài liệu không đưa ra đường dẫn tải về nào.","changelog.0ce86044cfae":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.39dc456bb806":"Thêm — tạo giai điệu, và các tâm trạng nhân nó lên","changelog.54cbe30a27b8":"<strong>Bộ tạo melody</strong> (TASK-035, FR-005). Các cấu trúc câu (vòng riff, hỏi/đáp, xướng/hoạ, vòng cung dài), thiên về nốt hợp âm ở phách mạnh, nốt màu, phân bố quãng và đường nét, nhảy quãng tám, biến tấu ở phần kết, và các thủ pháp riêng của từng thể loại: motif staccato hai tới ba nốt của rage, điểm khởi âm soi theo snare và thế bấm nhân đôi của drill, các ô nhịp móc đơn đều và những khoảng lặng có chủ ý. Cao độ được chọn dưới dạng <strong>bậc âm giai</strong> rồi mới được chuyển thành nốt MIDI, nên việc giữ đúng tông là do cấu trúc chứ không phải được lọc ra sau đó.","changelog.ded02e33501e":"<strong>Bộ tạo melody đối</strong> (TASK-036, FR-006). Tiếng vọng quãng tám, tiếng vọng chuông, rải hợp âm, câu lick đáp và pad ngân dài, được đặt vào các khoảng trống của melody ngay từ cấu trúc chứ không phải lọc ra sau đó.","changelog.eca3ea3c0cbd":"<strong>Tâm trạng</strong> (TASK-040V, nửa phía động cơ). Một mô hình có thể viết các <code>modes</code> có tên — trap đi kèm dark, bounce, melodic và minimal — mỗi cái là một phần ghi đè được hợp vào mô hình <em>trước khi</em> tạo, nên mọi bộ tạo đều tôn trọng tâm trạng mà không cần biết tâm trạng tồn tại. Tâm trạng được kế thừa qua <code>extends</code>, nên một nghệ sĩ chỉ đưa ra những tâm trạng mà dòng dõi của chính họ có.","changelog.547190faa689":"<strong>Cài đặt sẵn do plugin sở hữu</strong> (TASK-P13, nửa phía phiên). Sáu cài đặt sẵn mặc định được biên dịch vào tệp nhị phân, cài đặt sẵn của người dùng nằm trong thư mục dữ liệu theo người dùng của nền tảng, và một bảng ở thanh bên phải. Không cài đặt sẵn mặc định nào ghim tempo — điều đó sẽ đè lên DAW của bạn khi nạp.","changelog.65770bb90ada":"<strong>Trình chỉnh sửa trên Linux</strong> (TASK-P12). Giờ cửa sổ của plugin mở được trên Linux qua X11 và WebKitGTK, được kiểm chứng bằng cách chụp ảnh nó dưới Xvfb chứ không phải bằng một bản dựng xanh.","changelog.b0300de13023":"<strong>Một melody lặp lại không còn chỏi với các hợp âm mà nó lặp lại bên trên.</strong> Giờ một riff đi theo vòng hoà âm, trong khi vẫn giữ đường nét và tiết tấu riêng.","changelog.247d12fdb7be":"<strong>Melody đối không còn im lặng khoảng một nửa số lần.</strong> Tiếng vọng quãng tám được làm trễ, vì một bản sao quãng tám với độ trễ bằng không chỉ là một lần nhân đôi.","changelog.313e41270887":"<strong>Các pad ngân dài bấm nhiều hơn chỉ nốt gốc của hợp âm</strong>, và tự chọn quãng tám.","changelog.8395c17cc35d":"<strong><code>echoOffset: &quot;1/8&quot;</code> đã được đọc.</strong> Bộ phân tích giá trị nốt biết <code>&quot;8th&quot;</code> và <code>&quot;16T&quot;</code> nhưng lặng lẽ bỏ qua cách viết thứ ba mà bộ dữ liệu dùng.","changelog.be33f8017295":"<strong>Ô hạt giống hiển thị trọn một hạt giống.</strong> Nó từng rộng 12 ký tự trong khi một <code>u64</code> có 20 chữ số, nên hạt giống dài bị cắt mất — và một hạt giống bạn không đọc được là hạt giống bạn không gõ lại được.","changelog.e93ad35a782f":"Thay đổi — Freally MIDI Master đang trở thành một plugin","changelog.e77df776964c":"Quyết định ngày 2026-07-28. Không vì bản thân định dạng: một plugin được trao tempo, nhịp và đầu phát của phần mềm chủ, nên một mẫu được tạo ra sẽ rơi vào đúng bài bạn đang viết thay vì ở tempo mà nghệ sĩ tình cờ được viết. <code>docs/product-roadmap.md</code> ghi lại quyết định, những gì còn lại và những gì không.","changelog.1edfdd003cdf":"<strong>Crate <code>plugin/</code> mới</strong> trên <code>nih-plug</code>, xuất ra <strong>CLAP</strong>. VST3 và AU được <code>clap-wrapper</code> chiếu ra từ đó lúc đóng gói.","changelog.bf25160e0d26":"<strong>Crate <code>engine</code> không thay đổi</strong>, đó chính là mục đích của việc giữ nó không dính tới các kiểu của lớp vỏ. Không FFI và không C++.","changelog.a9420b95b887":"<strong>Đồng bộ tempo với phần mềm chủ</strong>, theo thứ tự ưu tiên <strong>ghim của người dùng &gt; phần mềm chủ &gt; mô hình</strong>. Trap viết ở 140 sẽ được tạo ở 92 trong một dự án 92 BPM; tempo ghim thắng phần mềm chủ; phần mềm chủ chưa báo tempo thì để mô hình dùng giá trị của chính nó.","changelog.e33f68653f46":"<strong>Các nốt được xuất thẳng lên track của phần mềm chủ</strong>, thay cho việc kéo ra.","changelog.a8f70eb81ba2":"<strong>Phiên được lưu cùng dự án.</strong> Nghệ sĩ, hạt giống, các giá trị ghim, số ô nhịp và kích thước cửa sổ đi qua chính các lệnh gọi trạng thái của phần mềm chủ — không có tệp cài đặt và không có đường dẫn nào phải tìm, và một phiên thuộc về một <em>bài hát</em> chứ không thuộc về một cái máy. Các nốt không được lưu; các đầu vào tạo ra chúng thì có, vì động cơ là tất định và một tệp dự án không nên mang những nốt có thể tạo lại.","changelog.105c98ac6345":"<strong>Cửa sổ có ba tỉ lệ</strong> (nhỏ, vừa, lớn) trên một nút ở thanh điều khiển phát. Bố cục vẫn là 1440x900 ở mọi tỉ lệ — cửa sổ được vẽ nhỏ lại, chứ không bị cắt bớt phần hiển thị — nên các bảng kit và phiên không bao giờ biến mất chỉ vì cửa sổ thu nhỏ.","changelog.7e09563eaf78":"<strong>Đã kiểm chứng trong Ableton Live 12 (VST3) và FL Studio (CLAP).</strong> FL là phần mềm chủ đầu tiên nạp chính tệp <code>.clap</code> thay vì bản được chiếu ra.","changelog.824480676fdb":"<strong>Giờ các bản phát hành có kèm plugin</strong>, dưới dạng một tệp zip cho mỗi nền tảng chứa cả <code>.clap</code> lẫn <code>.vst3</code>, được <code>clap-validator</code> kiểm định trước khi bản nháp được công bố và bị <code>verify-downloads.yml</code> từ chối nếu thiếu một trong hai định dạng.","changelog.2b3dec8da18b":"Gỡ bỏ — ứng dụng máy tính đã ngừng","changelog.2e83aecc5538":"Giờ Freally MIDI Master được phát hành dưới dạng <strong>plugin</strong>. Từ đây, các bản phát hành chỉ mang CLAP và VST3, không gì khác; các trình cài đặt cho Windows, macOS và Linux không còn được dựng nữa.","changelog.a99e41cef5bf":"<strong>Nếu bạn đang dùng v0.2.0:</strong> không có gì bạn đã cài ngừng chạy, và không có gì bị gỡ cài đặt. Bản của bạn chỉ đơn giản là không còn tìm thấy bản cập nhật, vì sẽ không có bản nào — kênh cập nhật im lặng chứ không hỏng. Để tiếp tục, hãy cài plugin từ bản phát hành này và nạp nó trong DAW của bạn, nơi có đồng bộ tempo, tông của phần mềm chủ và các nốt nằm ngay trên track. Đó là toàn bộ lý do cho việc chuyển đổi: ứng dụng máy tính không thể biết bạn đang viết bài gì.","changelog.0743cfc41115":"Vấn đề đã biết","changelog.4565e7c201a6":"<strong>Một tệp dự án hỏng có thể làm phần mềm chủ dừng đột ngột.</strong> Trình nạp trạng thái CLAP của <code>nih-plug</code> đọc một tiền tố độ dài thẳng vào một lần cấp phát mà không kiểm tra hợp lý, nên trạng thái sai định dạng làm tiến trình dừng hẳn thay vì chỉ nạp thất bại. Đó là lỗi của thượng nguồn, bản fork đang được duy trì cũng mang y hệt, và cần một bản fork đã vá mới sửa được. Cho tới lúc đó, <code>state-invalid-random</code> của <code>clap-validator</code> được loại trừ theo tên.","changelog.8b8422eaf91b":"<strong>Giao diện được mang sang nguyên vẹn.</strong> <code>src/lib/ipc.ts</code> vốn luôn là đường nối duy nhất và có thêm nhánh thứ ba; ứng dụng React, 18 bộ ngôn ngữ và các design token đều đúng là những thứ ứng dụng máy tính từng phát hành.","changelog.f31c4f9a96b4":"<strong>Chip phiên</strong> — BPM, tông, âm giai và swing, chỉnh được ở thanh bên phải. Để trống nghĩa là nghệ sĩ quyết định; có giá trị nghĩa là bạn quyết định. Khi chạy trong phần mềm chủ, chip tempo đi theo DAW và nói rõ điều đó.","changelog.4c7bcf4c5c18":"<strong>Bộ tạo hợp âm</strong> (FR-004): các họ vòng hoà âm, chồng quãng ba theo điệu thức để mọi cao độ đều nằm trong tông ngay từ cấu trúc, hợp âm mượn, sus và kiểu bỏ nốt giữa của drill, thế bấm hẹp và rộng, và các ô tiết tấu đảo phách 3–5 phách.","changelog.4a720cb1c31f":"<strong><code>scripts/assert-plugin-bundled.mjs</code></strong> — từ chối một tệp nhị phân plugin mà giao diện hoặc bộ dữ liệu không nhúng được vào, vì nếu không thì lỗi đó chỉ hiện ra như một cửa sổ trống không kèm thông báo lỗi nào.","changelog.1394f31a74f1":"<strong><code>npm run plugin:standalone</code></strong> — plugin trong cửa sổ riêng, không cần DAW. <strong><code>npm run plugin:install</code></strong> tạo symlink nó vào thư mục CLAP để bản dựng lại có hiệu lực ngay mà không phải sao chép.","changelog.d4a08bd89830":"<strong><code>vst3-sys</code> theo GPLv3</strong> và phần xuất VST3 của nih-plug liên kết với nó — điều lẽ ra đã khiến sản phẩm độc quyền này vi phạm giấy phép. Bị <code>cargo deny</code> bắt được. Giờ VST3 đến từ <code>clap-wrapper</code> (MIT). Chính VST3 SDK của Steinberg đã chuyển sang MIT vào tháng 11 năm 2025; nih-plug không dùng nó.","changelog.3c8bb13f96c1":"<strong>Thông báo lỗi khi tạo chưa bao giờ hiện ra được.</strong> <code>.stage__error</code> không có quy tắc CSS nào và nằm phía sau lớp FX, vốn là <code>position: absolute; inset: 0</code> phủ toàn bộ sân khấu.","changelog.e28adf2882ae":"<strong>Tempo ghim được kẹp</strong> trong dải 20–999 của Ableton Live ngay ở rìa IPC, và ô BPM chỉ nhận chữ số — <code>&lt;input type=&quot;number&quot;&gt;</code> nhận <code>e</code>, <code>E</code>, <code>+</code> và <code>-</code>, nên «1e5» từng là một tempo hợp lệ.","changelog.584e92185850":"<code>.github/workflows/{ci,release}.yml</code> từng không qua <code>format:check</code> trên <code>main</code>.","changelog.a2daa7b868f3":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-07-25\">2026-07-25</time></span>","changelog.a85f00dcce8a":"Giai đoạn 1: ứng dụng làm ra beat. Tìm một nghệ sĩ, nhấn Tạo, nghe nó, và kéo nó vào DAW.","changelog.e382399a54df":"Bộ dữ liệu phong cách được đóng gói cùng ứng dụng và nạp khi khởi động: mọi mô hình đều được phân tích, phân giải kế thừa và kiểm định trước khung hình đầu tiên, và danh mục được cung cấp cho giao diện qua các lệnh mới <code>roster_summary</code> và <code>resolve_model</code>. Một mô hình không hợp lệ được bỏ qua và báo lại chứ không bị coi là lý do để từ chối khởi động.","changelog.e2d9c9671a0f":"Bộ nhân hoá: swing kiểu MPC (từ 50% thẳng tới 66% chùm ba), các tầng lực nhấn cho trọng âm, cú đánh chính và nốt ghost, độ lệch thời gian theo từng làn tính bằng mili giây, và một cường độ lượng tử hoá quyết định bao nhiêu độ lệch đó được giữ lại. Swing uốn cả dòng thời gian, nên các roll viết ở độ phân giải mịn hơn đi theo đúng phách mà chúng thuộc về.","changelog.a6d5ebac7ba4":"Lõi của bộ tạo trống: ngữ pháp kick (anchor, mật độ, đảo phách, độ nghiêng tresillo, khoảng trống trước snare, các hình thức nhiều ô nhịp tường minh) và vị trí snare — half-time ở phách 3, backbeat 2-và-4, kiểu 3-rồi-4 hai ô nhịp của drill, và train beat của country — kèm snare ghost và một lớp clap chồng. Trap ra với snare ở phách 3; hình kick hai ô nhịp đã viết của UK drill được tái tạo chính xác ở mọi hạt giống.","changelog.24a70872e862":"Động cơ hi-hat: phân nhịp cơ bản (móc đơn, móc kép hoặc nhóm tresillo), mật độ fill, hi-hat mở đóng lại hi-hat nằm bên dưới chúng, một lớp thứ hai uốn cao độ và độ phồng dần qua một vòng lặp. Các phách và móc đơn nghịch phách mang trọng âm; các móc kép ở giữa lấp vào nhẹ nhàng.","changelog.22fd6d81f370":"Vốn từ roll: các roll hi-hat đổi phân nhịp (từ 1/16 tới 1/64, kể cả các lưới chùm ba), roll đặt ở cuối câu, trước snare và trước phách mạnh, dốc lực nhấn theo cả hai chiều, các chùm dồn, khoảng lặng và cụm lệch — cùng các thang roll snare với biến thể dồn-rồi-dừng và hai lớp, riser 8 ô nhịp và cụm lắp.","changelog.18c3919ac052":"Làn 808: nó bám theo kick theo tỉ lệ mà mô hình khoá hai phần với nhau, ngân legato từ nốt này sang nốt kế, lấy nốt gốc từ tông của phiên, và trượt theo các quãng mà mô hình liệt kê — được viết thành các nốt chồng lên nhau mà sampler đọc như portamento. 808 của UK drill dừng dưới tiếng snare; 808 của trap thì ngân xuyên qua.","changelog.50975022f50f":"Fill ở ranh giới câu nhạc: một biến tấu nhỏ mỗi hai ô nhịp, một biến tấu lớn hơn mỗi tám ô, và một fill ở ô nhịp cuối để vòng lặp dẫn tới đâu đó thay vì dừng cụt. Fill chiếm phần cuối ô nhịp của nó và giữ nguyên backbeat — cùng các nốt ghost.","changelog.ee8737dc4dcf":"Thêm mười hai khuôn mẫu thể loại: Chicago và NY drill, plugg và pluggnb, jerk, phonk, west-coast club, boom bap, R&amp;B thập niên 2000, liquid drum &amp; bass, train beat của country và pop thập niên 2000 — tổng cộng mười lăm, mỗi cái có một bài kiểm thử khẳng định ngữ pháp làm nên thể loại đó. Giờ mô hình có thể nói 808 của mình là staccato thay vì legato, rằng mình hoàn toàn không có 808, và rằng fill của mình xoay vòng trên tiếng clap.","changelog.0015d2f49d55":"Ảnh chụp chuẩn về tính tất định: một hạt giống, mô hình và phiên cố định giờ tạo ra JSON mẫu và MIDI giống hệt từng byte, được ghim bằng các ảnh chụp đã commit. Đó là điều biến lời hứa của chip hạt giống — dán một hạt giống, có lại cùng beat — thành một sự bảo đảm thay vì một ý định.","changelog.8ce8ea96f2f6":"Tạo và xuất đã dùng được từ ứng dụng: <code>generate_pattern</code> chạy một mô hình phong cách qua bộ tạo trống và bộ nhân hoá rồi trả lại mẫu, còn <code>export_midi</code> ghi nó vào thư mục phiên dưới dạng tệp MIDI type-0. Một yêu cầu có thể ghim tempo, tông, âm giai, swing, số ô nhịp hoặc cảm giác half-time; thứ gì không được ghim là lựa chọn của chính mô hình, và bỏ trống hạt giống sẽ chọn một hạt giống mới tái tạo chính xác kết quả.","changelog.599338a80b32":"Mười mô hình nghệ sĩ chủ lực dựng trên các nền thể loại — Metro Boomin, Southside, Pierre Bourne, OsamaSon, Nettspend, Summrs, Pop Smoke, Travis Scott, Future và Drake — mỗi người đều có tên gọi khác để tìm, kèm một bài kiểm thử rằng ai trong số họ cũng tạo ra thứ mà thể loại cha của họ không tạo ra.","changelog.b4c20dcbec08":"<strong>Ứng dụng làm ra beat.</strong> Tìm một nghệ sĩ, nhấn Tạo, và mẫu hiện ra trên lưới trống; nhấn Phát là bạn nghe thấy; kéo nó vào DAW hoặc xuất ra một thư mục. Tìm kiếm mờ và dễ dãi — «osa» ra OsamaSon, «drizzy» ra Drake, gõ sai vẫn trúng — chỉ cần bàn phím: ↑↓ để di chuyển, Enter để chọn, Esc để đóng.","changelog.4ffc65702fcb":"Phát lại: một động cơ âm thanh thời gian thực với bộ kit nghe thử được tổng hợp, sắp xếp chính xác tới từng sample, lặp vòng, vạch phát chạy theo, và một bộ limiter để một mẫu dày đặc không bao giờ làm vỡ đầu ra. Một máy không có card âm thanh vẫn tạo và xuất được, và nói rõ vì sao không phát được thay vì lặng lẽ thất bại khi nhấp.","changelog.2a7f05d53d42":"Hạt giống được hiển thị sau mỗi lần tạo và có thể dán lại để có lại đúng beat đó.","changelog.e948705bc342":"Một gợn sóng tạo nhạc quét qua lưới trong lúc mẫu được dựng, để beat tràn tới thay vì chớp một cái là hiện ra, và bừng sáng nhất ở đúng chỗ các nốt rơi xuống. Bật cài đặt giảm chuyển động của hệ thống sẽ thay nó bằng một lần chuyển mờ ngắn — ngay lập tức, không cần khởi động lại.","changelog.7f96e11b8d6b":"Giờ Cài đặt cho biết khi nào một mô hình phong cách bị bỏ qua lúc khởi động, kèm tệp và lý do. Một mô hình bị bỏ qua là một nghệ sĩ bị thiếu, và cho tới nay chỉ có console từng nhắc tới chuyện đó.","changelog.62ce473bf733":"Rút audio interface ra giữa phiên không còn khiến ứng dụng lặng lẽ bị điếc. Nó báo thiết bị đã mất, tự mở lại một thiết bị ngay khi có cái để mở — thử lại bao lâu cũng được — và báo khi thiết bị trở lại. Phát lại không tự chạy lại; nhấn phát thì lại chạy, và đó chính là thứ từng ngừng hoạt động.","changelog.1d647238b180":"Một cài đặt <strong>Giảm chuyển động</strong> trong mục Diện mạo, dành cho những máy mà hệ thống không có tuỳ chọn như vậy, hoặc cho ai muốn mọi thứ khác vẫn chuyển động còn riêng thứ này đứng yên. Nó có hiệu lực ngay khi được đánh dấu.","changelog.1b03300b577b":"MIDI xuất ra giờ mang hoá biểu. Đó là trường phiên duy nhất mà tệp chưa mô tả, nên một clip vào dự án mà không cho biết 808 của nó ở tông nào. Một điệu thức được ghi thành giọng trưởng hoặc thứ song song của nó, đó là tất cả những gì định dạng này nói được. <strong>Các ảnh chụp chuẩn <code>.mid</code> đã được tạo lại vì điều này</strong>: sáu byte mỗi tệp, đúng sự kiện meta mới và không gì khác — JSON mẫu không bị động tới.","changelog.ef6c13561f1f":"Giờ một cú slide 808 có thể vươn tới một quãng tám trên nốt xuất phát thay vì bị gập trở lại trong âm vực của mô hình. Một cú glide quãng tám — dấu ấn của phonk — trước đây rơi trúng chính nốt gốc của nó và bị loại bỏ.","changelog.eba636f4a895":"Bước phân giải kế thừa không còn sao chép toàn bộ mô hình tích luỹ ở mỗi bước của chuỗi, nhờ đó việc nạp 1.000 mô hình giảm từ 330 ms xuống 219 ms — nằm trong ngân sách khởi động 300 ms.","changelog.a287a4382167":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-07-22\">2026-07-22</time></span>","changelog.221bea271dc0":"Bản dựng đầu tiên được gắn tag: nền móng Giai đoạn 0. Lớp vỏ Studio, động cơ tạo nhạc thuần tuý, bộ dữ liệu mô hình phong cách và toàn bộ xương sống CI đã vào vị trí; bản thân các bộ tạo sẽ đến ở Giai đoạn 1, nên thanh điều khiển phát và nút Tạo được cố ý vô hiệu hoá thay vì giả vờ hoạt động.","changelog.44d12397d83d":"Lớp vỏ Tauri v2 + React + TypeScript trên một Cargo workspace, với crate <code>engine</code> thuần tuý (không kiểu Tauri, không mạng, không <code>unsafe</code>).","changelog.22cecd1d88c2":"Bố cục studio: thanh bên trái, sáu thẻ bộ tạo, sân khấu lưới, thanh bên phải và thanh điều khiển phát, mỗi bảng đều thu gọn được độc lập và trạng thái được lưu lại.","changelog.6c76ad6437f8":"Giao diện tối và sáng, độ tương phản đều được kiểm chứng theo WCAG 2.1 AA ở cả hai.","changelog.654cc0ec749e":"Lõi động cơ: <code>Pattern</code>/<code>Note</code>/<code>Lane</code>/<code>Song</code>, <code>SessionContext</code>, và RNG ChaCha8 có hạt giống với việc suy ra dòng theo từng miền, để tung lại một phần thì mọi phần khác vẫn giống hệt từng byte.","changelog.b59482b3b460":"Bộ dữ liệu phong cách: JSON Schema, hợp nhất sâu theo kế thừa có phát hiện vòng lặp, các lint ngữ nghĩa, và ba khuôn mẫu thể loại đầu tiên — trap, uk-drill, rage.","changelog.d7edc4251d89":"CLI <code>datasetc</code> — kiểm định, lint, thống kê, độ phủ.","changelog.3305f4e20d1f":"Trình báo sập theo chuẩn Havoc: phải tự chọn bật, đã lược sạch dữ liệu, không bao giờ gửi đi khi chưa có một cú nhấp.","changelog.179fa09246b2":"CI trên ba hệ điều hành, các cửa kiểm chuỗi cung ứng, và danh sách cấm phụ thuộc AI/mạng.","changelog.c8dd551642f8":"Kiểm thử E2E bằng Playwright chạy trên <code>vite dev</code>, với IPC được giả lập tại một đường nối duy nhất.","changelog.723cf83ffaea":"Cửa sổ không viền với các nút thu nhỏ / phóng to / đóng riêng, tiêu đề căn giữa, và kéo để đổi kích thước ở cả tám cạnh.","changelog.3fb0f4c44595":"Cài đặt và Giới thiệu, mở được từ thanh tiêu đề, kèm tuỳ chọn khay hệ thống (thu nhỏ xuống khay và đóng xuống khay, cả hai mặc định tắt).","changelog.a03b8762dc6b":"Trình báo lỗi và trình cập nhật theo chuẩn Havoc.","changelog.671f83dcff8b":"<strong>Mười tám ngôn ngữ</strong> — tiếng Anh cùng tiếng Ả Rập, tiếng Trung (Giản thể), tiếng Hà Lan, tiếng Pháp, tiếng Đức, tiếng Hindi, tiếng Indonesia, tiếng Ý, tiếng Nhật, tiếng Hàn, tiếng Ba Lan, tiếng Bồ Đào Nha (Brazil), tiếng Nga, tiếng Tây Ban Nha, tiếng Thổ Nhĩ Kỳ, tiếng Ukraina và tiếng Việt. Chuyển đổi tức thì, được ghi nhớ, và tiếng Ả Rập lật gương toàn bộ bố cục.","changelog.331da1149c6a":"<strong>Noto ở khắp nơi</strong>, đóng gói sẵn: 546 kiểu chữ phủ CJK, Ả Rập, Do Thái, các hệ chữ Ấn Độ, Thái, Khmer, Gruzia, Armenia, Ethiopia và hơn nữa, để không ngôn ngữ nào phải quay về dùng phông nào mà máy tình cờ có. Không có gì được tải về lúc chạy — ứng dụng vẫn không gửi yêu cầu mạng nào ngoài việc kiểm tra cập nhật.","changelog.6cfc2a93f8cf":"CI chụp lại ứng dụng đang chạy trên cả ba hệ điều hành, cùng hộp thoại Cài đặt ở mọi ngôn ngữ, dưới dạng artifact tải về được. Ảnh chụp trên macOS chưa đầy đủ và job ghi rõ điều đó (xem Live-To-Do).","changelog.a3c71b90162b":"Giới hạn đã biết","changelog.c2fce6ca915a":"Các bộ tạo, phát lại và xuất âm thanh chưa được triển khai; các nút điều khiển của chúng bị vô hiệu hoá thay vì bấm mà không có tác dụng.","changelog.82af19f3d55a":"Kéo ra gốc đã được dựng nhưng <strong>chưa được kiểm chứng với DAW thật</strong> — đó là cửa quyết định của Giai đoạn 0 và nó cần một con người.","changelog.58fced7db00c":"Menu khay hệ thống (Show / Quit) chưa được dịch.","changelog.169051a58b53":"Các trình cài đặt chưa được ký: hãy chuẩn bị gặp SmartScreen trên Windows và Gatekeeper trên macOS. Xem ghi chú phát hành để biết các bước cho từng nền tảng."};
